window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_007"]={"n":"玄烨","dyn":"清","poems":[{"t":"菩萨顶","f":"七言绝句","c":["四十余年礼世伽，本来面目是天家。","清凉无物何所有，叶斗峰横问法华。"]},{"t":"热河三十六景诗 其九 四面云山","f":"五言古诗","c":["殊状崔嵬里，兰衢入好诗。","远岑如竞秀，近岭似争奇。","雨过风来紧，山寒花落迟。","亭遥先得月，树密显高枝。","潮平无涌浪，雾净少多岐。","脉脉金明液，溶溶积翠池。","常忧思解愠，乐志馀清悲。","素学臣邻老，耆年自不知。"]},{"t":"览贞观政要","f":"五言古诗","c":["春阳淑以嘉，流云洒几案。","及此听政馀，缣缃获披玩。","寥寥三古后，载籍亦炳焕。","俯仰千年馀，盛治数贞观。","修德偃干戈，措刑空狴犴。","海外奉车书，臣民登燕衎。","事往迹尚存，流风照觚翰。","洋洋四十篇，可以一辞贯。","仁义有明效，非由事击断。","鄙哉封伦言，相去邈河汉。"]},{"t":"登景忠山","f":"七言律诗","c":["景忠远上日方阑，岩壑层层生早寒。","岭腹冻云凝玉仗，山中瑞气接仙鸾。","鸣钟涧里经声近，击鼓楼前树影残。","缭绕旌旗萦石道，六龙行处万民观。"]},{"t":"时巡近郊悯农事有作","f":"五言古诗","c":["芳郊景物丽，淑气扇暮春。","灵雨应良节，光风薄嘉辰。","省耕已届候，夙驾方来巡。","前驱列式道，羽卫罗钩陈。","时有田间子，荷耒披车尘。","讥诃勿频数，疾苦当咨询。","千耦幸终亩，二釜犹悬囷。","穮蓘尔勤动，痌瘝予隐亲。","赒赐出泉府，拊循属官臣。","行潦有挹器，冽井无枯津。","所惠良未遍，嗛嗛愧斯人。"]},{"t":"滇平","f":"七言律诗","c":["洱海昆池道路难，捷书夜半到长安。","未矜干羽三苗格，乍喜征输六诏宽。","天末远收金马隘，军中新解铁衣寒。","回思几载焦劳意，此日方同万国欢。"]},{"t":"升平嘉宴同群臣赋诗用柏梁体","f":"七言古诗","c":["丽日和风被万方。","卿云烂熳弥紫阊。","一堂喜起歌明良。","止戈化洽民物昌。","蓼萧燕誉圣恩长。","天心昭格时雨旸。","丰亨有兆祝千箱。","礼乐文章仰圣皇。","庙谟指授靖八荒。","春回丹诏罢桁杨。","河清海晏禹绩彰。","百度胥饬纲纪张。","千官济济盈岩廊。","天工无旷勤赞襄。","有年歌协臣所望。","共期红朽答殊常。","转漕亿万充天仓。","邦礼叨赞惭趋跄。","职司寅清佐垂裳。","天河洗甲通蛮乡。","皇威四畅咸来王。","祗承钦恤和气翔。","刑措不用民寿康。","八材庀化师殳斨。","右平左墄开明堂。","仰窥神策驱天狼。","膏以大泽人胥庆。","帝庸作歌追虞唐。","身依云汉赓天章。","恪秉训厉敦羔羊。","奉宣仁风之吴疆。","九阍詄荡瞻龙光。","斗杓高掩贯索芒。","图列养正亲羹墙。","黄钟大镛谐祯祥。","郊衢击壤欢丰穰。","大官珍膳罗酒浆。","调闲六御腾康庄。","忝预风纪凛清霜。","出入玉佩声锵锵。","纳言惟允尚职详。","褒忠励节感赐觞。","圜扉阒寂春草芳。","拜手好生颂禹汤。","前星令望钦颙卬。","终始念典用斯臧。","言模行范煇缥缃。","猗欤至德日就将。","叨尘侍从恩莫量。","靖共夙夜无怠遑。","梧桐生矣于高冈。","紬书东观翰墨香。","三德六行为士坊。","宫官备位滋悚惶。","六经义叶如笙簧。","奎文焕若森琳琅。","朝朝橐笔侍御床。","纪载圣治金匮藏。","频年宣室虚对扬。","宸篇掞藻烛昊苍。","承华毓德成圭璋。","青宫琪树栖鸾凰。","金舆导从骖云骧。","罘罳流影耀璧珰。","仁波溟渤同濊汪。","鸾旂乘春零露瀼。","爰赓天保矢勿忘。","八表同轨来梯航。","云门磬管声喤喤。","泰交天阙开春阳。","惟睿作圣金玉相。","珥笔何幸日月傍。","瑞逾宝鼎兼芝房。","尧樽夜醉星低昂。","在廷悦豫和宫商。","滥典乐正董上庠。","治登三五休声飏。","睿谟典诰同洋洋。","记神圣功臣职当。","琅函瑶版书焜煌。","石渠高议芟秕糠。","日侍清禁研铅黄。","愿言直节谨自防。","帝心勤民重农桑。","具举细目恢宏纲。","诞敷文德四国匡。","嘉禾既殖锄莠稂。","屈轶朱草纷两厢。","封章问夜检皂囊。","拟将劲操坚苍筤。","朝无阙事联班行。","千门燎火宵未央。","升平高宴迈柏梁。"]},{"t":"再游盘山","f":"七言古诗","c":["蓟州城北黄崖前，水甘土厚多平阡。","崇山特起矗霄汉，栝柏夹路阴参天。","回峦复嶂倍娟秀，幽林邃谷时夤缘。","云藏古寺行未到，树杪先有钟声传。","数峰突兀势陡绝，上迫箕尾双星躔。","峨峨石状兽蹲立，因风摇曳如空悬。","深潭清冷那可测，知是百尺神龙渊。","钵泉恍惚有海眼，潮井呼噏通百川。","不然泛滥亦易挹，何为万古清涓涓。","神工融结天巧凿，更骋远目穷高巅。","渔阳古郡最阻阨，屹为左辅雄幽燕。","即今交河远置候，此实堂奥非临边。","太平粗喜有端绪，石根沙碛皆原田。","偶兹登陟聊驻旆，用寄襟抱题斯篇。"]},{"t":"娑罗树歌","f":"七言古诗","c":["娑罗珍木不易得，此树惟应月中植。","想见初从西域移，山中有人多未识。","海桐结蕊松栝形，千花散尽七叶青。","山禽回翔不敢集，虚堂落子风泠泠。","楚州遗碑今已偃，峨眉雪外双林远。","未若兹山近可游，灵根终古蟠层巘。","繁阴亭午转团圞，回睇精蓝路几盘。","凭教紫府仙山树，写入披香殿里看。"]},{"t":"赐施烺诗","f":"五言律诗","c":["岛屿全军入，沧溟一战收。","降帆来蜃市，露布彻龙楼。","上将能宣力，奇功本伐谋。","伏波名共美，南纪尽安流。"]},{"t":"晓发虚谷","f":"七言绝句","c":["帷宫雨后纳新凉，虚谷风来百草香。","万里晴云任舒卷，凭高但见碧天长。"]},{"t":"谒大禹庙","f":"五言律诗","c":["古庙青山下，登临晓霭中。","梅梁存旧迹，金简纪神功。","九载随刊力，千年统绪崇。","兹来荐蘩藻，瞻对率群工。"]},{"t":"无锡小民以羔羊惠酒争献御舟笑而遣之","f":"七言绝句","c":["自昔君门隔九阍，如何草野得攀援。","多因爱此元元切，忘分公然学负暄。"]},{"t":"经明成祖勒铭处指示扈从诸臣","f":"五言古诗","c":["伊昔永乐年，征马嘶朔风。","碛间铭片石，苔藓磨青铜。","我行初拂拭，夏节欣相同。","当时月在已，今值清和中。","后先间两日，彼亦一代雄。","我武讨不庭，春发明光宫。","塞草绿微茁，雨雪阴濛濛。","或言时尚早，稍待边花红。","宁知英杰人，所见良疏通。","迅行掩不备，兵法贵折冲。","军谋在帷殿，士气如虎熊。","岂不资群策，惟断斯有功。","作诗纪其事，聊以示臣工。"]},{"t":"渡克鲁伦河网鱼暂驻待后军至","f":"七言古诗","c":["胪朐河水何泱泱，高山发源清且长。","漠北经流数千里，东趋辽海归扶桑。","夙昔河壖亦沃土，狡寇来据巢其疆。","自春徂夏雨泽断，塞草不绿川原黄。","惊闻我师自天来，远渡沙碛思遁藏。","焚巢裹糇夜窜走，老羸稚幼委道傍。","朕率轻骑渡河北，平沙浅水湔甲裳。","命士举网截清流，鲜鳞泼剌河中央。","笑彼智短气复懦，捐弃形势奔仓皇。","此时中宵自颠沛，当年北鄙徒披猖。","我师英武且整暇，临河饮马皆鹰扬。","黄钺一麾诸部集，回首万骑方腾骧。"]},{"t":"过阙里","f":"五言律诗","c":["鸾辂来东鲁，先登夫子堂。","两楹成俎豆，数仞见宫墙。","道统唐虞接，儒宗洙泗长。","入门抚松柏，瞻拜肃冠裳。"]},{"t":"松花江网鱼最多颁赐从臣","f":"七言古诗","c":["松花江水深千尺，捩柁移舟网亲掷。","溜洄水急浪花翻，一手提网任所适。","须臾收处激颓波，两岸奔趋人络绎。","小鱼沈网大鱼跃，紫鬣银鳞万千百。","更有巨尾压船头，载以牛车输欲折。","水寒冰结味益佳，远笑江南夸鲂鲫。","遍令颁赐扈从臣，幕下然薪递烹炙。","天下才俊散四方，网罗咸使登岩廊。","尔等触物思比托，捕鱼勿谓情之常。"]},{"t":"弹琴峡","f":"五言律诗","c":["琮琤流水意，彷佛似鸣琴。","曲度泉归壑，声兼峡泛吟。","空山传逸响，终古奏清音。","不御金徽久，泠泠会素心。"]},{"t":"瀚海","f":"五言律诗","c":["四月天山路，今朝瀚海行。","积沙流绝塞，落日度连营。","战伐因声罪，驰驱为息兵。","敢云黄屋重，辛苦事亲征。"]},{"t":"赐将士食","f":"五言律诗","c":["万骑拥雕弓，长鸣向北风。","龙荒弥旷远，虎旅正骁雄。","战鼓黄云外，旌门紫气中。","朕躬方蓐食，与尔六军同。"]},{"t":"剿灭噶尔丹大捷","f":"五言律诗","c":["残寇疲宵遁，横冲节制兵。","我师乘锐气，谁许丐馀生。","貔虎三军合，鲸鲵一战平。","愧称谋画定，讨罪荷天成。"]},{"t":"自宁夏出塞滨河行至白塔乘舟顺流而下抵湖滩河朔作","f":"七言古诗","c":["黄河之源难可穷，滔滔来自遐荒中。","既入洮兰复西出，飞涛浩瀚声淙淙。","来从边山远跋涉，遣师挽饷兼采风。","回銮欲假顺流便，特乘艇舰浮奔洪。","潆洄大野势几曲，沙岸颓突还巃嵷。","乱柳排生枝干密，中有巨鹿藏榛丛。","遥山转转行莫尽，忽前俄后迷西东。","有时塞云催急雨，晚天霁色横长虹。","旌门月上夜皎洁，水光直与银汉通。","放棹百里只瞬息，迅于走坂驰骏骢。","中霄望见旄头落，幕北已奏烟尘空。","兹行永得息兵革，岂惜晓暮劳予躬。","长河绵延古鲜历，巡阅乃与区域同。","自此寰海乐清晏，熙恬万国咸亨丰。"]},{"t":"己卯南巡视河工回跸","f":"七言绝句","c":["行遍江南水与山，柳舒花放鸟绵蛮。","明朝又入邳徐路，凤阙龙楼计日还。"]},{"t":"临城望","f":"七言绝句","c":["城高千仞卫山川，虎踞龙盘王气全。","车马遥看云雾里，民间休戚在当前。"]},{"t":"五十一年春二月二十四日回銮遇雨故作春雨行","f":"古风","c":["春雨难过时，春耕不可误。","江南苦多霪，河北厌久煦。","地湿易蒸云，土碱能散雾。","年年常觌此，惟祝顺旸雨。","纵然蒙天眷，更欲明三务。","去岁银花盈尺馀，今看滂沛满沟渠。","儿童应门有喜色，农夫奔走百愁舒。","忙布种，治畦蔬，山谷原隰免欷歔。","四民俯仰皆安业，庙堂忧悯当少除。","娱目怡心愿后乐，又虑夏秋苗何如。","仰冀阴晴无爽忒，方致大有登农书。"]},{"t":"饯闽抚陈瑸","f":"七言律诗","c":["留犊从来汉史传，建牙分阃赖官贤。","宽严驭吏须交勉，教养宜民务使全。","岭海屏藩消蜃气，关山保障息烽烟。","迎年节近新春至，援笔枫宸饯别篇。"]},{"t":"病中偶尔问及工部尚书翰林院掌院学士徐元梦乃同学旧翰林康熙十六年以前进士再无一人矣率赋一律以遣闷怀","f":"古风","c":["七旬彼此对堪怜，病里回思一慨然。","少小精神皆?尽，老年岁月任推迁。","常怀旧学穷经史，更想馀閒力简编。","诗兴不知何处至，拈毫又觉韵难全。"]},{"t":"朕自幼不喜厚味今年登古稀深知粗食软足以颐养天和有人进蒌蒿苦麻者因而书怀","f":"五言律诗","c":["淡泊生津液，清虚乐有馀。","鬓霜惭薄德，神惫恐高誉。","苦好山林趣，深耽性道书。","山翁多耄耋，粗食并园蔬。"]},{"t":"丰登者朕之获福歉收者朕之失政出此入彼不能自恕故作近体一律以自遣","f":"七言律诗","c":["喜雨人同我不然，鳃鳃宵旰待丰年。","千村时若千村庆，一日恒旸一日愆。","率土盈宁难并得，普天恩泽岂兼全。","先忧后乐何能遂，衰景残龄秖自怜。"]},{"t":"班师次拖陵","f":"七言绝句","c":["战马初閒甲士欢，挥戈早已破楼兰。","弥天星斗销兵气，照彻边山五月寒。"]},{"t":"巡幸子牙河建坝诗二首 其一","f":"七言律诗","c":["暂别宫槐幸子牙，近村处处少人家。","清和微署浮畦麦，绿树初荫接岸沙。","堤外草荒艰籽粒，淀中水浅捕鱼虾。","黄童白叟望霖雨，霖雨先施莫自赊。"]},{"t":"大城文安等处堤脩完舟中驻跸王家口","f":"五言律诗","c":["积水频萦虑，长堤幸已成。","桑麻连井邑，花柳近清明。","渐惬勤民意，还深问俗情。","兰桡经过处，布谷唤春耕。"]},{"t":"春","f":"五言绝句","c":["旭日含新淑，春光覆满屋。","东皇转岁华，融气杂山谷。"]},{"t":"春日郊行","f":"五言律诗","c":["春殿晴云绕，銮舆出禁闱。","桃花临紫陌，柳叶暗青旂。","宿雨能清跸，和风早拂衣。","马嘶驰道远，满地尽芳菲。"]},{"t":"玉泉春晓","f":"五言律诗","c":["郊墅初晴后，芳春曙色旋。","孤鸾堆画障，细穴吐新泉。","浪静鲜鳞跃，风恬紫菂妍。","怡情看万象，浩浩思无边。"]},{"t":"春日观花","f":"五言律诗","c":["枝上流莺早，千红万紫香。","气融催景丽，风过递年芳。","秾李花犹浅，垂杨叶未长。","涧中春溜发，疑是奏笙簧。"]},{"t":"景山春望","f":"七言律诗","c":["云霄千尺倚丹邱，辇下山河一望收。","凤翥中天连紫阙，龙蟠北极壮皇州。","烟生沆瀣春初丽，露湿芙蓉翠欲流。","却向闾阎看蔀屋，崇高还廑庙堂忧。"]},{"t":"后苑漫兴","f":"七言律诗","c":["佳气青葱绕苑墙，红泉紫岫胜云庄。","雕阑细草经春满，绮阁繁花入午香。","雨露生成随品类，鸢鱼飞跃自低昂。","閒亭久坐浑无事，静对琴书觉意长。"]},{"t":"春夜","f":"五言绝句","c":["玉炉烟霭尽，夜静百花香。","曙气浮丹陛，春光拂象床。"]},{"t":"春日","f":"七言绝句","c":["佳气山川浃地行，物随节候变初晴。","雪消树底花争发，冰泮池头草欲生。"]},{"t":"春晴舟中作","f":"七言绝句","c":["野水漫漫野岸长，几行嫩柳带斜阳。","不知春色来多少，但觉飞花处处香。"]},{"t":"元夜与诸王宴饮乾清宫","f":"五言律诗","c":["今夕丹帏宴，联翩集懿亲。","传柑宜令节，行苇乐芳春。","香泛红螺重，光摇绛蜡新。","不须歌湛露，明月足留人。"]},{"t":"春盘","f":"五言绝句","c":["小摘园中露，新香糁作羹。","岁和欣有兆，甘菜已春生。"]},{"t":"立春调寄太平时","f":"古风","c":["淑景维新爆竹声。","手调羹。","词臣载笔赋琼英。","学西凉。","凤阁龙楼昼渐长。","物资生。","劝官勉力尽升平。","竹马迎。"]},{"t":"春日内苑赐宴诗并序","f":"五言律诗","c":["春深内苑里，珍席宴群臣。","蝶向双檐舞，花飞复阁新。","和羹期上佐，调鼎协洪钧。","萧鼓欢无极，芳年醉此辰。"]},{"t":"途次逢寒食","f":"五言绝句","c":["何处来春风，澹荡开晴旭。","不见杏花红，才逢柳梢绿。"]},{"t":"清明","f":"七言绝句","c":["已日才从江岸行，舟中还复度清明。","上林闻道花迟发，留与归时听早莺。"]},{"t":"清明登玉泉山","f":"七言绝句","c":["寒食登高芳草青，泉声映柳出春亭。","心中怀得天然处，坐对沙鸥乐野汀。"]},{"t":"桥望","f":"五言绝句","c":["郊原浮麦气，池沼漾青蘋。","夏日临桥望，薰风处处新。"]},{"t":"夏日迎薰亭","f":"五言律诗","c":["苑启时初夏，亭阴午未阑。","雨过池藻碧，日绽海榴丹。","水木含清景，禽鱼得静观。","薰风能解愠，试取玉琴弹。"]},{"t":"夏日郊行","f":"五言律诗","c":["节变春方去，清和助麦秋。","蔚林乘早夏，茂草接新流。","柳絮堤边起，荷钱水上浮。","风光殊旧日，此意未曾休。"]},{"t":"初夏玉泉山二首 其一","f":"五言律诗","c":["别馆依丹麓，疏帘映碧莎。","泉声当槛出，花气入垣多。","路转溪桥接，舟沿石窦过。","薰风能阜物，藻景已清和。"]},{"t":"初夏玉泉山二首 其二","f":"五言律诗","c":["山翠引鸣镳，湖光漾画桡。","野云低隔寺，沙柳暗藏桥。","百啭黄鹂近，双飞白鹭遥。","今年农事早，时雨足新苗。"]},{"t":"夏日閒坐","f":"七言绝句","c":["云敛风微紫燕飞，春光已去夏初归。","清襟赢得天然处，暗觉花香到玉扉。"]},{"t":"午日","f":"五言律诗","c":["令序当重午，南台日正中。","玉阶鸣瀑水，瑶轸奏薰风。","菖叶浮杯绿，榴花照槛红。","临流看竞渡，转忆济川功。"]},{"t":"途次端午","f":"五言律诗","c":["蕤宾逢夏律，午日俯澄流。","黄鸟林中变，新蒲岸外稠。","宫筵传綵粽，仙酒泛丹榴。","遥忆蓬莱上，垂杨荫御沟。"]},{"t":"禁园秋霁","f":"五言律诗","c":["树冷催蝉咽，荷疏表影长。","深秋残暑气，微爽待高阳。","户外远尘迹，园中多蕙香。","溶溶新雨霁，吟乏愧成章。"]},{"t":"早秋新霁","f":"五言律诗","c":["卷幕过新雨，披襟纳好风。","馀霞明远岫，倒景射晴虹。","稼穑丰年足，乾坤爽气同。","高天云断处，历历见初鸿。"]},{"t":"立秋前一日晚同左右閒坐进鲜果","f":"七言律诗","c":["初到金风天气晚，微凉雨后画帘垂。","九重迥出白云远，三殿高临北斗移。","珍果满盘新献节，碧梧一叶报秋时。","漏深不寐题诗句，月色煇煌照凤墀。"]},{"t":"九日幸景山登高","f":"五言律诗","c":["秋色净楼台，登高紫禁隈。","千门鸣雁度，万井霁烟开。","翠拂銮舆上，云随豹尾来。","佳辰欣宴赏，满泛菊花杯。"]},{"t":"塞外初冬","f":"七言绝句","c":["阴山南去雁行多，渺渺沙原六御过。","报是初冬新律改，依然霜晓气暄和。"]},{"t":"途中长至","f":"七言绝句","c":["关塞经时跸未回，律逢葭琯暗飞灰。","遥知日晷添宫线，暖阁前头放早梅。"]},{"t":"赋得爆竹声中一岁除是日微雪","f":"七言律诗","c":["爆竹连宵不夜城，占年积素即丰盈。","维新四始全仁政，脩省三朝冀太平。","拂曙和风临上日，通晨淑气拥华清。","愿将柏叶芳樽酒，赐与臣邻共太羹。"]},{"t":"见途中夏麦将熟志喜","f":"七言绝句","c":["江浒淮壖道已周，归看东省麦盈畴。","雨滋膏润苗多秀，早庆今年大有秋。"]},{"t":"清明麦秀","f":"七言绝句","c":["清明前后麦花香，遍野氤氲映骕骦。","须认秋成春雨密，隔溪村落饮斜阳。"]},{"t":"秋日出郊观稼","f":"五言古诗","c":["秋气日寥迥，万象皆苍苍。","朝暾被渥露，草木含晶光。","西成方届候，农事将筑场。","于焉省敛穫，令典重百王。","轻轩屏前置，夙驾无严装。","郊原一以眺，烟树纷成行。","微风散深樾，清流抱回塘。","土脉秀且沃，篝车郁相望。","新䥥粲如月，刈此溪云黄。","捃拾复何幸，遗秉满道旁。","鸟雀互翔集，妇子咸悦康。","行将吹苇籥，报尔千斯箱。","眷言三时勤，艰难讵可忘。","茫茫视九壤，岂尽歌丰穰。","二釜苟不充，予饥惄如伤。","幸兹乐有年，时若雨与旸。","勖哉慎所丽，田功庶无荒。"]},{"t":"观苗无意到潭柘咏时景","f":"五言律诗","c":["昼永薰风至，清泉决决长。","芳年添景色，迟日换流光。","旧竹随堤发，新花满涧香。","观苗不觉晚，微雨点衣裳。"]},{"t":"入关见雨膏润泽禾苗茂遂喜而有作","f":"七言律诗","c":["甘雨时霖为洗兵，恰逢战胜武功成。","军容万队初旋凯，妇子千村正馌耕。","天意要荒同职贡，人欢闾井共升平。","征途每忆民生事，喜见桑麻惬此情。"]},{"t":"题耕图二十三首 其一 第一图","f":"七言绝句","c":["暄和节候肇农功，自此勤劳处处同。","早辨东田穜稑种，褰裳涉水浸筠笼。"]},{"t":"题耕图二十三首 其二 第二图","f":"七言绝句","c":["土膏初动正春晴，野老支筇早课耕。","辛苦田家惟穑事，陇边时听叱牛声。"]},{"t":"题耕图二十三首 其三 第三图","f":"七言绝句","c":["每当旰食念民依，南亩三时愿不违。","已见深耕还易耨，绿蓑青笠雨霏霏。"]},{"t":"题耕图二十三首 其四 第四图","f":"七言绝句","c":["东阡西陌水潺湲，扶耖泥涂未得閒。","为念饔飧由力作，敢辞竭蹶向田间。"]},{"t":"题耕图二十三首 其五 第五图","f":"七言绝句","c":["老农力穑虑偏周，早夜扶犁未肯休。","更驾乌犍施碌碡，好教春水满平畴。"]},{"t":"题耕图二十三首 其六 第六图","f":"七言绝句","c":["农家布种避春寒，甲坼初萌最可观。","自昔虞书传播谷，民间莫作等閒看。"]},{"t":"题耕图二十三首 其七 第七图","f":"七言绝句","c":["一年农事在春深，无限田家望岁心。","最爱清和天气好，绿畴千顷露秧针。"]},{"t":"题耕图二十三首 其八 第八图","f":"七言绝句","c":["从来土沃藉农勤，丰歉皆由用力分。","薙草洒灰滋地利，心期千亩稼如云。"]},{"t":"题耕图二十三首 其九 第九图","f":"七言绝句","c":["青葱刺水满平川，移植西畴更勃然。","节序惊心芒种迫，分秧须及夏初天。"]},{"t":"题耕图二十三首 其十 第十图","f":"七言绝句","c":["千畦水泽正瀰瀰，竞插新秧恐后时。","亚旅同心欣力作，月明归去莫嫌迟。"]},{"t":"题耕图二十三首 其十一 第十一图","f":"七言绝句","c":["丰苗翼翼出清波，荑稗丛生可若何。","非种自应芟薙尽，莫教稂莠败嘉禾。"]},{"t":"题耕图二十三首 其十二 第十二图","f":"七言绝句","c":["曾为耘苗结队行，更忧宿草去还生。","陇间馈馌频来往，劳勚田家妇子情。"]},{"t":"题耕图二十三首 其十三 第十三图","f":"七言绝句","c":["䆉稏盈畦日正长，复勤穮蓘下方塘。","堪怜曝背炎蒸下，惟冀青畴发紫芒。"]},{"t":"题耕图二十三首 其十四 第十四图","f":"七言绝句","c":["塍田六月水泉微，引溜通渠迅若飞。","转尽桔槔筋力瘁，斜阳西下未言归。"]},{"t":"题耕图二十三首 其十五 第十五图","f":"七言绝句","c":["满目黄云晓露晞，腰镰穫稻喜晴晖。","儿童处处收遗穗，村舍家家荷担归。"]},{"t":"题耕图二十三首 其十六 第十六图","f":"七言绝句","c":["年谷丰穰万宝成，筑场纳稼积如京。","回思望杏瞻蒲日，多少辛勤感倍生。"]},{"t":"题耕图二十三首 其十七 第十七图","f":"七言绝句","c":["南亩秋来庆阜成，瞿瞿未释老农情。","霜天晓起呼邻里，遍听村村打稻声。"]},{"t":"题耕图二十三首 其十八 第十八图","f":"七言绝句","c":["秋林茅屋晚风吹，杵臼相依近短篱。","比舍舂声如和荅，家家篝火夜深时。"]},{"t":"题耕图二十三首 其十九 第十九图","f":"七言绝句","c":["谩言嘉谷可登盘，糠秕还忧欲去难。","粒粒皆从辛苦得，农家真作雨珠看。"]},{"t":"题耕图二十三首 其二十 第二十图","f":"七言绝句","c":["作苦三时用力深，簸扬偏爱近风林。","须知白粲流匙滑，费尽农夫百种心。"]},{"t":"题耕图二十三首 其二十一 第二十一图","f":"七言绝句","c":["经营阡陌苦胼胝，艰食由来念阻饥。","且喜稼成登石硙，从兹鼓腹乐雍熙。"]},{"t":"题耕图二十三首 其二十二 第二十二图","f":"七言绝句","c":["仓箱顿满各欣然，补葺牛牢雨雪天。","盼到盖藏休暇日，从前拮据已经年。"]},{"t":"题耕图二十三首 其二十三 第二十三图","f":"七言绝句","c":["东畴举趾祝年丰，喜见盈宁百室同。","粒我烝民遗泽远，吹豳击鼓报难穷。"]},{"t":"畅春园观稻时七月十一日也","f":"七言绝句","c":["七月紫芒五里香，近园遗种祝祯祥。","炎方塞北皆称瑞，稼穑天工乐岁穰。"]},{"t":"桑林乍绿蚕事方兴诗以嘉之","f":"古风","c":["弥望桑林吐叶，垂枝嫩碧初匀。","竹舍正殷蚕务，天工雨露维均。"]},{"t":"岸侧桑叶初碧","f":"七言绝句","c":["夹岸青青绕御舟，浓桑初茁满村讴。","省方遍问蚕家苦，春雨连绵尽日忧。"]},{"t":"题织图二十三首 其一 第一图","f":"七言绝句","c":["豳风曾著授衣篇，蚕事初兴谷雨天。","更考公桑传礼制，先宜浴种向晴川。"]},{"t":"题织图二十三首 其二 第二图","f":"七言绝句","c":["柔桑初剪绿参差，陌上归来日正迟。","村舍家家帘幕静，春蚕新长再眠时。"]},{"t":"题织图二十三首 其三 第三图","f":"七言绝句","c":["红女勤劬日载阳，鸣鸠拂羽恰条桑。","只因三卧蚕将老，剪烛频看夜未央。"]},{"t":"题织图二十三首 其四 第四图","f":"七言绝句","c":["春深处处掩茅堂，满架吴蚕妇子忙。","料得今年收茧倍，冰丝雪缕可盈筐。"]},{"t":"题织图二十三首 其五 第五图","f":"七言绝句","c":["连宵食叶正纷纷，风雨声喧隔户闻。","喜见新蚕瑩似玉，灯前检点最辛勤。"]},{"t":"题织图二十三首 其六 第六图","f":"七言绝句","c":["爱逢晴日映疏帘，新绿如云叶渐添。","天气晴和蚕事广，移筐分箔遍茅檐。"]},{"t":"题织图二十三首 其七 第七图","f":"七言绝句","c":["桑田雨足叶蕃滋，恰是春蚕大起时。","负筥携筐纷笑语，戴鵀飞上最高枝。"]},{"t":"题织图二十三首 其八 第八图","f":"七言绝句","c":["频执纤筐不厌疲，久忘膏沐与调饥。","今朝士女欢颜色，看我冰蚕作茧时。"]},{"t":"题织图二十三首 其九 第九图","f":"七言绝句","c":["蚕性由来苦畏寒，深垂帘幕夜将阑。","炉头更爇松明火，老媪殷勤日探看。"]},{"t":"题织图二十三首 其十 第十图","f":"七言绝句","c":["自昔蚕缫重妇功，曾闻献茧在深宫。","披图喜见累累满，茅屋清光积雪同。"]},{"t":"题织图二十三首 其十一 第十一图","f":"七言绝句","c":["冰茧方堪作素纨，重绵亦藉禦深寒。","就中自有因材法，拣取筐间次第观。"]},{"t":"题织图二十三首 其十二 第十二图","f":"七言绝句","c":["一年蚕事已成功，历数从前属女红。","闻说及时还窖茧，荷锄又向绿阴中。"]},{"t":"题织图二十三首 其十三 第十三图","f":"七言绝句","c":["炊烟处处绕柴篱，翠釜香生煮茧时。","无限经纶从此出，盆头喜色动双眉。"]},{"t":"题织图二十三首 其十四 第十四图","f":"七言绝句","c":["蛾儿布子如金粟，水际分飞任所之。","莫令茧丝遗利尽，来年留作授衣资。"]},{"t":"题织图二十三首 其十五 第十五图","f":"七言绝句","c":["劳劳拜簇祭神桑，喜得丝成愿已偿。","自是西陵功德盛，万年衣被泽无疆。"]},{"t":"题织图二十三首 其十六 第十六图","f":"七言绝句","c":["绿阴掩映野人家，每到蚕时静不哗。","一自夏初成茧后，篱边新听响缫车。"]},{"t":"题织图二十三首 其十七 第十七图","f":"七言绝句","c":["从来蚕绩女功多，当念勤劳惜绮罗。","织妇丝丝经手作，夜寒犹自未停梭。"]},{"t":"题织图二十三首 其十八 第十八图","f":"七言绝句","c":["无衣卒岁早关情，寒气催人蟋蟀声。","茅屋疏篱秋夜永，短檠相对络丝成。"]},{"t":"题织图二十三首 其十九 第十九图","f":"七言绝句","c":["织纴精勤有季兰，牵丝分理制罗纨。","鸣机来往桑阴里，已作吴绡匹练看。"]},{"t":"题织图二十三首 其二十 第二十图","f":"七言绝句","c":["凝膏比洁络新丝，传得仙方色陆离。","一代文明资贲饰，须教五采备彰施。"]},{"t":"题织图二十三首 其二十一 第二十一图","f":"七言绝句","c":["巧样争传濯锦纹，堪怜织女最殷勤。","云章霞綵娱人意，自著寻常缟布裙。"]},{"t":"题织图二十三首 其二十二 第二十二图","f":"七言绝句","c":["手把齐纨冰雪清，秋衣欲制重含情。","逡巡莫谩施刀尺，万缕千丝织得成。"]},{"t":"题织图二十三首 其二十三 第二十三图","f":"七言绝句","c":["已成束帛又缝纫，始得衣裳可庇身。","自昔宫庭多浣濯，总怜蚕织重劳人。"]},{"t":"天花","f":"七言绝句","c":["灵山过雨万松青，朵朵缃云摘翠屏。","玉笈重缄敕飞骑，先调六膳进慈宁。"]},{"t":"邓尉山","f":"五言律诗","c":["邓尉知名久，看梅及早春。","岂因耽胜赏，本是重时巡。","野霭朝来散，山容雨后新。","缤纷开万树，相对惬佳辰。"]},{"t":"咏盆中松竹梅各一首 其三 梅","f":"五言绝句","c":["琼林遗玉骨，粉蕊趁冰姿。","香透芙蓉帐，诗成度玉墀。"]},{"t":"懋勤殿古干梅","f":"七言绝句","c":["宫梅先发上林枝，淡白含芳窈窕姿。","若待春风吹律暖，影随朝日乐雍熙。"]},{"t":"和唐太宗咏桃花即用原韵","f":"五言律诗","c":["苑里韶华满，春工试绮装。","霞轻笼树影，日暖散林光。","倚槛千丛锦，开帘百合香。","东风自骀宕，长护万年芳。"]},{"t":"雨后见梅花","f":"七言绝句","c":["新雨濛濛宜五沃，蒸霞始放见钱江。","初春锦绣铺千树，落日微吟坐北窗。"]},{"t":"点绛唇 前过江浙桃花已放今回銮至津门复见桃花盛开","f":"古风","c":["再见桃花，津门红映依然好。","回銮才到。","疑似两春报。","锦䌫仙舟，星夜盼辰晓。","情飘渺。","艳阳时袅。","不是垂杨老。"]},{"t":"咏画梨花","f":"五言古诗","c":["最爱梨花白，又惜同春老。","惟此画图中，冬夏长美好。","不令风雨摧，且无蜂蝶娆。","靓妆伴月容，尽在纸间造。","恶紫嫌夺朱，素体物难搅。","三品运胸中，六法生卉草。"]},{"t":"榴花","f":"五言绝句","c":["未结千房实，先开五月花。","红绡帘户下，疑似汉时槎。"]},{"t":"榴花","f":"五言绝句","c":["丹诚映白日，艳色喜清幽。","嫩绿疏棂外，开时傍翠楼。"]},{"t":"盆景榴花高有数寸开花一朵","f":"七言绝句","c":["小树枝头一点红，嫣然六月杂荷风。","攒青叶里珊瑚朵，疑是移根金碧丛。"]},{"t":"初秋幸西苑观荷命小船采莲","f":"五言律诗","c":["命驾来西苑，初秋向晚天。","芰荷池沼满，鸥鹭夕阳边。","频使移轻舫，时来献采莲。","离宫阑槛外，风动碧翩翩。"]},{"t":"千叶莲池夜闻雨滴之声","f":"七言律诗","c":["田田荷盖雨声齐，楼蕊缤纷向晚迷。","树叶不愁点翠幄，秧针岂忆灌青畦。","密林有意通宵响，茂草无知遍地萋。","偶尔喜吟今岁好，漫将诗句入新题。"]},{"t":"千叶莲","f":"七言律诗","c":["禁苑初秋玉殿凉，绿荷经濑递清商。","千英水面重重艳，几度风前柄柄香。","宫女移船摇绀叶，近臣载笔咏红芳。","定心坐对西山静，不管秾纤映夕阳。"]},{"t":"日讲毕同翰林张英高士奇励杜讷看荷","f":"七言绝句","c":["千队芙蓉太液池，迎薰初散讲筵时。","螭头绝胜金莲烛，自有清香送晓飔。"]},{"t":"夏燕新莲 其一","f":"七言绝句","c":["紫燕双双到案前，天教霖雨足禾田。","临窗斜掠莲花影，云与波光皆渺然。"]},{"t":"七夕观千叶莲","f":"七言绝句","c":["玉露初分水殿凉，满地红白杂芬芳。","香飘随座皆秋色，细月胧胧挂未央。"]},{"t":"咏各种牡丹","f":"五言律诗","c":["晨葩吐禁苑，花莳就新晴。","玉版参仙蕊，金丝杂绿英。","色含泼墨发，气逐彩云生。","莫讶清平调，天香自有情。"]},{"t":"忆畅春园牡丹","f":"古风","c":["晓雨疏疏薄洒，午风习习轻吹。","忽念畅春花事，正当万朵开时。"]},{"t":"畅春园众花盛开最为可观惟绿牡丹清雅迥常世所罕有赋七言绝以记之","f":"七言绝句","c":["碧蕊青霞压众芳，檀心逐朵韫真香。","花残又是一年事，莫遣春光放日长。"]},{"t":"玉兰","f":"七言绝句","c":["琼姿本自江南种，移向春光上苑栽。","试比群芳真皎洁，冰心一片晓风开。"]},{"t":"咏杜鹃花赐高士奇","f":"七言绝句","c":["石岩如火本天台，秀质丹心日月催。","移根禁苑清诗句，朱夏山林惜茂才。"]},{"t":"秋兰","f":"五言律诗","c":["猗猗秋兰色，布叶何葱青。","爱此王者香，著花秀中庭。","幽芬散缃帙，静影依疏棂。","岂必九畹多，侈彼离骚经。"]},{"t":"云栖竹树甚茂幽兰满山","f":"五言律诗","c":["山径纡徐合，溪声到处闻。","竹深阴戛日，木古势干云。","倚槛听啼鸟，攀崖采异芬。","韶华春已半，万物各欣欣。"]},{"t":"咏幽兰","f":"七言绝句","c":["婀娜花姿碧叶长，风来难隐谷中香。","不因纫取堪为佩，纵使无人亦自芳。"]},{"t":"九日对菊","f":"五言绝句","c":["不与繁花竞，寒苞晚更香。","数茎偏挺秀，嘉尔傲风霜。"]},{"t":"见案头水仙花偶作二首 其一","f":"七言绝句","c":["翠帔缃冠白玉珈，清姿终不污泥沙。","骚人空自吟芳芷，未识凌波第一花。"]},{"t":"见案头水仙花偶作二首 其二","f":"七言绝句","c":["冰雪为肌玉鍊颜，亭亭如立藐姑山。","群花只在轩窗外，那得移来几案间。"]},{"t":"柳梢青 咏岭外金莲盛放可爱","f":"古风","c":["万顷金莲。","平临难尽，高眺千般。","珠蹙移花，翠翻带月，无暑神仙。","俗人莫道轻寒。","悠雅处、馀香满山。","岭外磊落，远方隐者，谁似清闲。"]},{"t":"山菊蓝雀花","f":"五言绝句","c":["雨过初凉至，山花遍野馨。","虽无红紫艳，能使属车停。"]},{"t":"樱桃","f":"七言绝句","c":["禁籞朱樱晓露匀，不须驿骑拂红尘。","芙蓉未赐千官会，寝庙春残早荐新。"]},{"t":"樱桃","f":"七言绝句","c":["初夏含桃味早全，西山结实弱枝连。","赤瑛充荐休言过，丹色浓浓众果先。"]},{"t":"咏林檎","f":"七言绝句","c":["野果初来上苑东，紫红鲜品进离宫。","虽然不及群珍味，也有微诚在此中。"]},{"t":"元旦","f":"五言绝句","c":["广廷扬九奏，玉帛丽朝光。","恭已临四表，垂衣驭八荒。"]},{"t":"上元","f":"五言绝句","c":["月华连昼色，灯火杂星辰。","彩仗移双阙，琼筵会大臣。"]},{"t":"慈宁宫问太皇太后安","f":"七言绝句","c":["定省深宫曙气催，承恩献寿捧霞杯。","晨昏敬睹慈颜豫，不尽欢欣踊跃回。"]},{"t":"月","f":"七言绝句","c":["影送楼台照水明，金波荡漾远含清。","西山色净云初散，南苑风和令正行。"]},{"t":"昭仁殿","f":"五言绝句","c":["雕梁双凤舞，画栋六龙飞。","崇高惟在德，壮丽岂为威。"]},{"t":"赐旧时讲学","f":"七言绝句","c":["几前烛下长谈论，今日忽为垂老人。","怜尔林泉安淡薄，因思畴昔侍枫宸。"]},{"t":"赐抚远大将军图海二首 其一","f":"七言绝句","c":["两朝密勿重元臣，秉钺登坛西定秦。","钟鼎功名悬日月，丹青事业画麒麟。"]},{"t":"赐抚远大将军图海二首 其二","f":"七言绝句","c":["威名万里作长城，壁垒旌旗壮远征。","绥靖边陲驰露布，凯旋立奏泰阶平。"]},{"t":"夜半","f":"五言绝句","c":["览书银蜡短，观象玉衡长。","夜半无穷意，心为念万方。"]},{"t":"琴","f":"五言古诗","c":["峄阳桐百尺，斲为凤凰琴。","调丝坐石上，宛若松风吟。","希音合太古，贵以鍊予心。"]},{"t":"晚春游幸感怀","f":"五言绝句","c":["岸花芳且落，树木含春光。","思赏肠应断，长怀万古伤。"]},{"t":"河","f":"七言绝句","c":["春风野水秾花发，一道帆樯带柳烟。","影动长桥横螮蝀，岸铺芳草近南川。"]},{"t":"白洋湖","f":"五言绝句","c":["遥看白洋水，帆开远树丛。","流平波不动，翠色满湖中。"]},{"t":"船猎","f":"五言绝句","c":["万人齐指处，一鸟落晴空。","携琴鼓棹返，乐与大臣同。"]},{"t":"水村","f":"五言绝句","c":["孤村绿塘水，旷野起春云。","槐柳胜南苑，青莎有鹭群。"]},{"t":"鄚州河道","f":"五言绝句","c":["藻密行舟涩，湾多转楫频。","帆悬风正处，烟火近通津。"]},{"t":"喜雨","f":"七言绝句","c":["暮雨霏微过凤城，飘飘洒洒重还轻。","暗添芳草池塘色，远慰深宫稼穑情。"]},{"t":"赐宁古塔将军巴海诗","f":"七言律诗","c":["夙简威名将略雄，高牙坐镇海云东。","旌麾到处销兵气，壁垒开时壮武功。","尽使版图归化日，远教边徼被皇风。","酬勋世锡丹书重，勉尔长思报国忠。"]},{"t":"郊外即事","f":"五言绝句","c":["初蝉鸣暑气，雀噪满林枝。","蜂蝶花间舞，有情人不知。"]},{"t":"郊外偶作","f":"七言绝句","c":["乳燕衔泥花影静，鸣鸠唤雨树林深。","豫游不独题诗意，要识熙熙暤暤心。"]},{"t":"马上口占","f":"七言绝句","c":["夏日桥头望远山，儿童戏水水潺潺。","烟云数里方知异，野树汀花白昼閒。"]},{"t":"复道口占","f":"五言绝句","c":["深深复道远，停辇问宫官。","内苑薰风起，榴花满御阑。"]},{"t":"夏日登景山同翰林张英高士奇作","f":"七言绝句","c":["日暮登山览八荒，翰林随辇进辞章。","君臣同乐松阴下，时雨将来入未央。"]},{"t":"夜静读书","f":"七言绝句","c":["九重夜静御炉香，坟典披观意味长。","为念兆民微隐处，孜孜不怠抚遐荒。"]},{"t":"内厩阅马","f":"七言绝句","c":["龙种齐嘶御厩旁，追风逐日似飞翔。","蹋尘不染凌霄志，个个真堪号骕骦。"]},{"t":"夏日同大学士明珠暨诸侍卫过黑龙潭途中作","f":"七言绝句","c":["骏马骎骎蹋绿蘋，羽旗豹尾映龙鳞。","暑中荷锸方知苦，停辇观苗问稼人。"]},{"t":"黑龙潭","f":"五言绝句","c":["暗通山下草，流出涧边花。","空潭深静处，洒翰动龙蛇。"]},{"t":"由广泉寺至卧佛寺","f":"七言绝句","c":["岩边青竹低临水，云外岚峰半入天。","僧舍无人常寂寂，山门洄绕是寒泉。"]},{"t":"山寺晚景","f":"五言绝句","c":["岸积青苔厚，藤抽紫蔓长。","徘徊风景异，玩赏对斜阳。"]},{"t":"咏卧佛寺古树","f":"七言绝句","c":["乔木婆娑阴正肥，夕阳相对岭崔巍。","薰风拂树凉云起，暮景苍然送辇归。"]},{"t":"驻跸碧云寺","f":"五言律诗","c":["山寺通幽境，莺啼绿树枝。","幡虹迎玉辇，刹凤驻云旗。","翠麓三乘辟，佳辰万骑宜。","松阴辉落景，游豫近臣知。"]},{"t":"碧云寺临泉望月","f":"七言绝句","c":["碧云夜望月初圆，星斗辉煌照九天。","滴溜涓涓无止息，此心长使若清泉。"]},{"t":"碧云晓起","f":"七言绝句","c":["山中晓起听蝉鸣，遥对峰岑霁色清。","洞壑有年奇树老，梦回疑是在蓬瀛。"]},{"t":"再赋碧云晓景","f":"五言绝句","c":["夏早日方长，南风草木香。","清凉飘御扇，荒刹得恩光。"]},{"t":"洪光寺盘道","f":"五言绝句","c":["白云飞夏日，斜径尽崎岖。","仙阜崇高异，神州览眺殊。"]},{"t":"来青轩临眺二首 其一","f":"七言绝句","c":["摇拂烟云动翠旗，登临翰墨每相随。","山河景象无穷意，俯瞰人情因物知。"]},{"t":"来青轩临眺二首 其二","f":"七言绝句","c":["来青高敞眺神京，斜倚名山涧水清。","此日君臣同览赏，村村鸡犬静无声。"]},{"t":"法海寺瞻皇考御书敬佛二字","f":"五言律诗","c":["重来瞻御笔，怀感动心神。","丕烈迈前代，鸿休启后人。","兴文盛礼乐，偃武息兵民。","法则光华远，千年照佛轮。"]},{"t":"坐法海寺偶吟","f":"七言绝句","c":["纵目西山宜永日，开襟五月似高秋。","万几偶暇因游豫，期与黎民药未休。"]},{"t":"赐圣感寺僧海岫","f":"七言绝句","c":["翛然老衲净尘缘，台殿参差起瑞烟。","驯鸽檐前应受戒，游鳞花下亦参禅。"]},{"t":"驻跸石景山","f":"七言律诗","c":["驻跸荒亭日欲斜，潺湲石溜滴云霞。","鸾旗飘动连香草，龙骑骖驔映野花。","岩洞幽深无鸟迹，峰崖高处有人家。","青山绿水谁能识，怀古登临玩物华。"]},{"t":"石景山东望","f":"七言绝句","c":["车书混一业无穷，井邑山川今古同。","地镇崚嶒标异秀，凤城遥在白云中。"]},{"t":"登戒坛","f":"七言绝句","c":["楼阁高低树浅深，山光水色日沉沉。","碧墀静照寒松影，清昼蝉声响绿阴。"]},{"t":"下戒坛将至潭柘马上同士奇联句二首 其一","f":"七言绝句","c":["岭腹层层小径斜，穿云陟尽石㟏岈。","涧中草屋流泉绕，万匹龙骧拥翠华。"]},{"t":"下戒坛将至潭柘马上同士奇联句二首 其二","f":"七言绝句","c":["蝉鸣草木动薰风，蛱蝶双来引御骢。","潭柘幽深聊驻辇，省方不与豫游同。"]},{"t":"潭柘寺偶作","f":"七言绝句","c":["怡神水树清襟洽，满目奇峰入夏云。","微起凉风响万籁，山中莺啭奏纷纭。"]},{"t":"咏潭柘寺竹","f":"七言绝句","c":["翠叶才抽碧玉枝，经旬清影上阶墀。","凌霜抱节无人见，终日虚心与凤期。"]},{"t":"石景山望浑河","f":"五言绝句","c":["石景遥连汉，浑河似带流。","沧波日滚滚，浩淼接皇州。"]},{"t":"驻跸南苑遣使恭进太皇太后鲜果","f":"七言绝句","c":["日永离宫节候新，薰风早已献嘉珍。","赤瑛盘内甘鲜果，奉进瑶池第一人。"]},{"t":"南苑元灵宫是世祖皇考建","f":"五言古诗","c":["杰阁横霄峻，清都与汉翔。","规模开壮丽，星宿灿辉光。","碧瓦浮空翠，金铺映日黄。","门当啼鸟静，户有异花香。","细草沿阶发，新槐拂槛凉。","纡回疏辇路，藻彩绘雕梁。","警跸临仙境，瞻依问谷王。","敬钦崇太昊，继述忆先皇。","岁月碑文古，乾坤事业昌。","茫茫扶大造，暤暤体穹苍。","恭己身无倦，斋心念不忘。","时巡非逸豫，几暇岂游荒。","卫骑骖驔列，华旄宛转飏。","南薰披万物，北斗起千祥。","瑞气庭前见，佳辰昼正长。","休歌白云曲，吾道在惟康。"]},{"t":"南苑行围","f":"五言绝句","c":["苑中閒教阵，无事静论边。","不废时苗典，思周天下先。"]},{"t":"德寿寺","f":"五言绝句","c":["持身崇孝理，清净契真如。","岁久开金寺，时来降玉舆。"]},{"t":"南苑晚景","f":"七言绝句","c":["薰风南苑翠斿回，处处连云暮色催。","夜火辉煌盈帐幕，离宫长待万几来。"]},{"t":"瀛台偶作","f":"五言绝句","c":["蝉鸣槐叶绿，鱼跃芰荷风。","太液临斜景，参差更不同。"]},{"t":"咏水禽","f":"五言绝句","c":["水禽遥泛雪，池卉迥披红。","桐叶翩翩舞，迎薰景未穷。"]},{"t":"雨","f":"七言绝句","c":["稼穑忧勤在建章，油云洒落满岩廊。","凭窗喜雨雨方足，五谷秋成乐万方。"]},{"t":"夏日有怀","f":"七言绝句","c":["木槿花开夏日长，时摇清扇倚方床。","三庚不辍临朝政，盛暑常思守战场。"]},{"t":"内苑","f":"七言绝句","c":["晚凉内苑看槐花，依槛临池日欲斜。","龙戏清潭娱夏景，片云生处足桑麻。"]},{"t":"临池观鱼有怀","f":"七言绝句","c":["临池鱼跃白云连，太液东边问小船。","一色水天明似镜，风波销灭在何年。"]},{"t":"夜至三鼓坐待议政大臣奏事有感而作","f":"七言绝句","c":["午夜迢迢刻漏长，每思战士几回肠。","海东波浪何年靖，日望军书奏凯章。"]},{"t":"七夕","f":"五言律诗","c":["爽气三秋早，仙期此夕经。","针楼连万户，机石动双星。","玉露交珠缀，金风度绮軿。","天文在云汉，流影照彤庭。"]},{"t":"沙河途中作","f":"五言律诗","c":["煇煌明辇道，将晓漏声残。","秋月西山落，金风北野寒。","望陵悲树色，就景盼云端。","每念芳华日，漙漙露未乾。"]},{"t":"清河荒亭","f":"五言律诗","c":["楸叶晚蝉鸣，荒亭蟋蟀声。","露凝新树色，日出满林明。","蛱蝶从枝舞，蜻蜓点水轻。","欲看秋景好，归路且徐行。"]},{"t":"初秋景山","f":"七言律诗","c":["新凉树色向金天，御辇遥停蔓草边。","盛暑已过销夏日，清风才到有秋年。","高临三殿九重阔，下看千家万户连。","薄暮山亭观射毕，回宫复道起苍烟。"]},{"t":"题日精门古砚","f":"五言律诗","c":["古砚何年斲，云笺写御章。","宫门秋雨湿，内殿晚风凉。","夕景炉烟动，晴光烛影长。","文房友笔墨，洒翰起龙翔。"]},{"t":"待晓","f":"五言古诗","c":["阊阖馀残暑，夕籁鸣高秋。","暧暧月始出，泠泠露初浮。","远色淡河汉，新凉洒裀帱。","夜气倍澄寂，庭宇弥清幽。","眷言希古则，羲轩讵可俦。","不寐定天保，昧爽思旁求。","往轸虽缅邈，来途非阻修。","低徊待申旦，治理今何由。"]},{"t":"赐奉命大将军杰淑二首 其一","f":"七言绝句","c":["卷旆生风壮气扬，早持龙节定炎方。","秋毫无犯民心悦，尽扫欃枪奏凯章。"]},{"t":"赐奉命大将军杰淑二首 其二","f":"七言绝句","c":["旄钺才临父老迎，楼船一举海波清。","金瓯已定千年业，铜柱须标万古名。"]},{"t":"秋日咏刀","f":"七言绝句","c":["七宝刀光耀斗牛，建章佩带向初秋。","清流越砥方知力，截兕剸鲸断不愁。"]},{"t":"海子北红门秋雨后行围戏作","f":"七言律诗","c":["昼漏稀闻紫陌长，霏霏细雨过南庄。","云飞御苑秋花湿，风到红门野草香。","玉辇遥临平甸阔，羽旗近傍远林扬。","初晴少顷布围猎，好趁清凉跃骕骦。"]},{"t":"晾鹰台","f":"七言绝句","c":["清晨漫上晾鹰台，八骏齐登万马催。","遥望九重云雾里，群臣就景献诗来。"]},{"t":"南苑阅马","f":"七言绝句","c":["渥洼龙种雪霜同，毛骨天生气格雄。","八骏齐观南苑里，岂誇当日玉花骢。"]},{"t":"中秋望月","f":"七言绝句","c":["坐望中秋月正圆，玲珑丹桂植当天。","无私普照八荒外，皎洁清光云汉边。"]},{"t":"赐辅国将军俄启诗","f":"七言绝句","c":["观德由来上古风，手持满月绿沉弓。","鹰扬虎视流星远，中鹄穿杨为世雄。"]},{"t":"秋日晚景有怀","f":"七言律诗","c":["寒鸦秋景集南林，遥倚屏山绮树阴。","丹阙远砧鸣午夜，玉壶清漏起遐心。","衷情静里无人识，外象閒中有物寻。","忆想千般闻落叶，且须持笔漫微吟。"]},{"t":"大将军报吴逆暴死其下贼众溃散无馀大兵指日进取恢复封疆","f":"七言绝句","c":["遥天今日捷书来，万里欢声动地开。","从此黎民皆乐业，军威应振凯歌回。"]},{"t":"康熙十七年九月初十日奉太皇太后临御温泉恭纪五言排律八韵","f":"五言古诗","c":["慈宁方晓日，掖辇幸温泉。","羽骑清尘道，华旗卫御前。","九重双阙迥，三辅万家连。","葱郁东皋树，苍茫北岭烟。","问安频色喜，侍膳每心悬。","孝养尊亲重，时巡法祖虔。","村村施化溥，处处得恩先。","更虑民情隐，深惭抚八埏。"]},{"t":"驻跸平家滩","f":"七言绝句","c":["銮舆驻跸近沧浪，行殿崔嵬对夕阳。","郊外村庄时极目，秋成处处有风光。"]},{"t":"潞河晓起至太皇太后行殿问安","f":"七言绝句","c":["晓色方明在潞河，孤山远影郁嵯峨。","寝门恭问慈颜喜，还愧无能作赋歌。"]},{"t":"见雁南飞","f":"七言绝句","c":["归雁南飞有数行，南飞度岭向衡阳。","欲将信息传军士，早报成功返故乡。"]},{"t":"驻跸蓟州城南远眺山村","f":"七言律诗","c":["万骑骖驔拥蓟城，风行雷出远天清。","微霜细草野狐惧，寒露荒烟山鸟鸣。","捲幔浮凉侵帐殿，倚床明月似都京。","欣随圣母游情旷，深夜还思勉愫诚。"]},{"t":"山中获野禽恭进太皇太后","f":"五言律诗","c":["吹笳清辇道，大地杂旌旂。","万壑来秋色，千岩散落晖。","鹰随山雉远，箭带野禽归。","遣使呈鲜味，须令马迅飞。"]},{"t":"晓起山路口号","f":"七言绝句","c":["荒屋山中月色阑，秋高边塞正风寒。","羊肠石道临泉水，已静人声足旷观。"]},{"t":"恭谒孝陵","f":"五言律诗","c":["玉殿寒松秘，秋霜落树枝。","缅怀文武业，创立太平基。","晓色星辰动，晴光日月垂。","望陵愁不断，孝思起深悲。"]},{"t":"太皇太后驾到温泉","f":"七言绝句","c":["温谷神丹力不穷，五云暖溜绕行宫。","圣躬喜得今康豫，宇宙欢忻旧日同。"]},{"t":"雨后经明总兵戚继光所作八角石亭","f":"七言律诗","c":["华清雨后问安回，徐步山椒到水隈。","秋木荒池今白草，寒花故垒旧青苔。","精灵销散人何处，功业留传志未灰。","为将当年堪拊髀，亭开八角尚崔嵬。"]},{"t":"清晨入盘山二首 其一","f":"五言绝句","c":["日出入盘山，宸游草木閒。","村庄人尽望，处处水潺潺。"]},{"t":"清晨入盘山二首 其二","f":"五言绝句","c":["当年乘辇到，今日复来游。","山水不同色，泉声还细流。"]},{"t":"古中盘望莲花峰","f":"七言绝句","c":["中盘遥望莲花峰，日映山林气色重。","老衲吟诗浑半偈，翠舆临发又从容。"]},{"t":"盘山绝顶三首 其一","f":"七言律诗","c":["上盘绝顶俯神京，九月登山积翠晴。","荒寺日高人少至，野林烟静鸟无声。","道中勒马观风景，涧下留銮爱水清。","纵目徘徊犹不尽，氤氲缥缈海云轻。"]},{"t":"盘山绝顶三首 其二","f":"七言律诗","c":["四顾清标高逼天，风云塞上敛寒烟。","遥观沙漠宣威远，近控州城作镇悬。","紫盖山中独奇秀，双峰岭外更绵联。","九秋朗耀几千里，落叶萧条满目前。"]},{"t":"盘山绝顶三首 其三","f":"七言律诗","c":["薄暮东峰来返照，游心怡旷动挥毫。","题诗数句林光晚，作赋初联雁阵高。","盘道崚嶒难步蹑，危岩巀嵲恐身劳。","欲归帐殿还传语，引路山僧度远皋。"]},{"t":"晚过李靖庵二首 其一","f":"七言绝句","c":["两崖石壁出秋云，野草寒林有鹿群。","古刹斜阳人寂寂，香烟飘处杂纷纭。"]},{"t":"晚过李靖庵二首 其二","f":"七言绝句","c":["苍茫绝顶树参差，落日还营过竹篱。","念及凌烟留姓字，独于古壁一题诗。"]},{"t":"星出归营","f":"七言绝句","c":["皎皎星河路向西，将归玉帐渡山溪。","羽林扈从皆雄将，扫靖烟尘万马齐。"]},{"t":"奉侍太皇太后临御温泉因孟冬享庙暂回京","f":"五言古诗","c":["金风肃郊甸，秋光瀰颢穹。","晓钟出长乐，羽卫临新丰。","重闱庆康悦，游豫温泉宫。","鸣镳玉舆侧，侍跸清尘中。","晨夕奉慈颜，婉愉承欢衷。","原野陪登览，瑞霭光熊熊。","应钟忽届节，霜露霏空濛。","夙兴感时序，庙祀宜钦崇。","飨献荐圭璧，对越必微躬。","暂辞琼岛月，还御瑶池骢。","殿阙欣在望，斋祓明禋通。","眷言整星驾，依恋心靡穷。"]},{"t":"夜半览本","f":"七言绝句","c":["初冬夜静正三更，宵旰清心勉励精。","自愧事繁机不敏，细披章奏察民情。"]},{"t":"山中晓色","f":"七言绝句","c":["星汉参差晓色开，高峰初日射莓苔。","閒来驻跸山村静，坐爱明霞入酒杯。"]},{"t":"由鲇鱼池出关咏瀑布水","f":"七言绝句","c":["巉岩瀑布挂前川，树冷烟寒羃碧天。","关外黎民风俗厚，涵濡威德已多年。"]},{"t":"滦河","f":"七言绝句","c":["寒边远绕至滦河，彻底清明不见波。","驻辇徘徊千万里，石鲸两岸影嵯峨。"]},{"t":"冬至回京斋戒夜坐","f":"七言绝句","c":["一阳初发便知天，暂别慈颜日日悬。","午夜斋明湛心志，梦中犹自侍温泉。"]},{"t":"登边城作","f":"七言绝句","c":["冬月荒山落日斜，岧峣野景几千家。","边城戍色云烟静，绿水清河走白沙。"]},{"t":"温泉行","f":"七言古诗","c":["温泉泉水沸且清，仙源遥自丹砂生。","沐日浴月泛灵液，微波细浪流琮琤。","初经石窦漾暄溜，烈势直与炎曦争。","潆洄碧涧落花驻，掩映翠巘霜林明。","汀回溪转入栏槛，甃以文石何澄泓。","方壶圆峤时自暖，紫芝朱草冬常荣。","殿启披香溢石髓，盘低承露浮金茎。","冲融太和蓄元气，炎德利物功难名。","氤氲沆瀣结紫雾，缥缈云霞连赤城。","高秋九月天飒爽，鸾旂凤节纷相迎。","慈宁雕辇度阊阖，绛霄帐殿开蓬瀛。","神泉淑景供游赏，流金漱玉堪怡情。","时巡岂必瑶圃远，对此心意皆和平。","华清绣岭杳寂寞，鲸鱼凫雁徒纵横。","曷若兹泉独标异，万年胜迹环神京。","岁时来往护仙跸，点笔为赋温泉行。"]},{"t":"温泉流杯戏作","f":"七言绝句","c":["晓霜早落满池清，一气涓涓惬胜情。","偶坐浮杯几暇日，君臣对景论平生。"]},{"t":"南苑桥上大风","f":"七言绝句","c":["南苑霜华点翠旗，严风腊月断流澌。","已知朔气催寒尽，桥跨长虹涌溜迟。"]},{"t":"雪","f":"七言绝句","c":["细玉轻盈下碧霄，和烟飞霰上寒条。","片才落地溅溅湿，罗绮花纹处处飘。"]},{"t":"景山积雪侍卫下趋如飞","f":"五言绝句","c":["凭高纵远览，积雪明山峰。","直下数千尺，飞腾跨玉龙。"]},{"t":"元旦慈宁宫行礼","f":"七言律诗","c":["太蔟初分来万国，融融淑景动青阳。","曈昽翠盖祥云覆，缥缈兰宫瑞气扬。","节遇三元开宝历，时逢四始奉霞觞。","山呼拜舞臣民乐，愿颂千年正未央。"]},{"t":"上元幸万善殿戏作","f":"七言绝句","c":["雪霁寒轻景物鲜，上元临幸遇参禅。","方文无人般若静，天花虚落古松前。"]},{"t":"收复岳州作","f":"七言古诗","c":["聿予凉薄莅洪荒，遂使巨慝乱天常。","东南黎庶苦纷扰，几年戎马蹂疆场。","临轩重简亲藩出，军威万里风雷疾。","肆伐原因讨不庭，专征大义昭星日。","卧榻安容有悖狂，太阿岂好弛纪律。","再敕元臣佩虎符，戈矛刬地生寒栗。","铁骑骁腾拥楚云，霓旌闪烁连江濆。","七泽三湘据冲要，楼船璧垒屯诸军。","一时将士尽忿激，人人都愿成功勋。","悬知叛逆众所恶，直须吹气清妖氛。","顾此生灵负何罪，流离转徙多饥馁。","处处田畴芜不耕，年年桑柘无人采。","闻说荒榛遍野庐，还伤老弱填江海。","每念边陲一怃然，立身天地惭主宰。","未忍加兵戕我民，深宫宵旰勤五载。","五载踌躇常恭默，会当灭此乃朝食。","旗捲闽疆甲士降，阵开百粤坚城尅。","已见怀光伏冥诛，更看元济成俘䤋。","鼙鼓旌旄定岳阳，雕戈金镞清区域。","指顾能收六诏烟，宣恩早布招徕德。","书奏传来慰两宫，乂安社稷开鸿濛。","翼翼小心恒敬慎，敢忘继述在朕躬。","期与宰司百执事，共相砥砺克厥终。"]},{"t":"恭上太皇太后万寿诗二首 其一","f":"七言绝句","c":["和风瑞气满帘栊，慈寿无疆祝上宫。","喜得万方同孝养，千秋福德并苍穹。"]},{"t":"恭上太皇太后万寿诗二首 其二","f":"七言绝句","c":["透户卿云接御香，彤墀新柳拜韶阳。","宫中尧舜兼文母，恭捧南山万寿觞。"]},{"t":"赐大将军安亲王岳乐二首 其一","f":"七言绝句","c":["大开册府纪元功，伐罪安民将略雄。","伫见天潢蒙上赏，明光高宴赋彤弓。"]},{"t":"赐大将军安亲王岳乐二首 其二","f":"七言绝句","c":["洞庭南岳尽提封，九伐勋名勒景钟。","眼底穷荒皆赤子，早销金甲劝三农。"]},{"t":"赐护军统领桑格","f":"七言绝句","c":["百战威名已早扬，频年秉钺在岩疆。","素知果勇兼韬略，应著弘图肃鬼方。"]},{"t":"春夜月","f":"五言绝句","c":["晚来风景丽，初晴月色辉。","胧胧穿竹树，照耀满宫帏。"]},{"t":"题周文矩画说剑图","f":"七言绝句","c":["鹅溪尺幅衣冠古，貌出蒙庄辩论新。","剑客满前毛发动，须知绘事亦通神。"]},{"t":"鄚州杂诗五首 其一","f":"七言绝句","c":["条风鼓棹动清漪，夹岸青青杨柳垂。","轻转牙樯观易水，波光日影映旌旗。"]},{"t":"鄚州杂诗五首 其二","f":"七言绝句","c":["桃花历落李花开，绿柳含烟傍水隈。","鸿雁平沙看不尽，春光暧暧入蓬莱。"]},{"t":"鄚州杂诗五首 其三","f":"七言绝句","c":["为省春耕历灞沣，銮舆频止劝农功。","柴门掩处烟村静，碧水长桥落彩虹。"]},{"t":"鄚州杂诗五首 其四","f":"七言绝句","c":["阳气温和临树久，花繁物静草芊芊。","莎添嫩色含波绿，柳覆金堤翠幕连。"]},{"t":"鄚州杂诗五首 其五","f":"七言绝句","c":["野水瀰漫处处长，方流涵玉动珠光。","风移藻荇波痕阔，千点鹥凫柳一行。"]},{"t":"初夏登楼临水","f":"七言绝句","c":["澄潭彻底开心镜，柳絮轻飞近玉楼。","处处晴花风拂起，莺啼四月绕芳洲。"]},{"t":"夏日同三王慈宁宫请太皇太后安","f":"七言绝句","c":["九天旭日照铜龙，朝罢从容侍上宫。","花萼联翩方昼永，晨昏常与问安同。"]},{"t":"夏旱步祷南郊喜雨","f":"五言古诗","c":["历春悯农劳，首夏望嘉谷。","离毕月故迟，密云去何速。","颢穹閟膏泽，及此祈年夙。","斋居承穆清，中夜起自肃。","繁星丽赤霄，云汉光自煜。","鸡鸣开重闉，舆马辍华毂。","步祷升郊坛，祠官启太祝。","是时甘澍零，沾润及拜伏。","空濛迫阊阖，喷薄驱海渎。","屏翳洒道回，渗漉足裳服。","麦陇应秀色，重颖欲在目。","愿惟歌屡丰，馀粟栖比屋。"]},{"t":"五日泛舟赐内大臣侍卫宴","f":"七言律诗","c":["锡宴公卿礼数隆，浴兰令节泛翔鸿。","波开舟楫迎仙仗，岸转旌旗骤玉骢。","积翠香蒲经宿雨，轻烟宝幄散薰风。","臣民共乐升平日，畅饮何论灞浐雄。"]},{"t":"咏蝉","f":"五言律诗","c":["饮露当凉夜，吟风向晚晴。","乍移深树影，又听别枝声。","与物心无竞，离尘翼最轻。","秋怀聊寄咏，爱尔独能清。"]},{"t":"题苏轼墨竹","f":"七言绝句","c":["径尺筼筜墨浅深，雪堂健笔势千寻。","纵饶凝露春梢色，不比凌霜挺节心。"]},{"t":"初寒","f":"七言绝句","c":["洒雪凝霜正渺漫，晓来朔色满林峦。","何当吹遍邹阳律，尽却人间黍谷寒。"]},{"t":"春晓","f":"五言绝句","c":["夜短正宜眠，又闻天色晓。","临门亲政务，岂厌事多少。"]},{"t":"春雪","f":"七言绝句","c":["三冬望雪意殷殷，积素春来乱玉纹。","农事东畴堪播植，勤民方不愧为君。"]},{"t":"懋勤殿读尚书至无逸篇有作","f":"五言古诗","c":["元化斡四运，淑景催芳年。","乾乾总万几，寸阴惜屡迁。","绨几散瑶帙，阿阁飏炉烟。","澄怀求至理，孔壁存遗编。","公旦训无逸，则古多所宣。","言念小民依，田功稼穑先。","天命良匪易，敬德省厥愆。","法戒备近王，炯炯斧扆前。","寤寐思古人，千祀精意传。","端居不遑暇，三复期勉旃。"]},{"t":"春昼二首 其一","f":"五言律诗","c":["液池冰泮后，阿阁燕来初。","昼转铜壶漏，春添玉案书。","晴丝烟乍捲，花雾绮还舒。","万象生成意，欣欣各自如。"]},{"t":"春昼二首 其二","f":"五言律诗","c":["亭午朝初暇，方春候转佳。","惠风来上巳，迟日丽中街。","莺语频迁树，花阴半映阶。","所期凝庶绩，永使万邦怀。"]},{"t":"咏观天仪器","f":"五言古诗","c":["乾象极高远，孰者为纲维。","惟此贞恒理，可以揆测知。","灵台有仪器，云自古圣贻。","偃盖金粲粲，饰体珠离离。","横玉筦其中，激水相推移。","内挈黄赤道，外互南北垂。","紫宸凝不动，列曜如峙棋。","制作侔造化，法撰穷神奇。","昔在有虞氏，以命和与羲。","七政顺其轨，庶绩咸用熙。","后来代有述，神明夫前规。","日官比申命，钦哉重人时。","惟几恒自敕，曰旦凛在兹。","五纬协位序，燠寒无僭差。","永言答灵眷，长与休祯期。"]},{"t":"鹤","f":"五言绝句","c":["夜警三霄露，秋凌万里云。","立同薛稷画，舞忆鲍昭文。"]},{"t":"经筵进讲周易","f":"五言律诗","c":["桂宫仙仗启，兰殿讲筵开。","朝士鸣珂集，词臣执简来。","天苞宣一画，人极位三才。","待抉羲文秘，羹墙日几回。"]},{"t":"题张择端清明上河图","f":"七言绝句","c":["天津桥下水粼粼，柳外盘舟夹画轮。","想见汴京全盛日，春游多少太平人。"]},{"t":"长至日祀天圜丘有述四章","f":"古风","c":["于穆天縡，鉴观惟赫。","播物无私，佑于有德。","高皇受命，膺符阐绎。","丕显太宗，廓图登绩。","眷我皇考，九围是式。","克享天心，立民之极。","洪惟景运，集于渺躬。","南谐北燮，君兹万邦。","夙夜敬止，恒惕于衷。","毋曰高高，听卑则聪。","毋曰盱盱，视远斯通。","罔敢逸豫，昭事必恭。","是月仲冬，维日长至。","爰启泰坛，肃将禋祀。","济济奉璋，群工在位。","牲玉既陈，籥舞乃备。","对越有虔，百神攸暨。","云旓扬扬，华皇晢晢。","乃辨云物，载观载书。","乃占丰年，多黍多稌。","南陆曜采，导我归舆。","芸香始生，景长以舒。","初阳来复，相协厥居。","垂象是则，奉若不渝。"]},{"t":"远望西山积雪","f":"五言绝句","c":["积雪西山秀，仙峰玉树林。","冻云添暮色，寒日淡遥岑。"]},{"t":"端宁殿斋居","f":"五言古诗","c":["肃肃群籁屏，袅袅炉烟舒。","诹日躬禋祀，濯祓临斋居。","辉辉阁西日，流影照绮疏。","坐久微风来，冷然吹衣裾。","霁心观万象，默见天地初。","感神在至诚，宁俟灌鬯馀。"]},{"t":"赐直?巡抚于成龙","f":"五言律诗","c":["自昔崇廉治，勤思吏道澄。","郊圻王化始，锁钥重臣膺。","政绩闻留犊，风期素饮冰。","勖哉贞晚节，褒命日钦承。"]},{"t":"苑西新柳二首 其一","f":"七言绝句","c":["岸草青回太液池，春来又见柳垂丝。","东风小苑三眠后，最爱鹅黄蘸水枝。"]},{"t":"苑西新柳二首 其二","f":"七言绝句","c":["轻烟漠漠柳青青，半拂虹桥半水亭。","啼鸟数声春昼永，博山香袅隔帘听。"]},{"t":"潞河三首 其一","f":"七言绝句","c":["潋滟春波散碧漪，白蘋初叶麦初岐。","潞河三月桃花水，正是乘舟荐鲔时。"]},{"t":"潞河三首 其二","f":"七言绝句","c":["画鹢中流起棹歌，参差荇藻漾晴波。","泽梁虽设曾无禁，斜日鱼罾两岸多。"]},{"t":"潞河三首 其三","f":"七言绝句","c":["东风吹雨晓来晴，春水高低五闸声。","兰桨乍移明镜里，绿杨深处坐闻莺。"]},{"t":"巡幸出喜峰口过黄土岩","f":"五言律诗","c":["紫塞双崖出，丹梯百尺悬。","草香遮细路，树老卧晴烟。","地为时巡到，山当隘口偏。","何年留石室，驻马望层巅。"]},{"t":"大石矶","f":"五言律诗","c":["远近峰回合，潺湲涧浅深。","一矶横大石，万骑出层林。","蒙密岩花发，绵蛮谷鸟音。","龙堆尘不到，凭眺足娱心。"]},{"t":"塞上宴诸藩","f":"七言律诗","c":["龙沙张宴塞云收，帐外连营散酒筹。","万里车书皆属国，一时剑佩列通侯。","天高大漠围青嶂，日午微风动綵斿。","声教无私疆域远，省方随处示怀柔。"]},{"t":"入喜峰口","f":"五言律诗","c":["一道鸣銮度，三驱振旅还。","莓苔天半石，松栝雨中山。","险设关门壮，时清堠火閒。","孝陵佳气近，缥缈翠微间。"]},{"t":"野望","f":"五言绝句","c":["岭外茅茨小，林端烟火迟。","田家耕凿意，一一九重知。"]},{"t":"夏日潭柘寺","f":"五言古诗","c":["微云缀冈岭，细路扬前旌。","磴转松门开，渐觉沙界平。","潭湮石甃露，柘古苔纹生。","一径得疏豁，层轩面峥嵘。","爱此户外泉，俯视涓涓清。","修篁挺苍翠，其下流交横。","斐然淇澳思，宛尔渭滨情。","嶰谷有遗响，箫韶鸾凤声。"]},{"t":"戒坛卧松","f":"五言绝句","c":["苍松卧如龙，蜿蜒鳞鬣古。","肤寸起山云，用汝作霖雨。"]},{"t":"夜坐","f":"五言古诗","c":["霭霭燕寝夕，迟迟清漏催。","绨帙盈棐几，次第中宵开。","华月影帷烛，凉飔韵宫槐。","玉杯露方浥，金炉麝初煤。","坐觉秋气肃，斗柄西南回。","晨光尚未启，已有鸾声来。"]},{"t":"瀛台","f":"七言律诗","c":["红阑桥转白蘋湾，叠石参差积翠间。","画舸分流帘下水，秋花倒影镜中山。","风微瑶岛归云近，日落清霄舞鹤还。","乘兴欲成兰沼咏，偶从机务得馀閒。"]},{"t":"天津","f":"五言律诗","c":["转粟排千舰，分流纳九河。","潮声连海壮，树色入京多。","鼓楫鱼龙伏，停帆鹳鹤过。","津门秋望远，明月涌金波。"]},{"t":"通惠河阅运艘","f":"七言绝句","c":["千樯争溯白蘋风，飞挽东南泽国同。","已见灵长资水德，也应辛苦念田功。"]},{"t":"宫门听政示阁部诸臣","f":"五言古诗","c":["中书天下本，六官庶僚首。","丝纶委寄隆，分职慎所守。","上相列天阶，喉舌筦北斗。","乾象方昭垂，古来讵虚授。","轩皇置六相，姬文择四友。","得人邦乃昌，此事谅非偶。","曰予既寡昧，欿然谢哲后。","听政日不遑，望道远何有。","启沃藉臣邻，匡赞资左右。","虽云际升平，民物岂康阜。","图终贵谨始，治安莫予狃。","广业惟克勤，励精期永久。","作诗一相勖，敬哉庶无负。"]},{"t":"东巡二首 其一","f":"五言律诗","c":["昆池不习战，寰宇已销兵。","鸿业承匪易，肤功久乃成。","威灵昭祖德，展谒慰群情。","迢递关山路，宁辞千里行。"]},{"t":"东巡二首 其二","f":"五言律诗","c":["顺动因时豫，东风引翠旗。","鸣銮万骑出，执事百僚随。","日暖草初茁，烟轻柳未丝。","春光无限好，应有上陵诗。"]},{"t":"玉田","f":"七言绝句","c":["徐无山下水涓涓，几道横流灌玉田。","驱犊荷锄农事作，五风十雨卜丰年。"]},{"t":"驻跸丰润城西","f":"七言绝句","c":["旌门铙吹发云璈，行漏声传帐殿高。","欲向山头望明月，恐惊霄汉避龙镳。"]},{"t":"夷齐庙","f":"五言古诗","c":["滦河水清驶，荒山屹然峙。","上有孤竹城，乱石半倾圮。","堂庑既具观，庙貌亦俨尔。","缅惟商代末，天下渐披靡。","兹地实藩封，人民差可恃。","兄弟以义让，富贵如敝屣。","叩马谏周王，数语昭青史。","遁迹首阳山，薇蕨何其美。","万载挹高风，顽懦闻之起。","苍苍台下松，汤汤台前水。","劲节与澄流，不愧相比拟。","停銮碧山阿，怀古未能已。"]},{"t":"滦河泛舟","f":"七言绝句","c":["平沙漠漠接长河，天际浮云落照多。","两岸苍山相竦峙，扁舟一棹任清波。"]},{"t":"经永平城南","f":"五言律诗","c":["三代幽偏地，秦时右北平。","川原绵大陆，形胜借坚城。","晴日初迎辇，春风暗拂旌。","龙山遥入目，缥缈白云横。"]},{"t":"抚宁","f":"七言绝句","c":["辇路平铺孤屿东，日华升处海云红。","忽听百舌春啼巧，尽在苍条古木中。"]},{"t":"山海关","f":"五言古诗","c":["重关称第一，扼险倚雄边。","地势长城接，天空沧海连。","戍歌终岁苦，插羽不时传。","作镇隆三辅，征输困百年。","笳寒龙塞月，甲冷雉楼烟。","历数归皇极，纲维秉化权。","漫劳严锁钥，空自结山川。","在德诚非易，临风更慨然。"]},{"t":"蒙恬所筑长城","f":"七言绝句","c":["万里经营到海涯，纷纷调发逐浮誇。","当时用尽生民力，天下何曾属尔家。"]},{"t":"姜女祠","f":"七言绝句","c":["朝朝海上望夫还，留得荒祠半仞山。","多少征人埋白骨，独将大节说红颜。"]},{"t":"晓过宁远","f":"五言绝句","c":["孤城临巨野，旧烈忆西征。","破垒荆榛满，村鸡向晓鸣。"]},{"t":"行殿夜览章奏","f":"七言绝句","c":["飞递传来奏牍多，旌门莫问夜如何。","银灯毳幕春寒重，恐是阴阳尚失和。"]},{"t":"吕翁山是圣祖太宗文皇帝擒洪承畴处","f":"七言律诗","c":["旌旗直捲阵云沈，濠堑遗踪尚可寻。","十万健儿皆解甲，一时大帅此成擒。","民情效顺当年事，王业维艰圣祖心。","遂使关西如破竹，至今战气昼阴森。"]},{"t":"松山","f":"七言绝句","c":["鸣笳伐鼓速兵机，百胜谋成夜合围。","月黑风高神鬼泣，金戈白马识天威。"]},{"t":"杏山晚眺","f":"七言绝句","c":["野日荒荒蔓草平，孤村鸡犬寂无声。","山中猎罢残阳晚，时见高原夜烧明。"]},{"t":"憩小凌河","f":"五言律诗","c":["河水流不息，昼夜去涓涓。","昔为征战地，今是豫游年。","驻马孤岑外，移舟古岸前。","残阳下新柳，约略见春妍。"]},{"t":"锦州道上","f":"五言律诗","c":["野径临官驿，炊烟出杳冥。","地连榆塞紫，山列锦屏青。","城郭知何处，旌旄只暂停。","版图归大业，堠火罢林坰。"]},{"t":"驻跸大凌河","f":"七言律诗","c":["归骑云屯向晚过，升平笳吹动铙歌。","光摇幕火繁星灿，影暗旗风野雾多。","兵气已销沙右所，军声犹壮大凌河。","丰京老将还能说，曾记前途自倒戈。"]},{"t":"十三山","f":"七言绝句","c":["迤逦峰连大道间，凭空青削十三山。","敌楼人散堠台废，终日茸茸草色閒。"]},{"t":"过广宁望医巫闾山","f":"五言古诗","c":["名山插霄汉，朵朵青芙蓉。","连亘数十里，隐现千百重。","迢遥不可极，黛色堆奇峰。","窈窕复岝㟧，郁郁多苍松。","中有桃花洞，杳霭常云封。","万古镇幽州，秩祀同岱宗。","盻望生引领，瞻顾停六龙。","何时一登览，荡涤疏心胸。"]},{"t":"渡句骊河","f":"五言律诗","c":["野岸春芜发，青葱一色齐。","皇舆连近远，地轴别东西。","日送霓旌影，风催骏马蹄。","山河绵带砺，回首重低迷。"]},{"t":"过永安桥口占","f":"七言绝句","c":["夹路飞尘宿雨消，十年曾此驻龙镳。","春风城阙知非远，几处轻寒变柳条。"]},{"t":"盛京遣使请太皇太后皇太后起居夜书奏疏毕偶成","f":"七言绝句","c":["云山遥隔万安宫，定省心悬午夜中。","孺慕经时书不尽，微诚凭仗与东风。"]},{"t":"三月初六日告祭福陵恭述十韵","f":"五言古诗","c":["瑞霭钟灵阙，晴烟绕閟宫。","万山皆拱北，百水尽洄东。","夭矫盘峰秀，纡回磴道通。","俯看环众象，遥睇极高崇。","松柏丸丸直，冈峦面面同。","恢弘思祖烈，建树本神功。","战术无前略，谟谋启后衷。","挥蛇曾握剑，定鼎有遗弓。","展礼威仪整，申诚俎豆丰。","车书叨继统，藐尔愧微躬。"]},{"t":"初八日告祭昭陵恭述十二韵","f":"五言古诗","c":["盛德兼三代，威名定四方。","文谟真显赫，武烈实飞扬。","包并收群国，虚谦集众长。","网罗来俊彦，缔造辟洪荒。","卜世周垂历，开基汉启疆。","灵山佳气迥，寝庙瑞云张。","旷远临平陆，幽深逼上苍。","汗尝趋石马，歌欲奏芝房。","洱海销兵战，炎陬绝叛狂。","功成昭默佑，告祀肃诚将。","微念通层构，含情望两厢。","千官遵大典，进退尽锵锵。"]},{"t":"盛京旧宫","f":"七言律诗","c":["双悬凤阙隐金铺，想见龙飞握瑞符。","殿列丹霄崇大政，宫开紫极接神区。","君臣际会风云日，版籍留存山海图。","堂构有怀追往事，土阶俭朴示规模。"]},{"t":"告祀礼成宴诸臣于旧宫","f":"七言律诗","c":["阊阖门开玉座春，金支遍插绮筵新。","铿锵剑佩千官集，曼衍鱼龙百戏陈。","功定舞干歌靖乱，恩留过沛乐同民。","大风猛士何烦忆，仗下班联绛灌臣。"]},{"t":"三月十一日雪中诣永陵告祭","f":"七言律诗","c":["峰峦叠叠水层层，王气氤氲护永陵。","蟠伏诸山成虎踞，飞骞众壑佐龙腾。","云封草木桥园古，雪拥松楸辇路升。","一自迁岐基盛业，深思遗绪愧难承。"]},{"t":"萨尔浒","f":"七言绝句","c":["城成龙跃竦重霄，黄钺麾时早定辽。","铁背山前酣战罢，横行万里迅飞飙。"]},{"t":"柳条边望月","f":"七言绝句","c":["雨过高天霁晚虹，关山迢递月明中。","春风寂寂吹杨柳，摇曳寒光度远空。"]},{"t":"望祀长白山","f":"五言律诗","c":["名山钟灵秀，二水发真源。","翠霭笼天窟，红云拥地根。","千秋佳兆启，一代典仪尊。","翘首瞻晴昊，岧峣逼帝阍。"]},{"t":"松花江放船歌","f":"古风","c":["松花江，江水清，夜来雨过春涛生。","浪花叠锦绣縠明，綵帆画鹢随风轻。","箫韶小奏中流鸣，苍岩翠壁两岸横。","浮云耀日何晶晶，乘流直下蛟龙惊。","连樯接舰屯江城，貔貅健甲皆锐精。","旌旄映水翻朱缨，我来问俗非观兵。","松花江，江水清。","浩浩瀚瀚冲波行，云霞万里开澄泓。"]},{"t":"江中雨望","f":"七言绝句","c":["烟雨连江势最奇，漫天雾黑影迷离。","掀翻波浪三千尺，疑是蛟龙出没时。"]},{"t":"经叶赫废城","f":"五言绝句","c":["断垒生新草，空城尚野花。","翠华今日幸，谷口动鸣笳。"]},{"t":"铁岭","f":"古风","c":["雨馀塞草自绿，日出山花更红。","辙迹神州近远，骥鸣广陌西东。"]},{"t":"杂咏","f":"古风","c":["古戍行来日落，孤村坐对月明。","漠漠龙沙千里，桓桓虎卫三更。"]},{"t":"巡幸辽阳","f":"七言律诗","c":["肃将轩驾向辽阳，暖日晴薰百草芳。","照野山川皆动色，掀天旌旆自生光。","林间苍藓侵人径，城上新花缀女墙。","欲问襄平旧郛郭，千年华表鹤飞翔。"]},{"t":"驻跸辽阳夜深对月用唐太宗辽城望月诗原韵","f":"五言古诗","c":["夜气澄炎景，清光渡海碣。","流云渐稀朗，繁星粲如缀。","蟾殿魄初明，冰轮影未缺。","怀古听行漏，素心良蕴结。","旷然望九霄，妖氛尽殄灭。"]},{"t":"广祐寺","f":"五言律诗","c":["禅宫多岁月，瑞塔积风烟。","翡翠苔碑暗，珠玑宝相传。","驯檐来紫鸽，涌地出青莲。","微雨轻埃洗，兹晨兴独偏。"]},{"t":"入千山","f":"五言律诗","c":["晓入千山路，烟光织翠萝。","崎嵚缘石磴，宛转历岩阿。","树杪朱旗出，藤阴玉勒过。","物华看亦好，景色爱清和。"]},{"t":"祖樾寺","f":"五言律诗","c":["青山横古寺，羽旆陟层巅。","地僻茅堂小，桥危石径穿。","夏条含嫩叶，春卉发馀妍。","寂寞空林午，时闻钟磬传。"]},{"t":"龙泉寺","f":"五言律诗","c":["狭径才容骑，香台欲起龙。","悬崖千仞落，断碣百年封。","泉细通幽壑，庭深暗古松。","临高一骋望，积翠霭重重。"]},{"t":"行殿读书示翰林侍讲高士奇","f":"七言绝句","c":["六御东巡海上回，夜深思古帙重开。","秘书日日随行幄，玉辇前头珥笔来。"]},{"t":"登澄海楼观海","f":"七言律诗","c":["危楼千尺压洪荒，骋目云霞入渺茫。","吞吐百川归领袖，往来万国奉梯航。","波涛滚滚乾坤大，星宿煌煌日月光。","阆苑蓬壶何处是，岂贪汉武觅神方。"]},{"t":"端阳前一日回宫","f":"七言绝句","c":["满路榴花映玉舆，炉烟香绕侍臣裾。","经时远道彤闱隔，先向慈宁问起居。"]},{"t":"机政偶暇辄留意书法漫成","f":"七言古诗","c":["紫宸唤仗晓初散，坐挹朝爽浮南荣。","时平偶得机政暇，觚棱浮影风日清。","盘螭画几青玉色，回鸾素纸雪茧明。","临池试作波折势，染翰聊适优閒情。","体安要使结构密，志一始觉风神生。","心手调娱本非易，筌蹄脱落宁有程。","古来圣学亦游艺，别具妙诣非形声。"]},{"t":"夏日瀛台许奏事诸臣网鱼携归","f":"五言古诗","c":["西苑颇幽邃，崇台俯畿甸。","鲜云荫修廊，南薰披广殿。","水木既周遭，卉物亦葱茜。","岚光翠欲流，林晖清可荐。","于兹涤烦暑，敢曰恣游衍。","眺远畅阳和，居高协灵撰。","朝来览封事，洒洒意忘倦。","高阁昼漏移，彤墀集群彦。","靖共往汝谐，勤劬答予眷。","姑为池籞游，从容任所便。","投纶锦鬣飞，举手纤鳞见。","委蛇退食心，庶几娱式燕。"]},{"t":"赐大学士杜立德","f":"五言律诗","c":["十载资贤佐，劳深致太平。","吁谟留紫闼，风度重丹楹。","方倚盐梅略，难违丘壑情。","餐芝黄绮伴，轩冕有馀清。"]},{"t":"赐大学士冯溥","f":"五言律诗","c":["环海销兵日，元臣乐志年。","草堂开绿野，别墅筑平泉。","望切岩廊重，人思霖雨贤。","青门归路远，逸兴豁云天。"]},{"t":"西山驻跸夜闻秋声","f":"五言绝句","c":["西风吹长林，木叶响如雨。","起视山月高，浮云无一缕。"]},{"t":"玉泉山晚景用唐太宗秋日韵","f":"五言律诗","c":["晴霞收远岫，宿鸟赴高林。","石激泉鸣玉，波回月涌金。","薰炉笼竹翠，行漏出松阴。","坐爱秋光好，翛然静此心。"]},{"t":"秋日紫光阁阅射","f":"五言律诗","c":["碧汉层云敛，金风别馆开。","驺虞宾射礼，士马羽林材。","队引花间入，镳分柳外催。","桓桓心膂寄，堪许属车陪。"]},{"t":"大阅","f":"七言律诗","c":["南苑风高水潦收，旋催羽队肃貔貅。","九天鼓吹鸣金镯，万乘旌旄拥翠虬。","马足过时残雪尽，銮声回处朔云浮。","宣威端在承平日，自昔经邦有大猷。"]},{"t":"海东青","f":"七言古诗","c":["羽虫三百有六十，神俊最数海东青。","性秉金灵含火德，异材上映瑶光星。","轩昂时作左右顾，整拂六翮披霜翎。","期门射生谙调习，雄飞忽掣黄绦铃。","劲如千钧激砮石，迅如九野鞭雷霆。","原头草枯眼愈疾，砉然一举凌高冥。","万夫立马齐注目，下逐鸟雀无留形。","爪牙之用安可废，有若猛士清郊坰。","晾鹰筑台存胜迹，佳名岂独标禽经。"]},{"t":"曩因见雁念征南将士曾题截句今禁旅凯旋闻雁再作","f":"七言绝句","c":["上林秋晓净烟霏，每听征鸿忆授衣。","此日诸军齐奏凯，衔书不用更南飞。"]},{"t":"黄金台怀古","f":"五言古诗","c":["昭王礼贤士，筑馆黄金台。","矫矫昌国君，奋袂起尘埃。","下齐七十城，声振沧海隈。","汶篁植蓟邱，岂曰非雄才。","遗迹虽榛芜，千载犹低佪。","市骏固有术，贵在先龙媒。","但得一士贤，可以收群材。"]},{"t":"自长城岭至台怀","f":"五言古诗","c":["山行竟日夕，风景一以殊。","万马鱼贯前，宛若登天衢。","云际冠层峰，雪外辨修途。","丛卉未甲坼，寒禽互喧呼。","曲涧响环玦，空籁鸣笙竽。","纵乏绮丽观，烟萝澹相娱。","流览多所欣，未觉道路纡。","五台遥入抱，郁郁诚灵区。","翠微未及上，身已临清都。","佳气惬遐赏，旷怀抗远图。","陶唐此故土，馀泽仍渐濡。","刻玉缅往迹，游河景前模。","载咏蟋蟀吟，遗风今有无。"]},{"t":"显通寺","f":"五言律诗","c":["兰若翠微重，诸天第一峰。","金轮开汉日，紫府觅仙宗。","雪映交窗迥，云封阁道浓。","夕阳松影外，处处报疏钟。"]},{"t":"殊像寺法相最异","f":"五言律诗","c":["五髻瞻殊像，千花聚法筵。","经营思哲匠，髣髴见初禅。","緤马明霞外，燃灯画壁前。","不须仙梵放，清磬已泠然。"]},{"t":"驻跸灵鹫峰文殊寺","f":"五言律诗","c":["地敞层台近，林开法象遥。","香泉分乳钵，佛火簇松寮。","绀马迎銮入，珠幢引队飘。","竺兰遗迹在，选胜历山椒。"]},{"t":"登望海峰","f":"五言律诗","c":["谁驾鳌为柱，神州左一方。","重关连委粟，半夜豁扶桑。","晓散岚光白，晴收水气黄。","瀛壖不可极，万里自苍茫。"]},{"t":"北台眺望","f":"五言律诗","c":["绝磴摩群峭，高寒逼斗宫。","钟鸣千嶂外，人语九霄中。","朔雪晴犹积，春冰暖未融。","凭虚看陆海，此地即方蓬。"]},{"t":"赵北口","f":"五言律诗","c":["赵北时巡至，燕南古戍闻。","人烟生晓市，桥影漾晴云。","浴鸟迎船出，垂杨隔浦分。","中流清赏洽，箫鼓陋横汾。"]},{"t":"水淀杂诗四首 其一","f":"古风","c":["轻舟十里五里，垂柳千丝万丝。","忽听农歌起处，满村红杏开时。"]},{"t":"水淀杂诗四首 其二","f":"古风","c":["春水船行天上，泠风雨过田家。","深树几声布谷，晚晴千缕明霞。"]},{"t":"水淀杂诗四首 其三","f":"古风","c":["衔泥双燕沙际，唤雨单鸠树头。","昨夜桃花新水，鲤鱼跃入兰舟。"]},{"t":"水淀杂诗四首 其四","f":"古风","c":["为爱沙明水远，更看柳亸花新。","草木禽鱼咸若，河山民物同春。"]},{"t":"南苑","f":"五言律诗","c":["十里郊南路，红门启上林。","岁时蒐狩礼，畎亩豫游心。","羽仗连花影，帷宫接柳阴。","凤城回首望，缥缈五云深。"]},{"t":"夏日奉太皇太后避暑兴安","f":"七言律诗","c":["玉辇亲扶出凤城，青霄遥指五云生。","鸣銮日映中天永，避暑风来北塞清。","万里山河通远徼，九边形胜抱神京。","登临但得慈颜喜，长侍瑶台岁岁行。"]},{"t":"石盘峪龙潭","f":"五言律诗","c":["谷转盘千骑，潭深静一泓。","鱼迎斜照出，禽杂野风鸣。","扪石苔偏滑，分流水益清。","悠然惬心赏，归路月华生。"]},{"t":"白水","f":"七言绝句","c":["乱峰回合古檀州，白水云根一道流。","谁信塞垣图画似，凉风斜日放渔舟。"]},{"t":"古北口","f":"五言绝句","c":["断山踰古北，石壁开峻远。","形胜固难凭，在德不在险。"]},{"t":"晓发古北口望雾灵山","f":"五言律诗","c":["流吹凌晨发，长旓出塞分。","远峰犹见月，古木半笼云。","地迥疏人迹，山回簇马群。","观风当夏景，涧草自含薰。"]},{"t":"第一泉","f":"七言绝句","c":["峻阜横冈紫塞连，羽林卫士宿三千。","閒听鼓角空山里，月上长城第一泉。"]},{"t":"次上都河","f":"五言律诗","c":["碛里水潺潺，前旌杳霭间。","长风吹海月，一夜照关山。","虎旅严宵卫，星宫列从班。","高峰望缥缈，明发欲跻攀。"]},{"t":"青城道中","f":"七言绝句","c":["云屯万骑汗沾濡，不谓凉风满上都。","行到青城齐色喜，恍疑人影濯冰壶。"]},{"t":"九隘","f":"五言律诗","c":["合沓群峰接，潆洄九隘通。","片云晴作雨，高树午多风。","碛近扶珠幰，沙平骤玉骢。","凌歊何用筑，三伏杪秋同。"]},{"t":"塞外对雨","f":"七言律诗","c":["奋雷殷殷鸣大泽，飞雨千山万山白。","草色花香濯更新，荒冈处处流泉脉。","回望神京接塞云，雨声应得四郊闻。","黍苗翼翼平畴远，多少农人话夜分。"]},{"t":"红川","f":"七言律诗","c":["紫塞红川接上京，昼閒雉尾暑风轻。","茅茨不改阶三尺，台殿何须筑九成。","谷鸟群飞林欲暮，边花齐发雨新晴。","试看属国欢娱日，大漠虚烟处处生。"]},{"t":"驻跸兴安八首 其一","f":"五言律诗","c":["祖德隆三后，天心廓九围。","讴歌通毳幕，风雨想戎衣。","一自车书合，长看职贡归。","黄图无内外，时迈有光辉。"]},{"t":"驻跸兴安八首 其二","f":"五言律诗","c":["特奉仙舆出，晴峦驻羽旄。","风多停彩扇，驿远进冰桃。","丽草金莲涌，浓阴碧树高。","墉台新月上，广乐奏云璈。"]},{"t":"驻跸兴安八首 其三","f":"五言律诗","c":["重岭叠云烟，旌旗拂塞天。","草香薰翠幄，花暖接红川。","雁碛长城外，龙荒胜地传。","回瞻亭障远，千里抱幽燕。"]},{"t":"驻跸兴安八首 其四","f":"五言律诗","c":["六月浮埃净，高居暑气消。","千山低接帐，万木迥凌霄。","地拥边沙阔，天临塞曲遥。","封章达行在，银烛秉凉宵。"]},{"t":"驻跸兴安八首 其五","f":"五言律诗","c":["虎戟閒清候，逍遥览物华。","烟笼千树柳，暑发四时花。","风土暄凉异，山川道里赊。","濯枝新雨歇，皎皎散飞霞。"]},{"t":"驻跸兴安八首 其六","f":"五言律诗","c":["地脉连荒服，山形赴上陉。","炎歊移月令，分野别星经。","桦屋参覃白，松林断续青。","云沙一万里，属国尽来庭。"]},{"t":"驻跸兴安八首 其七","f":"五言律诗","c":["边云澄霁色，山翠点行衣。","马引雕弓过，禽连羽箭飞。","旌旗开一面，草树入长围。","我武当蒐狩，非因耀德威。"]},{"t":"驻跸兴安八首 其八","f":"五言律诗","c":["紫塞行巡日，雕舆问俗年。","大庖陈折俎，仙醴秩初筵。","屏翰金汤壮，光华赐予宣。","示慈良有意，裒对在敷天。"]},{"t":"巡历塞北杂咏四首 其一","f":"七言绝句","c":["叠嶂层崖一线开，草深径路绝尘埃。","龙沙雨后滦河水，日夜朝宗入塞来。"]},{"t":"巡历塞北杂咏四首 其二","f":"七言绝句","c":["云开灌木万山清，缥缈前旌拂晓星。","漫道穷荒人迹少，几家烟火簇边庭。"]},{"t":"巡历塞北杂咏四首 其三","f":"七言绝句","c":["职方风土有遗书，问俗今还一驻车。","禾黍近来耕稼满，烟锄云锸遍新畬。"]},{"t":"巡历塞北杂咏四首 其四","f":"七言绝句","c":["塞北风多露气凉，幔城坐听漏声长。","只今六月浑无暑，已见飘来木叶黄。"]},{"t":"杨川","f":"五言绝句","c":["塞柳多于荠，清川逐望平。","西风吹几日，碎叶欲成城。"]},{"t":"细河","f":"五言律诗","c":["一水沙冈外，回流甲帐前。","日长时饮鹿，风至忽闻蝉。","棕叶铺凉殿，松花落细旃。","从来销夏地，未胜此中偏。"]},{"t":"塞北早秋","f":"五言律诗","c":["万马边声合，千旓障口开。","霜威随出塞，秋色壮登台。","雁度连营去，鹰呼绝巘回。","苍茫云海月，永夜照龙堆。"]},{"t":"兴安夜","f":"七言绝句","c":["连峰横亘塞东西，缇幕高临百尺梯。","坐觉银河天际近，仰看珠斗夜深低。"]},{"t":"次杨岭北","f":"五言绝句","c":["半岭黄云合，新凉画角闻。","羱羊沙草外，落日自为群。"]},{"t":"过团河","f":"五言绝句","c":["远水团沙白，温风绝塞收。","三星流火夕，已拥翠云裘。"]},{"t":"次石山","f":"七言绝句","c":["凉生旌羽露华漙，画角声高夜未阑。","行幄不知三伏过，仗前翻觉六军寒。"]},{"t":"尖峰山谷口作","f":"七言绝句","c":["塞山秀出亦娟娟，细路穿林碧磴悬。","却为晚来飞雨过，数峰横翠入寒烟。"]},{"t":"三道河晚望","f":"五言绝句","c":["碛树隐雾深，河流带沙浅。","不须朔吹高，先有飞蓬卷。"]},{"t":"黄草川","f":"七言绝句","c":["烟沙一片塞天围，旧说秋高苜蓿肥。","今日边屯皆乐土，茅檐松火接金微。"]},{"t":"回銮抵古北口","f":"七言律诗","c":["黄谷清河古戍间，銮车此日省方还。","长林曲抱千溪水，小径斜通万仞山。","地扼襟喉趋朔漠，天留锁钥枕雄关。","时平不用誇形胜，云物秋澄斥候閒。"]},{"t":"中秋日闻海上捷音","f":"七言律诗","c":["万里扶桑早挂弓，水犀军指岛门空。","来庭岂为修文德，柔远初非黩武功。","牙帐受降秋色外，羽林奏捷月明中。","海隅久念苍生困，耕凿从今九壤同。"]},{"t":"是夜对月再成绝句","f":"五言绝句","c":["明月中秋节，驰书海外来。","自今天汉上，万里烟云开。"]},{"t":"秋日再过阜平","f":"五言古诗","c":["春经阜平县，夹道多榛杞。","雉堞久倾颓，郛郭仅遗址。","耆老遮马前，其言质且俚。","土硗愿力田，三时事耘耔。","所苦井税输，道远越山水。","闻之切痛瘝，宁尔在干止。","有司近拊循，疮痍庶能起。","十室忠信存，何况境百里。","郊圻戒申画，风土亦洵美。","问俗此重来，居民咸色喜。","易彼蒿与莱，荒涂渐成市。","经野得良图，可以喻治理。"]},{"t":"再驻龙泉关","f":"五言律诗","c":["高临晴雨外，绝磴似凌空。","节物经冬异，关山对月同。","龙泉冰未白，雁塞叶初红。","历历曾游地，香台在眼中。"]},{"t":"冬日重登清凉山","f":"七言律诗","c":["紫府名山忆旧踪，招提驻䍐认云松。","阴崖尚有春时雪，落日仍听下界钟。","塞远浑河寒更白，林疏恒岳翠逾重。","祝釐交叶人天庆，银榜新题遍五峰。"]},{"t":"咏马","f":"五言绝句","c":["岐阳方较猎，騕袅尽龙媒。","仗下黄金勒，横秋号逸材。"]},{"t":"初冬自五台回次日雪","f":"五言律诗","c":["鸣銮多霁日，停旆雪纷纷。","色向寒初积，声宜静里闻。","捲帘山忽近，扫石径犹分。","却忆清凉界，峰连万壑云。"]},{"t":"盆中橘实甚繁咏此","f":"七言绝句","c":["厥包禹贡自扬州，作颂骚人楚泽留。","争似青条朱实好，移来满树洞庭秋。"]},{"t":"台湾平告祀孝陵有述","f":"古风","c":["缵武平瀛海，诹辰谒寝陵。","翠微千嶂拱，紫气五云凝。","圣德光垂裕，神谟大显承。","乾坤资翕辟，日月象升恒。","奕世讴歌集，多方历数膺。","远犹思燕翼，盛业想龙兴。","卉服皆来享，鲸波自此澄。","明禋稽旧典，万?肃尝蒸。"]},{"t":"玉河春水","f":"七言律诗","c":["春回冻解玉河清，潋滟晴光绕凤城。","翠岭雪消新涨阔，绿杨风动晓波平。","派分星海千重远，色映银潢万里明。","欲挽朝宗无限水，遍流膏泽慰苍生。"]},{"t":"仿二王墨迹","f":"古风","c":["春暮芳菲满禁林，鸾笺暇展学来禽。","银钩运处须师古，象管挥时在正心。","案上露凝铜雀润，帘前花照墨池深。","却思?篆原羲画，精理图畴细讨寻。"]},{"t":"紫光阁","f":"五言律诗","c":["政閒多豫日，别馆偶留连。","草绿含春气，花红带晓烟。","鸣禽听绕树，新水看浮船。","物理何曾息，从容忆抚弦。"]},{"t":"夜","f":"五言律诗","c":["良夜观图史，浑忘刻漏深。","月流金殿影，花转玉阶阴。","追琢崇民则，居稽长道心。","缅怀皇古治，四海遍讴吟。"]},{"t":"流杯亭晚眺有怀","f":"五言律诗","c":["霁宇开初夏，临池晚景鲜。","流觞观宇宙，列籍念桑田。","飞絮缘窗起，閒花傍槛妍。","读书新月下，讲道勉尧篇。"]},{"t":"晓起再赋","f":"五言律诗","c":["胜地堪修褉，斯亭乃得名。","颇饶松竹趣，无待管弦声。","一水涵天象，三阳畅物情。","政馀耽静赏，吟罢听流莺。"]},{"t":"夏日水云榭闻梵声","f":"七言绝句","c":["水榭周遮积翠苔，薰风拂处午云开。","忽听梵诵惊残梦，疑是金绳觉路来。"]},{"t":"偶成","f":"五言绝句","c":["石岸众芳静，斜阳柳色边。","挥毫意独远，鱼跃在深渊。"]},{"t":"瀛台","f":"五言律诗","c":["岁序开炎节，离宫绕翠微。","莲香闻讲席，柳色映垂衣。","物阜风光好，时清奏牍稀。","罢朝鹓鹭散，花下佩声归。"]},{"t":"塞外省览风俗","f":"五言律诗","c":["莫道岩关险，要荒总一家。","戍楼无鼓角，战垒是桑麻。","野静知民乐，时清见物华。","林中归径晚，旌旆满烟霞。"]},{"t":"再至红川避暑","f":"五言律诗","c":["塞外留銮跸，长林帐殿幽。","乍看南火历，已动北山秋。","露冷轻葵箑，花寒御绮裘。","重来欣胜赏，斯地即丹邱。"]},{"t":"红川秋兴","f":"五言绝句","c":["俛视八方尽，高天峻岭分。","秋风起孤韵，日色下溪云。"]},{"t":"回銮至鳍鬣口秋雨初霁对月","f":"五言律诗","c":["纤月高林动，辉辉古塞长。","冰轮初濯露，桂影欲飘香。","乌鹊声频起，关河色共凉。","旌门吟眺远，万国自清光。"]},{"t":"咏史四首 其一","f":"五言古诗","c":["鸿钧运元气，万汇无私恩。","上德贵醇闷，容覆如乾坤。","熙熙康衢老，作息循晨昏。","耕凿食其力，安知帝德尊。","在宥物自理，巧历难为言。","下览商周际，颂声亦已繁。"]},{"t":"咏史四首 其二","f":"五言古诗","c":["三田岁毕举，用以荐明禋。","圣王戒暴殄，郊薮游麒麟。","虞罗张复解，原野气已春。","六合岂不广，一面何逡巡。","亳都百里间，旷如天地仁。","宽政逮毛羽，况乃蚩蚩民。"]},{"t":"咏史四首 其三","f":"五言古诗","c":["轩皇访后牧，相道光璿枢。","精诚契冥漠，在古岂有诬。","巍巍兴王佐，竟与梦寐符。","天意靖殷邦，岂为荣一夫。","缅彼耕莘叟，后有版筑徒。","试观说命篇，典则追三谟。"]},{"t":"咏史四首 其四","f":"五言古诗","c":["尚父抱奇略，壮龄运不偶。","一竿清渭滨，经纶在其手。","志欲网九州，吞舟非所取。","卜兆示先几，龙螭载车后。","白旄师既陈，青社符还剖。","伟哉八百基，肇自一钓叟。"]},{"t":"仇英青绿画","f":"七言绝句","c":["流莺百啭起烟槐，细雨油云点翠苔。","松竹青青山色静，游人倚杖尚徘徊。"]},{"t":"东巡出都作","f":"五言绝句","c":["阊阖来天风，玉仗排双凤。","乔岳耸高标，巡方翠华动。"]},{"t":"晾鹰台集蒙古诸部落慰劳遣之","f":"七言绝句","c":["秋尽高原霁景清，远人马首颂巡行。","九经自重怀柔意，欲使遐陬识治平。"]},{"t":"河间即古瀛州地","f":"五言律诗","c":["新霜来朔气，纳稼满西畴。","省敛因农暇，观风廓远猷。","箕躔分冀野，舆地古瀛州。","驻辔郊坰外，斜阳下堞楼。"]},{"t":"景州观开福寺塔","f":"五言律诗","c":["涌塔高凌汉，穹隆拱法筵。","虚铃含远籁，密宇绕寒烟。","不问三车法，空劳七宝悬。","偶过成小憩，漫比布金田。"]},{"t":"次德州即事","f":"五言绝句","c":["近郭人烟集，遥天月上初。","新寒添夜漏，不寐坐看书。"]},{"t":"九河故道","f":"五言绝句","c":["野树迷深岸，荒荆露浅沙。","还思乘四载，岂效泛浮槎。"]},{"t":"平原","f":"古风","c":["冬晴柳叶未落，潦尽寒潭初清。","龙镳千骑万骑，雁队一声两声。"]},{"t":"渡济水","f":"古风","c":["晓渡更临济水，野风时捲霓旌。","几曲寒流荡漾，十月舆梁始成。"]},{"t":"巡幸东省黎庶拥马瞻拜命诃警者弗禁得以察其疾苦","f":"七言律诗","c":["东来端为重民生，不事汾阴泰畤名。","井里俨存齐国俗，田畴还忆历山耕。","暂宽羽骑钩陈卫，一任村童野老迎。","敢道迩言勤访察，止期治理得舆情。"]},{"t":"趵突泉","f":"五言律诗","c":["十亩风潭曲，亭间驻羽旂。","鸣涛飘素练，迸水溅珠玑。","汲杓旋烹鼎，侵阶暗湿衣。","似从银汉落，喷作瀑泉飞。"]},{"t":"登济南城望华不注","f":"七言绝句","c":["百雉城临济水隈，云山环拱接青莱。","更看瘦削孤峰色，独立亭亭秀作堆。"]},{"t":"登岱","f":"七言律诗","c":["岩岩岱岳高无极，攀陟遥登最上头。","路转天门青霭合，峰回日观白云浮。","振衣巀嵲凌千仞，骋目苍茫辨九州。","欲与臣邻崇实政，金泥玉检不须留。"]},{"t":"百丈崖观瀑","f":"七言绝句","c":["悬崖千尺响奔湍，涧道嶒嵘动石澜。","仿佛清天有风雨，松阴漠漠逼人寒。"]},{"t":"岱顶对月","f":"五言古诗","c":["夜宿乔岳颠，缥缈近云阙。","孤高绝尘翳，天外见明月。","不闻城市喧，惟听空籁发。","开轩肆遐览，万象争突兀。","对此心悠然，清梦自超越。"]},{"t":"汶水吟","f":"七言绝句","c":["汶水潺潺清似玉，石涧萦纡行踯躅。","连山百里入莱芜，松柏绵蒙冬尚绿。"]},{"t":"蒙阴晓雪","f":"七言绝句","c":["一片寒云向晓封，雪花应候慰三农。","马蹄碎踏琼瑶路，隔断蒙山顶上峰。"]},{"t":"沂水","f":"五言绝句","c":["板桥缇骑度，沙岸野舟移。","想像二三子，浴沂春暮时。"]},{"t":"渡黄河","f":"七言绝句","c":["河流九曲迅飞鸿，千里能施润泽功。","疏凿远怀神禹迹，乘虚快睹满帆风。"]},{"t":"途次网得鲜鱼驰进两宫兼志思慕之诚","f":"七言绝句","c":["千里难承玉陛欢，鲜鳞网得劝加餐。","遥知长信开函日，定荷慈颜一笑看。"]},{"t":"晚经淮阴","f":"七言绝句","c":["淮水笼烟夜色横，栖鸦不定树头鸣。","红灯十里帆樯满，风送前舟奏乐声。"]},{"t":"平山堂","f":"七言律诗","c":["宛转平冈路向西，山堂遗构白云低。","帘前冬暖花仍发，檐外风高鸟乱啼。","仙仗何尝惊野梦，鸣镳偶尔过幽栖。","文章太守心偏忆，墨洒龙香壁上题。"]},{"t":"天宁寺","f":"七言绝句","c":["小艇沿流画桨轻，鹿园钟磬有馀清。","门前一带䢴沟水，脉脉常含万古情。"]},{"t":"由仪真乘巨舰至京口","f":"七言古诗","c":["长江万里开鸿濛，高樯巨楫乘艨艟。","仪真京口路百里，挂帆瞬息凌长风。","汀芦洲树看历历，波恬浪阔光瀜瀜。","遄流直下入沧海，远源上与岷峨通。","山川断续合云雾，日月照耀浮虚空。","舟行迅速疾飞驶，恍闻击鼓冯夷宫。","柂楼高据极观眺，奇纵豁达舒心胸。","年来江汉罢桴鼓，河海清宴绝战攻。","舳舻閒系沙岸侧，水师捲甲悬长弓。","羽葆南巡渡扬子，居安更念艰难功。"]},{"t":"金山","f":"五言律诗","c":["一览江天胜，东南势尽收。","帆樯来极浦，台榭起中流。","路出丹崖上，烟同碧汉浮。","登临豁心目，浩荡俯沧洲。"]},{"t":"试中泠泉","f":"五言绝句","c":["缓酌中泠水，曾传第一泉。","如能作霖雨，沾洒遍山川。"]},{"t":"妙高台","f":"五言律诗","c":["台高绝众鸟，临眺畅清襟。","渺渺沙洲树，青青远岸岑。","波涛岩下接，洞壑槛边深。","江水明如镜，弥徵天地心。"]},{"t":"铁瓮城","f":"七言律诗","c":["万里晴江拥舳舻，城高铁瓮接康衢。","遗铭欲探华阳迹，旧宅难寻海岳图。","半面烟岚雄北固，一方形势控东吴。","龙舟漫道巡行盛，多恐深居政未敷。"]},{"t":"竹林禅院在润州城南竹径数里","f":"五言古诗","c":["一径入深竹，数里来上方。","丛生岩磴密，枝拂云烟长。","华旗出林际，芝盖停三阳。","飒飒吹霜风，碧叶纷翱翔。","山斋颇幽寂，万籁含虚光。","触物感予怀，歌彼淇澳章。"]},{"t":"夜过丹阳","f":"七言绝句","c":["锦缆徐牵夜未停，遥天烟霭淡疏星。","居人两岸明灯火，早是轻帆过驿亭。"]},{"t":"途中览皇太子仿书以示之","f":"七言绝句","c":["奎文一画开天象，保氏先教识六书。","笔势须知贵严正，好将功力足三馀。"]},{"t":"锡山","f":"五言律诗","c":["朝游惠山寺，閒饮惠山泉。","漱石流仍洁，分池溜自圆。","松间幽径辟，岩下小亭悬。","聊共群工濯，天真本浩然。"]},{"t":"吴阊","f":"七言律诗","c":["鸣銮独上高城望，巷陌遥通水寺斜。","土俗惟知斗歌舞，闾阎不解种桑麻。","鸟啼茂苑千年树，霜冷吴宫十月花。","声教四方犹未讫，愿将淳朴变繁华。"]},{"t":"虎邱","f":"七言绝句","c":["小阜回冈落照红，长廊曲榭构西东。","独怜剑石潺湲水，霸业销沉在此中。"]},{"t":"句容道上","f":"五言律诗","c":["渐入茅山境，来当农暇时。","但看初日上，未觉朔风吹。","碧敛寒塘水，红垂野树枝。","江南经几郡，民俗欲周知。"]},{"t":"雨花台","f":"五言律诗","c":["何地飞花雨，晴空无片云。","江山恣遐瞩，草树出清芬。","城郭参差见，楼台远近分。","人家百万户，烟火尽氤氲。"]},{"t":"幸报恩寺","f":"七言绝句","c":["凤刹高悬上界灯，珠缸璧带一层层。","平临下见诸天小，晴日江山万里澄。"]},{"t":"驻跸金陵以方物寄献两宫","f":"五言律诗","c":["深宫违定省，经月恋晨昏。","率土方为养，苍生共戴尊。","题书千里重，托物寸心存。","遣使旌门外，踟蹰望九阍。"]},{"t":"金陵旧紫禁城怀古","f":"七言律诗","c":["秣陵旧是图王地，此日鸾旗列队过。","一代规模成往迹，六朝兴废逐流波。","宫墙断缺迷青琐，野水湾环剩玉河。","治理艰勤重殷鉴，斜阳衰草系情多。"]},{"t":"江宁驻跸皇太子启至请安兼报读完四书","f":"五言古诗","c":["先圣有庭训，所闻在诗礼。","虽然国与家，为学无二理。","昨者来江东，相距三千里。","迢遥蓟北云，念之不能已。","凌晨发邮筒，开缄字满纸。","语语皆天真，读书毕四子。","龆年识进修，兹意良足喜。","还宜日就将，无令有间止。","大禹惜寸阴，今当重分晷。","披卷慕古人，即事探奥旨。","久久悦汝心，自得刍豢美。"]},{"t":"示江南大小诸吏","f":"五言古诗","c":["东南财赋地，江左人文薮。","时巡历此疆，民事日探剖。","风俗贵淳庞，纷奢讵能久。","澄清属大吏，表率群僚首。","郡县布慈和，恺悌歌父母。","民者国之本，生计在畎亩。","六府既孔修，三事安可后。","教化默转移，各须尽官守。","户使敦诗书，人知崇孝友。","庶几远迩氓，皞皞登仁寿。","诰诫申予怀，斯言慎不负。"]},{"t":"燕子矶夜泊","f":"七言律诗","c":["巍峨一片江头石，千载人传燕子矶。","疑有鼋鼍藏窟宅，时闻钟磬出山扉。","牙樯缓住寒烟净，羽卫周连夜火围。","沙岸声声动行漏，芦花深处雁惊飞。"]},{"t":"高邮湖见居民田庐多在水中因询其故恻然念之","f":"古风","c":["淮扬罹水灾，流波常浩浩。","龙舰偶经过，一望类洲岛。","田亩尽沉沦，舍庐半倾倒。","㷀㷀赤子民，栖栖卧深潦。","对之心惕然，无策施襁褓。","夹岸罗黔黎，跽陈进耆老。","?诹不厌频，利弊细探讨。","饥寒或有由，良惭奉苍颢。","古人念一夫，何况睹枯槁。","凛凛夜不寐，忧勤惄如捣。","亟图浚治功，拯济须及早。","会当复故业，咸令乐怀保。"]},{"t":"阅河堤作","f":"五言律诗","c":["防河纡旰食，六御出深宫。","缓辔求民隐，临流叹俗穷。","何年乐稼穑，此日是疏通。","已著勤劳意，安澜早奏功。"]},{"t":"泉林寺即子在川上处","f":"七言绝句","c":["偶从川上驻行旃，密树重林带野烟。","俯仰古今成一辙，源泉昼夜尚涓涓。"]},{"t":"途中长至","f":"七言律诗","c":["旌门已报黄钟节，六琯葭飞律未残。","叆叆占云书太史，玱玱执玉忆郊坛。","阳升一线宫中日，冰合重渊野外寒。","景福重闱应有庆，晴光捧处是长安。"]},{"t":"阙里古桧","f":"五言律诗","c":["干耸朱甍外，根蟠碧殿阿。","奇文成左纽，元气挺孤柯。","瑞与龟龙并，传来岁月多。","徘徊看手泽，不共劫灰磨。"]},{"t":"晚到河间太皇太后使人送乳饼食物","f":"七言律诗","c":["綵斿晚驻瀛州道，忽报铜龙骑使来。","心识慈怀同日照，口传温语逐阳回。","松脂似截盘中玉，绮食初和鼎内梅。","两月几虚甘旨奉，归程欲听晓钟催。"]},{"t":"巡幸回宫内殿进讲毛诗","f":"七言绝句","c":["丹甍绣户拂寒霜，静读毛诗意觉长。","讨论一言穷六义，道心少悟爱斜阳。"]},{"t":"原任总督于成龙居官清廉自古罕有特命诸臣议恤以励官方","f":"五言古诗","c":["服官敦廉隅，抗志贵孤洁。","扬历著贤声，谁能茹荼檗。","况复拥旌麾，藜藿甘以悦。","视彼悬鱼操，于今尤峻烈。","东南失保釐，言念心如结。","江上见甘棠，遗爱舆人说。","恤典宜优崇，庶不负清节。","匪独彰国常，且以风在列。"]},{"t":"蓟城遇雪","f":"七言绝句","c":["冻云封树蓟城西，玉蕊轻盈乱马蹄。","忆想年年常过此，何曾瑞雪遍山溪。"]},{"t":"读左氏春秋作","f":"五言律诗","c":["夫子维王道，褒诛汗简青。","千秋师凤德，三传翼麟经。","义理资参校，丹铅彻昼冥。","静中欣悟入，古训是新铭。"]},{"t":"季夏游西山忆旧","f":"五言律诗","c":["寻芳踏绿野，万紫迷深溪。","地远峰头阔，山高水势低。","飞花疑旧梦，烟柳促新题。","沙暖鸳鸯睡，萋萋草满堤。"]},{"t":"咏花","f":"七言绝句","c":["奇蕊琼葩缀碧枝，幽香独占美丰姿。","薰风初到窗前赏，疑是仙花月下移。"]},{"t":"苦热戏作","f":"七言律诗","c":["数年不见歊蒸热，于今炽日最难当。","披襟气蹙三庚远，近榻神昏九夏长。","烦暑时侵高阁上，炎光每到小楼傍。","微凉须动清风扇，勉力勤民阅奏章。"]},{"t":"雨中远望","f":"五言律诗","c":["庭槐开御幄，云气逼遥岑。","雨湿銮铃重，风吹辇路深。","芭蕉分碧叶，䓿萏荐香林。","极目天边望，斜阳半岭阴。"]},{"t":"初秋","f":"七言绝句","c":["大火初收暑气残，金风吹动芰荷寒。","鸣蝉送夏声声急，雨霁遥天万里看。"]},{"t":"中元日蕉园作","f":"五言律诗","c":["中元来太液，新爽下林端。","水槛临流入，风窗捲幔看。","鱼游迷藻荇，鸥戏悦沙滩。","宇宙无尘翳，凉生月一团。"]},{"t":"复游盘山绝顶","f":"五言律诗","c":["绝顶巉岩里，松烟向晓开。","片云生众壑，虚籁落空台。","寺古人行少，林深鸟乱回。","千峰多秀色，远眺足徘徊。"]},{"t":"夏日口外寄宫中","f":"五言律诗","c":["翠盖鸾旌出，平明刻漏同。","油云驱暑气，时雨引清风。","山脉经年秀，泉形此日充。","遥遥千里外，回首忆深宫。"]},{"t":"避暑畅春园雨后新月","f":"七言绝句","c":["园亭气爽雨初晴，新月胧胧透树明。","漏下微眠思治道，未知清夜意何生。"]},{"t":"喜雨诗十六韵","f":"五言古诗","c":["体国为民事，忧勤固在斯。","骄阳春既盛，膏泽夏愆期。","省刑书每下，请雨令频施。","云未油然作，风偏飒尔吹。","芃芃苗欲槁，细细草将萎。","翘首瞻青汉，焦心对赤墀。","圜扉重举滞，旃厦几畴咨。","斋祭祈神鉴，精诚只已知。","谁云天最远，于是听能卑。","默处敬居日，恭虔步祷时。","微衷惭上格，大化喜潜移。","霶霈滋南亩，飘潇遍九逵。","叆叇阴阳协，滂沱渥泽垂。","田家还自乐，朝野共吟诗。","从此烦襟涤，由来百志熙。","愿同兹砥砺，参赞奉无私。"]},{"t":"南巡再过济南","f":"七言律诗","c":["六御重经历下城，频将疾苦问苍生。","肩摩毂击风犹在，土沃农恬世久平。","户户春灯佳节过，村村社鼓乐郊盈。","韶年渐布阳和泽，淑气晴光仗外横。"]},{"t":"观珍珠泉","f":"七言绝句","c":["一泓清浅漾珠圆，细浪潆洄小荇牵。","偶与诸臣閒倚槛，堪同鱼藻入诗篇。"]},{"t":"经泰山之麓","f":"七言律诗","c":["耸巘高峰记昔攀，春回瀑水响潺潺。","万层石级云霄上，千里烟村缥缈间。","暂驻犹然思往事，凭陵直欲小人寰。","朱旗翠葆疏林外，已见巍巍俯众山。"]},{"t":"再过淮南","f":"五言古诗","c":["前来历兹境，斯民似未遂。","今日再经过，风土觉有异。","纨褐既充体，庐舍各完置。","拥道欢趋迎，扶老与携稚。","咸云获休息，近免徭役累。","水患日就平，田畴可耕植。","一饮与一食，莫不歌帝赐。","素念切民依，时为劳寤寐。","大造本无私，湛恩欲广被。","闻言聊自宽，庶慰省方意。"]},{"t":"淮城晓霜闻雁","f":"七言绝句","c":["天际晨光水月连，带霜归雁向前川。","盂城晓发寒仍在，谈笑春风杂紫烟。"]},{"t":"蠲江南逋赋","f":"七言绝句","c":["国家财赋东南重，已责蠲租志念殷。","膏泽何妨频见渥，普天愿与乐耕耘。"]},{"t":"过维扬","f":"五言律诗","c":["重过䢴沟地，春风细草生。","帆樯连贾舶，笙吹满江城。","物力须教惜，民情亦见诚。","繁华当淑景，气象喜充盈。"]},{"t":"金山江天寺","f":"五言律诗","c":["独爱江天寺，停桡上碧峰。","波澜声浩浩，楼阁势重重。","日暖浮双树，风微送午钟。","遥看南北岸，春色澹春容。"]},{"t":"焦山","f":"五言古诗","c":["焦山何岝㟧，遥与金山峙。","草木尽蒙茸，幽偏隔城市。","放舟下中流，攀萝上涯涘。","隐士不可招，鹤铭洵足纪。","栖鹘惊人飞，暮云千万里。"]},{"t":"驻跸金山","f":"七言绝句","c":["烟雾空濛水国昏，夜移凤舸泊山门。","然犀欲照鼋鼍窟，卧听涛声自吐吞。"]},{"t":"雨过锡山","f":"七言绝句","c":["轻云冉冉雾弯环，细雨丝丝羃远山。","画舫青帘开晓坐，平波漫衍白鸥閒。"]},{"t":"虎丘望山后","f":"五言绝句","c":["试剑空存石，生公尚有台。","爱看山后景，错落野田开。"]},{"t":"邓尉小轩望太湖","f":"七言绝句","c":["山轩閒坐倚前楹，万顷澄湖夕照明。","夜久天心初月上，笙簧谡谡奏松声。"]},{"t":"登灵岩","f":"七言律诗","c":["霏微灵雨散春烟，按辔逍遥陟翠巅。","香水通流明若箭，琴台列石势如拳。","诸峰尽在青萝外，万井全依綵仗前。","闻是吴宫花草地，空馀钟磬梵王筵。"]},{"t":"晚过吴江","f":"七言绝句","c":["垂虹蜿蜒跨长波，画戟牙樯薄暮过。","灯火千家明似昼，好风好雨祝时和。"]},{"t":"入平望","f":"七言绝句","c":["锦缆无劳列綵艭，轻桡自爱倚船窗。","勤民不惮周行远，早又观风向浙江。"]},{"t":"禾中道上","f":"七言绝句","c":["两岸人家半种桑，雨中入望尽苍茫。","民间本业惟农织，爱看山村共水乡。"]},{"t":"巡幸杭州","f":"七言律诗","c":["东南上郡古临安，亲采风谣一省观。","翠岫巃嵷犹舞凤，羽旗简约不鸣銮。","春晖草木江山丽，户满弦歌雨露宽。","德化远敷吾未信，如何夹路万声欢。"]},{"t":"吴山","f":"七言绝句","c":["左控长江右控湖，万家烟火满康衢。","偶来绝顶凭虚望，似向云霄展画图。"]},{"t":"泛舟西湖","f":"七言律诗","c":["一片湖光潋滟开，峰峦三面送青来。","轻舟棹去波添影，曲岸移时路却回。","春色初摇堤上柳，惠风正发寺边梅。","此行不是探名胜，欲使阳和遍九垓。"]},{"t":"西溪","f":"五言律诗","c":["十里清溪曲，修篁入望深。","暖催梅信早，水落草痕侵。","俗藉渔为业，园饶笋作林。","民风爱淳朴，不厌一登临。"]},{"t":"题西溪山庄以竹窗二字书赐高士奇","f":"五言绝句","c":["花源路几重，柴桑皆沃土。","烟翠竹窗幽，雪香梅岸古。"]},{"t":"过桃花岭至玉泉寺","f":"七言绝句","c":["度岭穿云路始平，停镳聊憩小池清。","游鱼自有悠然意，岂识乾坤造物宏。"]},{"t":"湖心亭","f":"五言绝句","c":["水上起楼台，湖面平如镜。","春风吹柳条，远与山光映。"]},{"t":"渡钱塘江","f":"七言律诗","c":["雪后春烟漠漠浮，扬舲击楫向中流。","江通潮汐分吴地，路入溪山隐越州。","振武戈矛皆驻马，省方斿葆此乘舟。","风帆沙鸟看何限，远近云霞望里收。"]},{"t":"山阴","f":"七言绝句","c":["灌木丛篁傍水幽，澹烟晴日漾芳洲。","兰桡摇过山阴道，在昔人传镜里游。"]},{"t":"登卧龙山越望亭","f":"七言绝句","c":["周览山川历井疆，越峰突兀见青苍。","争流万壑通城郭，一一看来在下方。"]},{"t":"虎跑泉","f":"五言绝句","c":["松林带馀雪，空山啼百舌。","石溜响涓涓，寒泉自清洁。"]},{"t":"灵隐寺","f":"五言律诗","c":["灵山结幽秀，鹫岭起嵯峨。","梵宇盘空出，香云绕地多。","开襟对层碧，下马抚烟萝。","羽卫閒来往，非同问法过。"]},{"t":"飞来峰","f":"七言绝句","c":["岩岫崚增洞壑奇，悬藤古木半迷离。","冷泉亭子清溪上，谁识源头混混时。"]},{"t":"谕浙省将吏军民","f":"五言古诗","c":["省方浙西东，山川极遐瞩。","兹晨当回銮，谆谆一相勖。","军民贵安和，文武须联属。","息忿可无争，守分在忍辱。","日使讼庭閒，愚民免械梏。","奢侈尤当惩，繁华莫恣欲。","俭乃保其富，素履各敦笃。","惟令教化兴，益见闾阎足。","诸吏宜勉之，期归淳朴俗。"]},{"t":"舟中书怀","f":"七言律诗","c":["澹澹春山暮霭清，和风拂柳入帘轻。","留情远寄悬千里，抚景兴怀历几程。","寒尽梅中初霁雨，诗成洲上忽闻莺。","船窗睡起疑宫阙，月满江湖听棹声。"]},{"t":"将游华山以欲雨未往","f":"七言绝句","c":["欲向青山涧壑行，春云又变晓阴轻。","勾陈不遣惊禅定，恐碍林间碧草生。"]},{"t":"雨中幸锡山园林","f":"五言律诗","c":["澹冶青山色，幽探傍晓来。","烟笼岩下竹，雨洗石边苔。","断续听啼鸟，飘摇惜落梅。","胸襟原浩荡，随意坐亭台。"]},{"t":"惠泉","f":"七言绝句","c":["寒云覆树昔年经，再品山泉到此亭。","春水一犁农事足，喜看膏雨遍郊坰。"]},{"t":"句容雨望","f":"五言绝句","c":["山行逐高低，四望多松树。","雨里万人家，遥看隔云雾。"]},{"t":"巡幸江宁","f":"七言律诗","c":["南省封疆惟此区，江流环绕壮规模。","华旗芝盖重临幸，二水三山半画图。","吏事莫先田野治，民情但愿闾阎孚。","不知比岁恩波洽，止听黄童白叟呼。"]},{"t":"赐江宁文武将士宴于教场","f":"七言律诗","c":["瑞云捧日晓初晴，丽景天开羽仗明。","扈跸赳桓多绛灌，分行俊誉尽璁珩。","三浆满浥沾须遍，五载南巡泽再倾。","文穆武恬惭化理，万方无事宴升平。"]},{"t":"再过明故宫","f":"七言绝句","c":["楼台金粉已沈销，不独诗人说六朝。","月落宫垣春寂寂，经过惟叹草萧萧。"]},{"t":"江宁驻跸","f":"七言律诗","c":["心勤民隐独咨诹，不为江山作胜游。","白下回銮期已近，黔黎拥道欲何求。","多怜野老堆盘献，勉就舆情两日留。","二十八年宵旰意，岂图远迩慕怀柔。"]},{"t":"后湖","f":"五言绝句","c":["淼淼长湖水，春来发绿波。","飞鸣下凫雁，朝暮集渔蓑。"]},{"t":"登报恩寺浮图","f":"五言律诗","c":["涌地千寻起，摩霄九级悬。","琉璃垂法相，翡翠结香烟。","缔造人功巧，流传世代迁。","旷然弥远望，万象拱诸天。"]},{"t":"上巳日再登金山","f":"五言绝句","c":["晴和逢上巳，况在大江滨。","正是回銮日，挥毫记此辰。"]},{"t":"长江夜月","f":"五言律诗","c":["万顷沦涟映，平沙一望收。","天光起水色，云影共波流。","隔岸姑苏远，临轩夜月浮。","民情咸自得，何必泛龙舟。"]},{"t":"晓发维扬顺风扬帆午馀已过秦邮","f":"五言绝句","c":["傍晓发芜城，风帆疾如驶。","晚照半平湖，舟行百馀里。"]},{"t":"自宿迁解缆一日夜达山东境","f":"七言绝句","c":["千里南程几日回，轻舟直下溯潆洄。","天风更假帆樯便，一夕山东境上来。"]},{"t":"途次书怀","f":"七言绝句","c":["长乐慈颜两月违，白云迢递恋春晖。","轻舟不系兼程进，应话民风坐漏稀。"]},{"t":"忧旱忆民事作","f":"五言律诗","c":["仲夏炎曛盛，德凉时未和。","骄阳因六事，亢旱最三河。","民以食为重，天将风更多。","忧勤难暇顾，惟诵悯农歌。"]},{"t":"挽大行皇后诗四首 其一","f":"七言律诗","c":["月掩椒宫叹别离，伤怀始觉夜虫悲。","泪添雨点千行下，情割秋光百虑随。","雁断衡阳声已绝，鱼沈沧海信难期。","繁忧莫解衷肠梦，惆怅销魂忆昔时。"]},{"t":"挽大行皇后诗四首 其二","f":"七言律诗","c":["交颐泪洒夕阳红，徒把愁眉向镜中。","露冷瑶阶增寂寞，烟寒碧树恨西东。","旧诗咏尽难回首，新月生来枉照空。","鸾影天涯无信息，断弦声在未央宫。"]},{"t":"挽大行皇后诗四首 其三","f":"五言律诗","c":["音容悲渐远，涕泪为谁流。","女德光千祀，坤贞应九州。","凉风销夜烛，人影散琼楼。","叹此平生苦，频经无限愁。"]},{"t":"挽大行皇后诗四首 其四","f":"五言律诗","c":["淅沥动秋声，中心郁不平。","离愁逢叶落，别恨怨蛩鸣。","寂寂瑶斋隔，沈沈碧海横。","玉琴哀响辍，宵殿痛残更。"]},{"t":"中秋书怀","f":"七言律诗","c":["多病多悲感百端，暂来此地驻琼銮。","岩间雨歇衣还湿，岭外云开露未乾。","风激清潭三汲浪，秋催堕叶五更寒。","惊看圆月峰头出，似照愁肠劝夕餐。"]},{"t":"守陵太监崔邦琪侍慈宁宫年久诗以赐之","f":"五言律诗","c":["返照寒松影，心悬泣露霜。","一生常感悼，数载几悲凉。","恨接云峰近，思连沧海长。","问安劳梦想，绝矣九回肠。"]},{"t":"康熙二十八年岁旱冬又无雪朕焦心劳思寝食俱废二月初间谒陵路遇大雨田野欢声方少抒朕怀故赋五言律以记之","f":"五言律诗","c":["念愆思云汉，望岁意真纯。","稼穑三时重，祈丰六事频。","风恬咸自乐，雨洒易为春。","高下皆沾足，方知天至仁。"]},{"t":"咏花瓶","f":"七言绝句","c":["撷取群芳置案头，天香一段贮清幽。","人生常有悲欢事，惟尔閒情不晓愁。"]},{"t":"雨后初晴戏作二首 其一","f":"七言绝句","c":["山腹重云锁晚烟，水光逐浪共天连。","长桥疑作虹蜺似，落照扁舟湖上眠。"]},{"t":"雨后初晴戏作二首 其二","f":"七言绝句","c":["新晴雨后映斜阳，草茂花繁处处香。","石色苍苔随岸绿，桥边垂柳挂丝长。"]},{"t":"命裕亲王福全皇长子允禔帅师征厄鲁特锡之以诗","f":"五言古诗","c":["万国勤怀保，三阶愿治平。","寰中皆赤子，域外尽苍生。","小蠢忘帡冒，天心解斗争。","执迷思梗化，伐罪事专征。","武略期无敌，王师出有名。","亲藩分鈇钺，长子拥麾旌。","貙虎资郎将，貔貅壮禁营。","玉戈凝晓色，金甲耀秋晴。","获丑宁遗类，筹边重此行。","据鞍军令肃，横槊凯书成。","烟火疆隅堠，牛羊塞上耕。","遐荒安一体，归奏慰予情。"]},{"t":"养病塞北","f":"五言古诗","c":["寒蝉鸣野树，旅雁过秋蓬。","岭外皆红叶，城边有绿桐。","身虚苦夏热，多病爱清风。","山色犹然在，人颜渐不同。","幸无烽火事，喜有智神功。"]},{"t":"古北塞上望月","f":"七言绝句","c":["桂树清光挂碧天，云开万里塞无烟。","远人向背由敷政，惟在筹边与任贤。"]},{"t":"康熙三十二年六月赐总督佛伦","f":"五言律诗","c":["东表闻风化，西秦作雨霖。","扬清知疾苦，激浊勉官箴。","旷世孤芳节，超伦千古心。","封疆资大吏，抚育代忧深。"]},{"t":"夏燕新莲 其二","f":"七言绝句","c":["丹桥绿柳啭黄鹂，碧涧深林对小池。","睡起閒情题画箑，薰风动处乐雍熙。"]},{"t":"初秋晚雨后观仪器","f":"七言律诗","c":["从容更觉静悠悠，片片荷香送小舟。","日落开窗云外景，风清拂户雨中秋。","宽怀自有数行字，乐志须操一算筹。","万物无穷最易晓，其间诸象列天球。"]},{"t":"初秋咏竹","f":"七言绝句","c":["森萃青青绕碧塘，霜姿霭霭动幽香。","寒风不变终身节，绿叶纷然映晚凉。"]},{"t":"閒坐咏竹","f":"古风","c":["门外千竿细竹，窗前万朵鲜花。","秋寒众色皆变，惟尔霜姿可嘉。"]},{"t":"咏金莲花","f":"五言律诗","c":["迢递从沙漠，孤根待品题。","清香拂槛入，正色与心齐。","磊落安山北，参差鹫岭西。","炎风曾避暑，高洁少人跻。"]},{"t":"祝巴林淑慧大长公主诗","f":"五言律诗","c":["长祝南山寿，愿言北斗诗。","祥开应帝女，釐降自金枝。","沙漠黎心服，坤贞天下知。","年年庆人瑞，岁岁赏瑶池。"]},{"t":"戏题自鸣钟","f":"七言绝句","c":["昼夜循环胜刻漏，绸缪宛转报时全。","阴晴不改衷肠性，万里遥来二百年。"]},{"t":"夏日舟行","f":"五言律诗","c":["灵液开仙仗，清晖映碧波。","黄鹂鸣茂树，归雁戏青莎。","水曲蒲帆转，岸回锦缆过。","三春曾布德，月下听讴歌。"]},{"t":"夏日幸潞河杂诗三首 其一","f":"七言绝句","c":["水色连天四望收，轻舠桂楫放中流。","东南惟有长江胜，一片云帆万里游。"]},{"t":"夏日幸潞河杂诗三首 其二","f":"七言绝句","c":["曾记当年幸潞河，翠旌熠爚映微波。","临流士女争瞻望，不禁扁舟唱棹歌。"]},{"t":"夏日幸潞河杂诗三首 其三","f":"七言绝句","c":["野云渐起罩斜阳，暮泊平沙觉水凉。","初更未寝吟诗句，静见炉中焚异香。"]},{"t":"亲阅运河堤","f":"五言古诗","c":["旧岁阴霖胜，忧勤亿兆难。","析津通鹊渚，形势接桑乾。","物理常求治，朝堂亦自安。","运堤久未整，岸堰最宜完。","夹道黎民悦，沿河老幼欢。","云容随豹尾，暑气拥仙銮。","九酝贤人酒，三浆龙凤团。","匡床搜典诰，流水奏幽兰。","棹响逼前驾，渔歌进小滩。","去回四百里，舟次五云端。"]},{"t":"舟泊潞河","f":"七言律诗","c":["万里帆樯宛转来，炎天系缆泊河隈。","长江曾著操舟说，短梦频思作楫才。","隔水翛翛秋麦起，绕林处处野花开。","从容披阅依书幌，静尔忘言忆九垓。"]},{"t":"二月三十日亲统六军徂征漠北","f":"五言古诗","c":["惟天尽所覆，眷命畀我清。","自予莅鸿祚，恒愿销甲兵。","狡焉窥北疆，属国横相撄。","夙昔张挞伐，凶丑皆颠倾。","赦之释不诛，开网全其生。","怙终恣跳梁，边鄙摇群情。","皇皇仁义师，声讨必有名。","春雪洒贝胄，朔风捲龙旌。","眷兹貙虎士，金革劳远征。","于铄振我武，赫赫扬天声。"]},{"t":"出居庸关","f":"五言律诗","c":["群峰倚天半，直北峙雄关。","古塞烟云合，清时壁垒閒。","军锋趋朔漠，马迹度重山。","渐向边城路，旌旗叠翠间。"]},{"t":"赤城","f":"七言律诗","c":["慈宫曾驻此温泉，展转依稀廿五年。","今日征途冰未解，当时冻岭雪还全。","渐近边关风土别，长驱旌旆岳山连。","孤城寒重深宵静，敢卜龙沙奏凯旋。"]},{"t":"龙门","f":"七言绝句","c":["绝巘何时凿五丁，双崖万仞辟门屏。","潺湲塞水嵯峨石，振旅归来定勒铭。"]},{"t":"过独石口","f":"七言律诗","c":["关名独石插遥天，路绕青冥绝嶂悬。","翠壁千寻标九塞，黄云万叠护三边。","霓旌晓度长城月，毳帐春回大漠烟。","总为民生勤战伐，不辞筹画在中权。"]},{"t":"出塞训厉军士","f":"七言绝句","c":["铁马金戈整六师，鼓行出塞暮春时。","边尘尽埽从今始，莫让天山建绩奇。"]},{"t":"北藩诸部君长来迎","f":"七言律诗","c":["关山直北尽王臣，属国侵陵煽乱频。","为靖边方勤士马，欲令藩落辑民人。","声灵有赫群知肃，抃舞来同意倍亲。","共睹此行清朔漠，保疆绥土俗还淳。"]},{"t":"沙漠二首 其一","f":"七言绝句","c":["高下龙堆万马趋，直将漠外作疆隅。","汉家只守飞狐岭，坐使中原失远图。"]},{"t":"沙漠二首 其二","f":"七言绝句","c":["沙碛荒榆细柳多，步行不用蹀鸣珂。","连朝登顿浑无倦，甘苦身先士荷戈。"]},{"t":"风雪致祷遂尔晴霁","f":"七言绝句","c":["塞外春深雨雪频，寒风犹自拂征尘。","昨朝遣祀咨宗伯，已见遥天霁色新。"]},{"t":"赐皇子允祉","f":"七言绝句","c":["玉弩金戈壮此行，期门环卫在连营。","深居莫忘勤劳意，须识间关出塞情。"]},{"t":"赐皇子允祐","f":"七言绝句","c":["逆我颜行讨必加，六军严肃静无哗。","分营此日如棋布，奋武群看捲塞沙。"]},{"t":"春寒轸念将士","f":"七言律诗","c":["大漠春残雪尚飞，从征车马正騑騑。","风回沙路迷金勒，寒送冰花上铁衣。","每念折冲凭士气，况从绝徼奉天威。","六军同奋赳桓志，伫见睛曛满翠旂。"]},{"t":"途中新夏","f":"七言绝句","c":["边草才青节序更，征裘未换入朱明。","遥思南陌东阡候，正是居人急耦耕。"]},{"t":"赐皇子允祀","f":"七言绝句","c":["戎行亲莅制机宜，栉沐风霜总不辞。","随侍晨昏依帐殿，焦劳情事尔应知。"]},{"t":"帐殿对雨念畿辅四方农事","f":"五言律诗","c":["气和时雨降，驻跸对荒陬。","点点侵油幕，霏霏湿翠斿。","未知同甸服，果足渥田畴。","轸念民依切，驰书付置邮。"]},{"t":"违皇太后定省言怀","f":"七言律诗","c":["帐殿风高日影移，庭闱常忆问安时。","寸心每自依清禁，慈念遥应系北陲。","柔远肯教罹疾苦，除残焉敢惜胼胝。","预期露布飞章入，早报瑶阶母后知。"]},{"t":"行殿示诸皇子","f":"五言古诗","c":["师行日已远，边马风萧萧。","眷言靖疆宇，宁惮道路遥。","彼寇邻北藩，谲谋声动摇。","除恶必拔本，稂莠隳良苗。","外攘内斯安，务令金甲销。","吾民息转输，丁男无敝彫。","一劳方永逸，所戒怠与骄。","天心鉴此诚，雨旸时以调。"]},{"t":"营夜南望北斗","f":"七言绝句","c":["碧琉璃界四垂边，渐觉云低欲到天。","为问北来行近远，果然北斗挂南川。"]},{"t":"雁栖沙碛","f":"七言律诗","c":["为靖风尘夜不眠，平沙四顾断人烟。","征夫欲度阴山外，北雁偏栖瀚海边。","黩武诗书天子戒，惟仁经史帝王先。","须看战垒生灵骨，吊古文章信可传。"]},{"t":"时乏水于山坡得泉志喜","f":"七言绝句","c":["麾兵深入贼巢边，斯地从来乏水泉。","报道六军齐饮马，清流山畔忽涓涓。"]},{"t":"克鲁伦河上流雨后草生","f":"七言绝句","c":["晚从岸曲驻前旌，雨歇行营草怒生。","一望青青河上色，平芜共听马嘶声。"]},{"t":"登山巅下瞰克鲁伦河周览山川形势指麾营阵","f":"古风","c":["策马登崇冈，冈势亦崔嵬。","浩浩见河流，迢递西隅来。","杳然罕人迹，周览复徘徊。","命我熊罴士，往驻山之隈。","旌旗布林麓，寇见应疑猜。","六师压其阵，贼势立崩摧。","麾示诸部曲，号令肃风雷。","俯视窟中?，殄灭同纤埃。"]},{"t":"军中夜尝擐甲达旦","f":"七言绝句","c":["四山风静建旌旄，帐外沙明片月高。","除逆安民非得已，终宵擐甲敢言劳。"]},{"t":"噶尔丹溃遁遂穷追之","f":"古风","c":["谩道爰爰?窟多，久从西路列雕戈。","疾驰莫惮追奔力，须使穷禽入网罗。"]},{"t":"自贼中投诚来者皆宥之","f":"七言绝句","c":["伐叛军声震若雷，奔亡贼势已全摧。","龙荒所至皆苍赤，许尔投戈向化来。"]},{"t":"遣使示皇太子捷音","f":"七言绝句","c":["逋寇多年快剪除，风清塞北已回车。","遥知念切驰相慰，驿骑南归赐捷书。"]},{"t":"示宫中捷音","f":"五言律诗","c":["向南瞻北斗，水际见飞鸿。","雪照平沙月，云生大漠风。","捷书传远塞，喜气溢深宫。","奏凯鸣銮近，新荷夏正中。"]},{"t":"班师拖陵留皇长子允禔殿后示之","f":"七言绝句","c":["北伐经时铁马驰，自春徂夏历边陲。","炎风暑雨归来日，留待旋镳抚六师。"]},{"t":"行间赐大学士张玉书","f":"五言律诗","c":["畴昔谋康阜，除顽事战攻。","若非扬九伐，何以靖三农。","古义严声讨，儒臣在折冲。","遐荒风雪里，扈跸纪军容。"]},{"t":"外藩诸部落络绎来贺宴赉之","f":"五言律诗","c":["诸部名王集，扶携绕御营。","皆言清朔漠，从此乐生成。","喜溢车书会，欢腾鼓角声。","朕怀勤抚恤，所志在休兵。"]},{"t":"南口","f":"七言绝句","c":["銮舆历远度龙城，已近郊圻一日程。","时雨润来山翠重，更添高下小溪声。"]},{"t":"入京见百官耆民童稚欢迎道周","f":"七言律诗","c":["星斿葆羽禁城闉，雨霁郊坰不动尘。","旭日薰风归凯路，黄童白叟太平人。","正逢师至经三月，敢比苗顽格七旬。","从此普天无战斗，更将休养勖臣邻。"]},{"t":"赐将军孙思克","f":"五言律诗","c":["天讨恭行日，军威战捷时。","列营张犄角，扼吭有偏师。","立见穷追尽，能承节制奇。","鹰扬资远略，宿望在西陲。"]},{"t":"朕偶至潭柘览老和尚照福画像因而有感故作诗赐之","f":"七言绝句","c":["法像俨然参涅槃，皆因大梦住山间。","若非明镜当台语，笑指真图并戒坛。"]},{"t":"赐皇太子生辰诗","f":"五言绝句","c":["百岁桐长老，千年松满枝。","万峰迎瑞气，亿兆庆灵芝。"]},{"t":"国舅佟国维六十寿诗以赐之","f":"七言律诗","c":["领袖高门称退让，英华雅望冠椒房。","谦和不恃勋臣贵，谨恪能承宠眷长。","鹤算天增筹国老，松年仙授养生方。","齐眉共享团圆庆，特赐流霞捧寿觞。"]},{"t":"静明园喜雨","f":"七言绝句","c":["西山初夏玉泉清，暮雨随风满凤城。","四野皆沾比屋庆，八荒尽望乐丰盈。"]},{"t":"密云作","f":"七言绝句","c":["连年驻跸此城隈，云谷无尘金碧堆。","斗室何妨宇宙志，晨昏常掖辇舆回。"]},{"t":"石匣营作","f":"七言绝句","c":["青岭横峰荫薜萝，时方小暑绿新荷。","蒲编诗兴光岩穴，虎士桓桓扣角歌。"]},{"t":"仿唐人戏作","f":"七言律诗","c":["一村耕作两村耕，两处缘来一处成。","下止丰亨上土旱，南山落雨北山晴。","河流数转河流去，任性无常任性行。","万物参差须格物，一生何苦太关情。"]},{"t":"读书得风云月露字因而分作四句中成绝一首","f":"七言绝句","c":["吟风欲识诗书髓，弄月须参天地心。","莫遣云尘绕八极，时时湛露沛高深。"]},{"t":"塞外新秋","f":"五言律诗","c":["松塞云峰转，边陲秋气长。","枫林消溽暑，柏叶送清香。","禾黍宜关外，情怀喜夜凉。","年丰还重谷，处处有馀粮。"]},{"t":"夜闻雷雨大作晓赋志喜","f":"七言律诗","c":["秋成望泽意悬悬，驻辇山庄已数天。","雷送溪声连夜雨，炉凝香霭润鸾笺。","开襟漏报残钟曙，破梦茶敲活火煎。","半百无文惟自乐，顿教心地作清涟。"]},{"t":"赋得芳气有无中","f":"五言律诗","c":["大儒吟咏物，正自托诗情。","气质原含内，芬芳远向荣。","藕花中外直，绛雪有无名。","惟愿菊兰气，山林勿使轻。"]},{"t":"早起看雪","f":"古风","c":["凛冽朔风舞雪，逶迤静夜高眠。","起听芸窗万籁，依然寻句韦编。"]},{"t":"咏盆中松竹梅各一首 其一 松","f":"五言绝句","c":["岁寒坚后雕，秀萼山林性。","移根黼座傍，可托青松柄。"]},{"t":"咏盆中松竹梅各一首 其二 竹","f":"五言绝句","c":["此君霜后青，密叶欲停雪。","丛篁傍小山，清节依然洁。"]},{"t":"静坐读书自喻","f":"五言古诗","c":["壮年好血气，半老少知闻。","顾諟惟当谨，铭盘不至宭。","励精勉图治，旰食尽民殷。","性理宗濂洛，临摹仿鹅群。","煌煌劳梦想，济济咏南薰。","悬钟是进德，止辇问停云。","怀保编氓苦，惠鲜鳏寡煴。","留心刑服念，鄙笑图书焚。","优礼任舟楫，凭轩尊典坟。","前星诫琢磨，帝子识群分。","外戚无矜势，诸王惜旧勋。","烽烟熄万里，瀚海畏三军。","淮黄关国计，漕运致忧勤。","土木毋轻动，民情宜所欣。","志广则宽裕，神清息俗纷。","由来恶旨酒，自喻喜玄纁。","长歌咏白雪，论赋小横汾。","几暇讲寥廓，提筹算紫氛。","乾阳得复转，测景考斜曛。","有始无终叹，为山一篑慬。"]},{"t":"咏雁","f":"五言绝句","c":["品清敛燕雀，高洁许宾鸿。","衡阳时有忆，留伴佐雄风。"]},{"t":"咏弹琴","f":"五言绝句","c":["流水高山志，清音本自虚。","朱弦准古调，和气近宸居。"]},{"t":"四十一年除夕书怀","f":"五言律诗","c":["平生宵旰志，七七又将过。","忘寝愁旸雨，精心勉泰和。","送寒辞故岁，待曙问民疴。","莫论新春媚，预怜五噫歌。"]},{"t":"赐云南法界寺讲经溥畹","f":"五言绝句","c":["昆明度法语，滇海论新禅。","万里虽云远，金经自有传。"]},{"t":"灯节戏作","f":"七言绝句","c":["隐隐光风度柳条，千寻银箭列丹霄。","龙衔火树开花看，欲见山青待雪消。"]},{"t":"三渡齐河即事","f":"五言律诗","c":["淑气霓旌绕，光风拂济川。","曾经三次渡，未若十年前。","疾苦劳宵旰，深恩赖保全。","颇知民食重，安抚责臣贤。"]},{"t":"趵突泉留题源清流洁四字","f":"七言绝句","c":["突兀泉声涌净波，东流远近浴羲和。","源清分派白云洁，不虑浮沙污水涡。"]},{"t":"夜登泰山","f":"五言绝句","c":["日斜登泰岱，岭腹隔层霄。","深夜回銮处，便忘石磴遥。"]},{"t":"新柳","f":"七言绝句","c":["畿内柳丝未出黄，江南柳色已成行。","郁金枝上啼莺早，积翠河边待夕阳。"]},{"t":"览淮黄成","f":"七言律诗","c":["殷勤久矣理淮黄，几度风尘授治方。","九曲素称天下险，四来实为兆民伤。","使清引浊须勤慎，分势开疏在不荒。","虽奏安澜宽旰食，诫前善后奠金汤。"]},{"t":"登金山望长江","f":"七言律诗","c":["烟云清处晓霞飞，万里滔滔映紫微。","灵液渺茫浮淑气，孤峰峍崒照晴晖。","花翻浪涌疑天色，风动帆张共德威。","昼夜如斯莫间歇，体乾勉已识璿玑。"]},{"t":"虎丘","f":"五言律诗","c":["秀壁名吴水，悬萝接紫霞。","仁风期大吏，厚俗止纷华。","停辇舆情问，开轩畎亩赊。","笙歌陈勿用，意使尽桑麻。"]},{"t":"过云栖憩竹林下令人斸笋斸兰","f":"七言律诗","c":["寻春二月幸云栖，满目天光入品题。","密林布荫樵渔乐，幽柏成行蕙芷齐。","浴手临泉开箨笋，傍岩倚石选蓬藜。","馀杭风景西湖胜，未若山中待竹迷。"]},{"t":"云栖归途遇雨","f":"七言绝句","c":["钱江风雨促前旌，竹树缤纷细草萌。","夹岸黎元瞻拜切，频施膏泽惬民情。"]},{"t":"钱塘江潮","f":"七言绝句","c":["相传冰岸雪崖势，滚滚掀翻拥怒涛。","风静不闻千里浪，三临越地识江皋。"]},{"t":"西湖夜月","f":"七言绝句","c":["月照清涟静不波，鸾箫象管夜来多。","轻舟岂羡江湖胜，欲写无私属棹歌。"]},{"t":"癸未春二月二十日自杭回至苏州是夜雨二十一日朕欲北行地方大小官员百姓留住二十二日雨甚冉留不能起行二十三日雨晴又欲留故书怀以示","f":"七言律诗","c":["踌躇星夜两河工，又至吴乡泊趠风。","春雨姑苏留豹尾，黎情江浙恋青骢。","翠华景从无云盖，遍覆时巡有折衷。","不意龙蟠虎踞胜，岂因景物杂谦冲。"]},{"t":"巡省江浙见闾阎有起色示诸臣省刑爱民","f":"七言律诗","c":["巡方不用驾楼船，白舫兰桡问市廛。","和气成春知岁稔，清风布物爱时妍。","齐民但示蒲鞭辱，报国应同竹节坚。","莫恃才名轻庶政，冥冥中自有青天。"]},{"t":"船泊无锡","f":"五言律诗","c":["扬帆百馀里，警跸惠山泉。","竹倚青松外，藤悬秀岭巅。","垂杨初匝幔，新藻写澄渊。","惟爱此清洁，开言点素笺。"]},{"t":"至江宁百姓欢迎遮道志喜","f":"七言绝句","c":["童叟欣迎步辇前，春风润雨万条烟。","若非念切军民久，争得欢声祝八千。"]},{"t":"行宫春雨作书竟日","f":"五言绝句","c":["离宫暂驻辇，竟日检牙签。","自愧书家奥，临池正笔传。"]},{"t":"江宁道上口号","f":"七言绝句","c":["白下回程傍竹林，平山水溜似鸣琴。","星驰不为阴晴阻，瓜步城南念旧吟。"]},{"t":"下长江舟中作","f":"五言律诗","c":["一鹭芦中起，双鸥沙上鸣。","翠烟含碧嶂，瑞霭覆琼英。","洲转牙樯乱，江流大块横。","智仁山水德，动静也移情。"]},{"t":"自江宁至京口","f":"七言律诗","c":["轻绡初霁引江干，隔岸芦洲映水寒。","吴会人文因气秀，金焦峦势起弘观。","往来客旅千重艗，上下波涛万里滩。","逝者绵绵无歇息，利名今古视艰难。"]},{"t":"登焦山","f":"七言绝句","c":["风帆战舰入沙洲，不动云烟一豫游。","只见晴光安水面，潮声静里卷潭湫。"]},{"t":"维扬雨霁","f":"七言绝句","c":["二十四桥夜雨收，蜀冈阜下水西流。","禅心欲定沾泥絮，不为繁华紫绮裘。"]},{"t":"见泰安等数州县饥民亟命设法赈济","f":"五言古诗","c":["东路行辇到，人食正荐饥。","呼庚儿女盼，宸游众所依。","村中皆菜色，散去掩柴扉。","救荒先发谷，转漕迅如飞。","两旬无多日，有司报民归。","地丁既已责，私派务全希。","尽力专邦本，留意欲国肥。","麦秋犹可望，黎命其庶几。"]},{"t":"东八闸舟遇顺风志喜","f":"七言绝句","c":["千里程途数日还，岸回转转抱清湾。","云帆不用荃桡力，喜志恩从大内颁。"]},{"t":"阅两河告成事毕因有恩诏星夜回京至天津书怀","f":"五言律诗","c":["阅河临南国，飞旆转金台。","不畏中宵困，岂因华祝催。","千秋明镜鉴，万寿鄙霞杯。","沐雨栉风紧，恩从涣汗开。"]},{"t":"赋得万物静观皆自得","f":"七言律诗","c":["布教皇风性理寻，右文惠化无私临。","清閒静省危微志，宴坐动观人道心。","天地浑元肃气象，乾坤阖辟识书林。","圣贤雅颂原无远，实在存神咏四箴。"]},{"t":"麦秋盈野志喜","f":"七言律诗","c":["去冬盈尺雪占年，今夏翛翛麦陇全。","万亩皆齐诞降谷，千家秀实已登阡。","先忧旸雨惟民疾，后乐时丰纪玉笺。","志喜雕虫晚学愧，薰风南至影花砖。"]},{"t":"将之山庄四首 其一","f":"五言绝句","c":["畏暑心何胜，平明出玉墀。","万几岂歇息，临政有畴咨。"]},{"t":"将之山庄四首 其二","f":"五言绝句","c":["暖溜自平地，风光此日佳。","暄波由近发，浩泽无津涯。"]},{"t":"将之山庄四首 其三","f":"五言绝句","c":["驻辇相风竿，临书羡五传。","情澜分暑节，疏爽须葵扇。"]},{"t":"将之山庄四首 其四","f":"五言绝句","c":["霖雨消尘迹，轻霞照野荆。","词臣每扈从，上赏赋昆明。"]},{"t":"赋得绿树阴浓夏日长","f":"七言律诗","c":["绿槐影荫碧纱厨，茂树纷纷叶渐殊。","绵雨新霖消九夏，薰风初热未三驱。","末垂蝉咽浓阴下，脩景云开炎暑无。","长日山中吟咏毕，气清塞外鄙凉珠。"]},{"t":"尖齐圆健笔之四德戏作四首 其一","f":"五言绝句","c":["尖锐虽云利，锋铓日计摧。","藏拙莫言巧，生花自有来。"]},{"t":"尖齐圆健笔之四德戏作四首 其二","f":"五言绝句","c":["齐之故有道，人一已千能。","默运良为手，挥毫须敬承。"]},{"t":"尖齐圆健笔之四德戏作四首 其三","f":"五言绝句","c":["圆活幽人本，珠玑三品详。","刚方学米芾，宛转仿其昌。"]},{"t":"尖齐圆健笔之四德戏作四首 其四","f":"五言绝句","c":["健乃乾行体，才分不息功。","书称钦若语，赓颂赖文风。"]},{"t":"古戍三绝 其一","f":"七言绝句","c":["隐隐山头皆古戍，中原民力尽边城。","曾闻父老经年战，回首生灵血泪盈。"]},{"t":"古戍三绝 其二","f":"七言绝句","c":["金瓯永固识人和，万里烽烟发兴多。","设使山林有暗晓，更须太息论如何。"]},{"t":"古戍三绝 其三","f":"七言绝句","c":["旧日山中罢马叹，今时避暑乐清风。","穷兵岂若为观德，仁义无私八表同。"]},{"t":"赋得雨洒石壁来","f":"七言绝句","c":["润叶随风洗绿枝，群峰著雨尽离披。","阴霖又念农家业，事事何烦先预知。"]},{"t":"塞外山庄","f":"五言律诗","c":["巀嶭连青嶂，悬崖挂绿溪。","鱼随渊静戏，鹤喜树高栖。","洞远行僧断，林寒过客迷。","惟予心旧好，逸兴少同跻。"]},{"t":"每时届炎暑即赴口外掖辇视膳朝夕温凊自初夏皇太后偶尔违和故不至此清凉之境因咏怀一首敬书于箑头恭进以接清风而舒远慕之微悃而已","f":"七言绝句","c":["遥想京中暑气阑，犹思上苑有冰纨。","山庄咫尺何曾远，欲进瑶池一笑看。"]},{"t":"避暑驻跸山庄六月间阴霖少晴自立秋日晴霁喜怀","f":"五言律诗","c":["亢旸望十雨，霪雨思晴天。","累日贯秋序，终朝潦水绵。","身虽无暑汗，心实抱迍邅。","忽睹西风紧，油云逐岭巅。"]},{"t":"山庄夜雨听滦河溜声","f":"七言律诗","c":["临流震耳似惊潮，滚滚泠泠眺绮寮。","夜色初分秋景霁，风声已送积霖飘。","皆因百壑归来远，非是孤川自去饶。","何比长江无弃物，小河水涸岂容桡。"]},{"t":"穹览寺偶成","f":"七言绝句","c":["塞北钟声久不闻，梵音列刹共氤氲。","雨花柏树同僧老，开世瞿昙永法云。"]},{"t":"兄裕亲王挽诗二律 其一","f":"五言律诗","c":["花萼空虚梦，悲歌暮景伤。","泪同秋雨湿，声逐碧天长。","清颂连香桂，心慈厌帝乡。","徽章纵有秩，寂寂叹时光。"]},{"t":"兄裕亲王挽诗二律 其二","f":"五言律诗","c":["少小同居处，义深读孝经。","赋诗明务本，携手问慈宁。","乐善从无息，神襟物外停。","繁忧题旧日，血泪染疏棂。"]},{"t":"过固关入山西境","f":"五言律诗","c":["鸟道入云中，风光塞漠同。","人依险地立，城自越山丛。","俗朴观民舍，才多壮士雄。","芹泉连冀北，回首指青骢。"]},{"t":"固关口号","f":"古风","c":["关固须凭人守，城高所赖兵防。","若非威德恩惠，恃险何曾世长。"]},{"t":"平定州","f":"七言绝句","c":["劳农岂惮元英节，寒景风沙透体来。","志有鹊山无觅处，目前常见冻云回。"]},{"t":"幸西省至太原","f":"五言律诗","c":["黎元瞻翠盖，三晋力桑麻。","纳稼知丰稔，祈年意静嘉。","边无戍卒苦，巷有读书家。","此幸非游玩，隆冬见玉花。"]},{"t":"渡黄河潼关驻跸","f":"五言律诗","c":["星源来晋甸，天险峙秦关。","波涌方舟速，威明古戍閒。","万民瞻凤辇，百职集鹓班。","冬省经兹地，移风先化顽。"]},{"t":"入陕西境","f":"五言律诗","c":["世远山河在，汉唐史有存。","风光移万户，景物换千门。","叹昔当殷鉴，筹今广湛恩。","从来秦陇地，莫使竞心繁。"]},{"t":"望华山","f":"七言绝句","c":["一月风霜尘土中，忽看翠盖拥三峰。","汉廷金掌今应笑，惟有华巅并古松。"]},{"t":"渭河见终南山","f":"五言古诗","c":["渭水自萦纡，秦川喜清旷。","山势何岧峣，经过绝尘坱。","马首见层峦，直插青霄上。","云际有飞泉，朝光明画嶂。","石险登临难，心寒不可量。","太乙本仙源，天都聊骋望。","岁岁松柏林，遐睇心神畅。","问俗戒征途，便欲慰幽访。"]},{"t":"冬至日抵西安遥祝皇太后万寿","f":"七言绝句","c":["葭管初回日景长，西秦行幸抵披香。","愿将唐句南山寿，遥捧蓬莱万里觞。"]},{"t":"长安行","f":"七言古诗","c":["河山天险古金汤，都邑规模溯汉唐。","陆海膏腴本沃壤，秦风剽悍称岩疆。","每因眷念劳中夜，忍使时巡后一方。","远幸冲寒访民隐，终南太华遥相望。","豳岐不乏耕织业，漆沮尚存蒐狩场。","重农藏富屡诏谕，雨旸时若歌丰穰。","雄兵超距贾馀勇，野老讴吟多宿粮。","要令遐陬沾湛露，讵以无事弛边防。","大阅三军训甲士，来朝诸部趋蕃王。","蠲租恤下恩未已，共跻仁寿乐且康。","渭水冰消回暖律，南山烟霭动初阳。","停銮怀古还披卷，宵旰勤求意不忘。"]},{"t":"西安偶作","f":"五言绝句","c":["八水源秦陇，山河辅帝京。","此方文武职，须教尽和平。"]},{"t":"回銮至华阴欲登华山因风雾所阻","f":"七言律诗","c":["踟蹰风雾阻莲峰，未识云台止水溶。","秦地山川聊一望，方舆畎亩尽三农。","兵民拥道心随仗，文武攀辕泪满容。","凉德何能衢壤乐，皆因岁久庆时雍。"]},{"t":"由豫省回銮渡孟津","f":"七言律诗","c":["遥望嵩峰欲逼天，太行绵亘洛阳川。","金明池畔无烽火，醉白堂前起玉烟。","千里中州古击壤，两河分界旧原田。","扁舟稳渡观民俗，休养心殷冀有年。"]},{"t":"赐超玉和尚","f":"七言绝句","c":["秦晋山河巡幸毕，回銮揽辔历新中。","忽闻梵语如风送，疑是江南话桂丛。"]},{"t":"元旦朝罢","f":"七言律诗","c":["四十三年瞬息间，罔知自惜鬓将斑。","晋秦丰裕群情悦，齐鲁调饥万姓艰。","经史保怀分善恶，古今吏治辨贤奸。","一生终始此心在，何卜新春乐解颜。"]},{"t":"甲申春谒陵回銮路经盘山有僧智朴呈接驾诗即用原韵二首 其一","f":"五言律诗","c":["廿载常轻步，年华去莫从。","古松分远近，老衲自舂容。","问及当时景，犹疑隔岭重。","山高劳脚力，来往遍云峰。"]},{"t":"甲申春谒陵回銮路经盘山有僧智朴呈接驾诗即用原韵二首 其二","f":"五言律诗","c":["铃铎鸣山下，田畴雨露恩。","经声连静舍，法语闭柴门。","隐迹安无意，清思礼世尊。","春风来拂面，依旧是乾坤。"]},{"t":"点绛唇 春雪晴望","f":"古风","c":["积素飘飖，和风欲度千门晓。","冷时尽了。","禁苑梅花绕。","妙舞莺声，歌咏清平调。","残腊杳。","青春偏矫。","日影寒松杪。"]},{"t":"康熙四十二年夏秋间恒雨为菑山左尤甚朕夙夜靡宁宵旰焦劳减膳撤乐坐不安席自冬至夏自夏至秋未尝晷刻少安虽设法拯救几乎难保幸四十三年二麦大熟秋成颇佳饥者未转沟壑穷者皆得衣食实非朕之凉德所感赖上天之所鉴祐也故喜而不寐作长歌以示","f":"七言古诗","c":["璇玑玉衡齐七政，祇惧敏德天眷命。","百志惟熙亮天功，六府三事须主敬。","天地无私本至公，人事有违失五正。","水旱从来不可测，全赖有司勉安定。","癸未夏秋恒雨频，二麦秋禾皆没沦。","州县无策万姓逃，父子流离呼苍旻。","奏疏纷纷连早夜，手书的的察忧贫。","蠲赋蠲赈诏数下，民食维艰岂不询。","截漕施惠恐不及，遣官分养诫沾均。","人力虽尽惟时难，唯天至仁不绝食。","甲申春夏风雨调，麦陇翛翛众喘息。","夏苗遍野双穗多，舆情颜解去菜色。","山左编氓閒且乐，畿南黎庶喜而康。","从此休息须谨慎，防灾备患岂有伤。","闲邪存诚勉官吏，清廉奉职守封疆。","民脂民膏供尔禄，痛痒莫知误筹量。","宗子家相同胞义，勿使丛脞述职方。"]},{"t":"山庄书怀赐大学士","f":"七言律诗","c":["待旦勤勤望雨晴，京南塞北察安氓。","已知云敛无霪潦，未卜田间有稻粳。","八月秋成欢宇内，四方风景解春卿。","大川舟楫同忧戚，更觉凝承信洛英。"]},{"t":"咏医","f":"五言绝句","c":["神圣岂能再，调方最近情。","存诚慎药性，仁术尽平生。"]},{"t":"静坐偶成","f":"七言绝句","c":["静中危坐忘机巧，无觉有空色相消。","浑似太玄非可道，利名终始定难摇。"]},{"t":"赋得霜叶红于二月花","f":"七言绝句","c":["塞鸿初度惊霜信，枫叶流丹树树红。","最喜山林清俗念，故应暂却世尘风。"]},{"t":"看运河建坝处","f":"七言律诗","c":["十月风霜幸潞河，隔林疏叶尽寒柯。","岸边土薄难容水，堤外沙沉易涨波。","春末浅夫忙用力，秋深霖雨失时禾。","往来踟躇临渊叹，何惜分流建坝多。"]},{"t":"题边景昭鸣禽图","f":"七言律诗","c":["青绿缤纷巧画工，鸣禽对对绕芳丛。","黄莺能语吟高树，白燕低飞喜惠风。","骚人纸上贪春昼，客旅村中知气融。","无意篷窗真伪辨，枝头犹带艳林红。"]},{"t":"翰林魏学诚该直命大学士陈廷敬出题考得四方无事太平年朕喜其句而偶成四韵","f":"七言律诗","c":["太平久远须忧虑，无怠无荒即乐天。","教化原从风俗起，观瞻祇系庙堂坚。","精心可畏先贤语，守法勿更大义全。","问道愚民何为愿，官清省事便丰年。"]},{"t":"立冬微雨雪偶成","f":"五言律诗","c":["朔风拂户牖，梅蕊报门阑。","颁历小春候，同云十日寒。","琼花连雨润，侍女怯衣单。","念彼穷檐苦，还思盘石安。"]},{"t":"冬月微雨闻落叶","f":"七言绝句","c":["寒条晰历被风催，霜叶纷纭杂雨来。","节届元英冬气暖，恐伤物性岂悠哉。"]},{"t":"灯月文房戏作","f":"七言绝句","c":["缸花冷月并争光，书幌牙签御墨香。","先识薛涛盈净洁，挥来毛颖赋琼章。"]},{"t":"园中十种葡萄味甚甘美戏作近体一律以示南书房诸臣","f":"五言律诗","c":["休誇大宛贵，莫讶汉宫传。","十种标名异，千条带叶鲜。","随班命内侍，分赐列忠贤。","饱食和心胃，归鞍赋木天。"]},{"t":"乏良医","f":"五言律诗","c":["长息上池水，偏疑寿世书。","七诊理不再，九候势全虚。","肱折知良术，身轻辨病除。","名医非取利，涤脏足心舒。"]},{"t":"冬晴","f":"七言律诗","c":["秋雨连绵道不通，冬晴少雪喜清宫。","阶前瑞草呈长至，盆内梅花报色红。","闭户点文烧蜡短，垂帘静思万缘空。","愿言一善犹心定，总览经书众虑同。"]},{"t":"题闽粤进贡小香荔枝","f":"七言绝句","c":["闽粤山川产绛囊，味参崖蜜色含香。","大官先散词林客，捧出瑶阶和玉浆。"]},{"t":"题墨竹","f":"七言绝句","c":["浓墨丛篁写意生，风枝欲动不闻声。","虚怀还待寒松友，记与瑶篇识重轻。"]},{"t":"咏灯","f":"七言绝句","c":["寒冬秉烛不成章，欲解先贤命意长。","经史预分知善恶，诗吟自辨性情良。"]},{"t":"赋得梅雪争春","f":"七言绝句","c":["梅花十里香犹在，雪白千山岭益明。","盈尺预知秋麦壮，争春岂不让生生。"]},{"t":"风入松 腊日","f":"古风","c":["冲寒待腊雪花飘。","词意并琴挑。","嘉平岁暮春光近，朔风冽、裘暖狐貂。","须晓民间衣薄，那知宫里宽饶。","隆冬气惨绛香烧。","披览共仙韶。","毡帘软幕凉还透，微云一抹散琼瑶。","听得梅将开也，先看绿萼清标。"]},{"t":"季冬南苑十首 其一","f":"五言绝句","c":["銮舆出禁门，前队已临苑。","威德如风行，感恩似草偃。"]},{"t":"季冬南苑十首 其二","f":"五言绝句","c":["麦丛还待雪，苑静那看风。","平野无尘迹，寒条远近同。"]},{"t":"季冬南苑十首 其三","f":"五言绝句","c":["讲武不忘威，劳农亦预知。","回看止辇处，尽是岁寒枝。"]},{"t":"季冬南苑十首 其四","f":"五言绝句","c":["武职皆熊貔，没羽穿杨力。","所向任干城，挽强视道德。"]},{"t":"季冬南苑十首 其五","f":"五言绝句","c":["三驱一面网，雉兔正堪肥。","弦响无虚落，日暮即收围。"]},{"t":"季冬南苑十首 其六","f":"五言绝句","c":["骥德鄙千里，飞黄汗血传。","临风嘶远路，蹋雪意贞坚。"]},{"t":"季冬南苑十首 其七","f":"古风","c":["赤精长耳速，撮兽?麋鹿。","迅捷欺飞腾，恋主犬为独。"]},{"t":"季冬南苑十首 其八","f":"五言绝句","c":["雄飞耻燕雀，受緤志凌云。","阔臆惊禽鸟，鹰扬冠不群。"]},{"t":"季冬南苑十首 其九","f":"五言绝句","c":["罢猎归鞍早，乐施命大官。","分餐不畏冷，祇恐夜间寒。"]},{"t":"季冬南苑十首 其十","f":"五言绝句","c":["离宫乙夜静，堪将岁月除。","悬灯览奏摺，终始复如初。"]},{"t":"南苑晚雪","f":"五言律诗","c":["七月伤多雨，三冬少问天。","晴开逾至日，云作近新年。","猎雪宜岐麦，银花润早田。","心劳催短鬓，忧乐验谁先。"]},{"t":"总兵刘汉业补授肃州因地远职重特书御制诗截句一首赐之以奖武职惜兵爱民之意也","f":"七言绝句","c":["此去阳关路八千，总戎远镇碛沙边。","欲知营伍精兵法，遐迩怀柔似御前。"]},{"t":"除夕晚宴","f":"七言律诗","c":["辞旧迎新岁事终，未知来日与今同。","平生恶酒难堪饮，一世劳心不计功。","满座儿孙教乐善，数班鹓鹭劝和衷。","此宵家宴逢除夕，须遣纷纭静守中。"]},{"t":"康熙四十四年元旦用唐太宗元日旧韵","f":"五言古诗","c":["午夜占天象，平明忆岁光。","旌旗旋转动，钟鼓奏玎珰。","临下开诚信，守身勿自荒。","履端出宝历，正始勉岩廊。","圣道原无远，仁慈渐得昌。","位高仰五帝，责重仿三王。","惜物由心俭，去华莫喜妆。","常怀兢惕诫，遐迩愿梯航。"]},{"t":"赋得光风遍寰宇","f":"七言律诗","c":["佳气先春丽景殊，光风遍拂到寰区。","新年二日逢斋戒，去腊三朝读典谟。","立志铭心闽洛理，虚怀注念鬼神孚。","岂知人意皆从善，爱此元元是巩图。"]},{"t":"览皇清文颖内大学士陈廷敬作各体诗清雅醇厚非集字累句之初学所能窥也故作五言近体一律以表风度","f":"五言律诗","c":["横经召视草，记事翼鸿毛。","礼义传家训，清新授紫毫。","房姚比就韵，李杜并诗豪。","何似升平相，开怀宫锦袍。"]},{"t":"赋得当户翠峰稠","f":"五言律诗","c":["杳冥巉岩石，苍茫远近山。","案书无俗韵，侍女有云鬟。","静省参三教，动沦闭四关。","閒来偶独咏，自笑为开颜。"]},{"t":"阅河南巡出京","f":"五言古诗","c":["五幸畿南域，鸣銮出帝京。","数巡乏镜海，减从省春耕。","人望返风吏，官箴留犊名。","治民属大法，分阃欲冰清。","豫动怀柔典，观瞻感慨情。","东皋迎淑气，绮陌拥霓旌。","冻解流澌远，寒迟惜岁更。","岸容新柳报，堤候早梅惊。","日月几何改，神思逐物萦。","停车咨实政，载路喜和平。","绿鬓将成白，衰颜义自明。","精微执一旨，守久道心生。"]},{"t":"柳梢青 乙酉仲春南巡船窗偶作","f":"古风","c":["大块光风。","春畴一望，满目从容。","桂棹初摇，牙樯始立，淑色烟笼。","堤边对对宾鸿。","村庄里、安平气融。","乐志情深，读书意远，与古和同。"]},{"t":"船窗对月小饮","f":"七言律诗","c":["皎洁胧胧向晚明，鲜云细雨过帆轻。","上樽空设原非饮，梅赋无花句亦成。","媚景依然铺锦甸，晴光更与助桃笙。","隔溪酒市迎流近，转岸遥闻笑语声。"]},{"t":"拟田家春日","f":"七言绝句","c":["芳晨麦陇布风和，片片如云万亩坡。","忽睹远村垂柳处，喧声颇觉住人多。"]},{"t":"过临清闸","f":"五言律诗","c":["岸转蒲帆速，樯回树影低。","波倾闸势险，溜紧浪声齐。","连岁歌云汉，今春释惨悽。","往还为赤子，注意在黔黎。"]},{"t":"南巡舟行会通河杂咏四首 其一","f":"五言绝句","c":["风劲寒犹在，低篷抵博平。","麦畦青遍野，方意近清明。"]},{"t":"南巡舟行会通河杂咏四首 其二","f":"五言绝句","c":["三载齐民饥，多方济一喘。","后先益在兹，晷刻心难遣。"]},{"t":"南巡舟行会通河杂咏四首 其三","f":"五言绝句","c":["迟日云烟静，芳春膏泽多。","时旸时雨望，祝稔并祥禾。"]},{"t":"南巡舟行会通河杂咏四首 其四","f":"五言绝句","c":["案读临清流，澄怀夕景悠。","敕几逢事少，吟咏敢忘忧。"]},{"t":"河南巡抚赵宏燮陛见求训旨故作截句一首赐之","f":"七言绝句","c":["宣布抚安在已廉，刚柔率属要温谦。","中州民俗多忠厚，务使和平莫太严。"]},{"t":"乙酉南巡途间观麦少雨上巳日抵微山湖口闸春雨大霈因赋五言近体一首以志喜","f":"五言律诗","c":["农事遍东皋，心閒不自劳。","闸添济运水，风送逐渔篙。","雨罩湖光隐，春深日影高。","遥观两岸麦，乐志赋轻舠。"]},{"t":"杨家庄新开中河得顺风观民居漫咏二首 其一","f":"七言绝句","c":["瞬息风帆百里馀，往来数次过淮徐。","光阴犹似当年景，自觉频催点鬓疏。"]},{"t":"杨家庄新开中河得顺风观民居漫咏二首 其二","f":"七言绝句","c":["春雨初开弄柳丝，渔舟唱晚寸阴移。","庙堂时注淮黄事，今日安澜天下知。"]},{"t":"驻跸淮安一宿即过","f":"七言律诗","c":["鹅黄垂柳迓清明，野望湖边远碧横。","古渡烟波春色好，新堤静溜水心平。","杏花才吐梅先尽，鸲鹆偏言莺未鸣。","迅速行舟惟一目，何关有意与无情。"]},{"t":"幸天宁寺","f":"五言律诗","c":["空濛为洗竹，风过惜残梅。","鸟语当阶树，云行动早雷。","晨钟接豹尾，僧舍踏芳埃。","更觉清心赏，尘襟笑口开。"]},{"t":"朕每至南方览景物雅趣川泽秀丽者靡不赏玩移时也虽身居九五乐佳山水之情与众何异但不至旷日迟久有累居民耳所以一目即过者亦恐后人错借口实而不知所以然也至于茱萸湾之行宫乃系盐商百姓感恩之诚而建起虽不与地方官吏但工价不下数千尝览汉书文帝惜露台百金后世称之况为三宿所费十倍于此乎故作述怀近体一首以自警又粘之壁间以示维扬之众","f":"七言律诗","c":["又驻塔湾见物华，先存蔀屋重桑麻。","惠风遍拂维扬市，沛泽均沾吴越家。","作鉴道君开艮岳，长嘘炀帝溺琼花。","浇胸经史安邦用，莫遣争能纵欲奢。"]},{"t":"览奏章少倦甲夜得寝又被清磬惊醒复睡梦中作成起时已忘少半故前后增补以成四韵赐纪荫老和尚迩来未临法书久不作字手涩难于运管字不甚佳","f":"七言律诗","c":["春梦深沉新刹中，陡闻清磬在邻东。","方疑般若真非相，不解金经尽是空。","鼻竖眉横无著落，胸宽意阔有尘笼。","毫光咫尺临高眺，满目江干淑景融。"]},{"t":"长江静浪歌","f":"七言古诗","c":["传来江势最凶险，万里长流湍潋滟。","葱岭分派自岷山，江汉黑水界蜀陕。","逶迤东注百川归，萦带如驶经诸矶。","风波云雾全眇眇，群峰屹立暝烟微。","铁锁横江原气怯，投鞭断流借盖威。","未若自然顺天意，无怠无荒广川济。","利涉须凭正刚柔，分理全赖作舟枻。","仁者如斯称水德，治人御事先光霁。","最喜长江能容物，更羡长江有宽厉。","每度无险浪且平，登临慷慨古今情。","未卜始终概难信，愿言永静勿纷更。"]},{"t":"自过江至常州府杂咏四首 其一","f":"五言绝句","c":["风平杨子渡，举棹过长江。","暮色林低水，晴光月照窗。"]},{"t":"自过江至常州府杂咏四首 其二","f":"五言绝句","c":["爱竹为长绿，南方已满林。","乔松分路侧，并作映江浔。"]},{"t":"自过江至常州府杂咏四首 其三","f":"五言绝句","c":["夜过丹阳道，红尘不染帆。","氤氲存五内，浩气托经函。"]},{"t":"自过江至常州府杂咏四首 其四","f":"五言绝句","c":["延陵曙色阑，意与渚田宽。","人尽农桑力，文风表里观。"]},{"t":"至阊门","f":"七言绝句","c":["明丽山川列象辉，光风轻艗带烟霏。","云随御仗分河畔，雨洗微尘花点衣。"]},{"t":"虎丘一咏","f":"七言绝句","c":["三天风雨百花催，独赏幽兰倚槛栽。","俯瞰田间浮麦浪，舆情足食即春台。"]},{"t":"自苏州行至昏刻未到昆山河傍有竹林数亩晚风可佳故驻跸于此赋得劲节疏枝带晚风之句","f":"七言律诗","c":["无意虚中得劲节，非关强作有疏枝。","晚风不待春将老，寸晷岂容年少时。","落照昆山掩玉色，远分秦望感人思。","初来更觉渔家乐，援笔题笺叹暮诗。"]},{"t":"雨中登玉峰","f":"七言绝句","c":["万井人烟春雨浓，菜花麦秀滋丰茸。","登高欲识江湖性，染翰留题文笔峰。"]},{"t":"船泊三江口","f":"五言律诗","c":["满眼湖山丽，九峰负海隅。","沃野吴淞境，横云馆驿衢。","观风来泽国，非是喜灵区。","雨过泊舟处，星连映水珠。"]},{"t":"汎黄浦江","f":"七言绝句","c":["飞渡浦江意自如，午潮往返到阶除。","欲知震泽分流处，非是观渔触浪馀。"]},{"t":"松江进鲜鲥鱼有怀","f":"七言绝句","c":["古有盛鱼奉老亲，锦鳞初得尚方珍。","虽然星夜传驰驿，岂似鲜新出水滨。"]},{"t":"驻跸杭州府","f":"五言律诗","c":["越境湖山秀，文风天地成。","南临控禹穴，西枕俯蓬瀛。","容与双峰近，徘徊数句盈。","民心多爱戴，少慰始终情。"]},{"t":"西湖遇雨","f":"七言绝句","c":["雨洗催花叶满林，柴门晓色静沉沉。","微飘柳絮春光晚，轻縠徐波见水心。"]},{"t":"西湖戏作","f":"五言律诗","c":["晴雨分山色，临流启壮观。","楼台横水面，梵塔插云端。","忽讶松间竹，当誇岩下兰。","风光被草木，无处不成欢。"]},{"t":"幸云栖二首 其一","f":"七言绝句","c":["鸟道沿江问信潮，石头恬静有归桡。","转移至险看洄洑，尽得人防莫失调。"]},{"t":"幸云栖二首 其二","f":"七言绝句","c":["竹径因依长绿苔，桑田菜麦碧岩隈。","此来也为佳山水，又恐迟行畏景催。"]},{"t":"无锡惠山之作","f":"七言绝句","c":["花尽春残一径深，清流长惹百年心。","溪边鸟语锡山麓，坐对梧楸叹碧林。"]},{"t":"回舟至常州府是夜甘霖大霈","f":"七言律诗","c":["夏浅云高惜阪田，江南比岁赖丰年。","麦秋遍野堪收穫，灵雨愆期倍惕乾。","夜半篷窗闻浙沥，晓来练浦听潺湲。","此行往返无他事，益见民情远近虔。"]},{"t":"临江仙 自镇江之江宁","f":"古风","c":["一路江边烟景，千般莺晓园林。","夕阳小屋暂容身。","松风清习气，麦浪得甘霖。","夹岸渔歌唱晚，临流按谱行吟。","肩舆遥指石榴阴。","怡情援笔录，危坐待知音。"]},{"t":"驻跸江宁雨后幸雨花台","f":"五言律诗","c":["膏澍一夜雨，初晓喜晴辉。","警跸长千里，鸣銮不阖扉。","人勤并物盛，官守莫心违。","出京迟日久，怯暑便思归。"]},{"t":"织造处阅机房","f":"七言绝句","c":["终岁勤劳匹练成，千丝一剪截纵横。","此观不为云章巧，欲俭骄奢赌未萌。"]},{"t":"自龙潭用战舰顷刻至金山","f":"七言绝句","c":["来往无涛如皎镜，江干极目远峰连。","昔时血战君山侧，今日平成万里天。"]},{"t":"见龙行","f":"七言古诗","c":["在田在天连二五，纯阳变化参吞吐。","非如起蛟坏田庐，又非密雾伤园圃。","云端前后发祥光，逶迤上下行有矩。","而乘六龙以御天，不违施德普时雨。","有亢有悔有亏盈，首出庶物用精明。","大哉龙德从其类，发挥纯粹须经营。","长江一派何泱漭，素波万里尽澄泓。","象震凌云敦元气，日新顾諟玩无声。"]},{"t":"高旻寺塔顶放光","f":"五言律诗","c":["塔顶丹霄近，光函宜日中。","成平愿地久，熙皞似山崇。","不识昙云法，先知寰海同。","回舟何怪速，心急盻潮风。"]},{"t":"回銮中河三首 其一","f":"五言绝句","c":["风雨中河阻，心旌北望遥。","归舟吴越远，不必忆溪桥。"]},{"t":"回銮中河三首 其二","f":"五言绝句","c":["江南苦雨多，冀北少灵雨。","此念未尝忘，此心鉴万古。"]},{"t":"回銮中河三首 其三","f":"五言绝句","c":["锦䌫牵舟远，蒲帆逐浪深。","回看旧跸处，不竞自澄心。"]},{"t":"乙酉秋日山庄偶成","f":"七言绝句","c":["山花野菊喜清风，塞北烟光报岭枫。","无暑不知秋气至，数丛兰蕊放离宫。"]},{"t":"一路清廉图","f":"七言绝句","c":["青莲挺挺不污泥，岂被重波乱性迷。","虽有羡鱼心尚在，清风由是见崇题。"]},{"t":"赐吏部尚书宋荦予告还里","f":"五言律诗","c":["久任封疆事，苏台净点尘。","东曹班次重，北阙性情真。","怜旧吟风度，无文饯老臣。","林泉益壮志，当乐故乡春。"]},{"t":"大病少愈见春至述怀","f":"七言律诗","c":["神衰意绝见新春，忽报春风送紫晨。","淑气虽催首正节，病躯不改定中身。","心伤亿兆惜皇极，血尽黎元愧圣真。","此后如先意未卜，红尘碌碌阜人民。"]},{"t":"春日有所思二首 其一","f":"七言绝句","c":["淡抹浓妆总是新，白须慵懒度三春。","若非碌碌红尘縳，近得清心养谷神。"]},{"t":"春日有所思二首 其二","f":"七言绝句","c":["叠叠愁肠无日舒，春风细雨绿芳初。","诗中乏兴疑新句，自问何伤露地居。"]},{"t":"五台有怀","f":"五言律诗","c":["又到清凉境，巉岩卷复垂。","劳心愧自省，瘦骨夕鸣悲。","膏雨随春令，寒霜惜大时。","文殊色相在，惟愿鬼神知。"]},{"t":"大学士张玉书挽诗","f":"七言律诗","c":["文章末齿秉丝纶，旧德凝承近紫宸。","瀚海天山同正略，江干河道与尝新。","表贤未及身先没，颐养空谈梦后湮。","挥泪长歔叹佐斗，从来伤痛肃雍臣。"]},{"t":"孟秋凉风初至","f":"五言律诗","c":["白发详词切，劳心至语烦。","蝉鸣催木叶，月映冷泉源。","云去天疑近，露凝草益繁。","山村题旧事，唯德遍黎元。"]},{"t":"赋得秋水共长天一色","f":"七言绝句","c":["江渚长天一目收，滕王风送引扁舟。","当年未识文章巧，唐世诗词并水流。"]},{"t":"新秋","f":"五言绝句","c":["虫声咽晚凉，云敛天涯外。","何处寻高山，知音在一会。"]},{"t":"热河三十六景诗 其一 烟波致爽","f":"五言古诗","c":["山庄频避暑，静默少喧哗。","北控远烟息，南临近壑嘉。","春归鱼出浪，秋敛雁横沙。","触目皆仙草，迎窗遍药花。","炎风昼致爽，绵雨夜方赊。","土厚登双谷，泉甘剖翠瓜。","古人戍武备，今卒断鸣笳。","生理农商事，聚民至万家。"]},{"t":"热河三十六景诗 其二 芝径云堤","f":"古风","c":["万几少暇出丹阙，乐水乐山好难歇。","避暑漠北土脉肥，访问村老寻石碣。","众云蒙古牧马场，并乏人家无枯骨。","草木茂，绝蚊蝎，泉水佳，人少疾。","因而乘骑阅河隈，湾湾曲曲满林樾。","测量荒野阅水平，庄田勿动树勿发。","自然天成地就势，不待人力假虚设。","君不见磬锤峰，独峙山麓立其东。","又不见万壑松，偃盖重林造化同。","煦妪光临承露照，青葱色转频岁丰。","游豫常思伤民力，又恐偏劳土木工。","命匠先开芝径堤，随山依水揉辐齐。","司农莫动帑金费，宁拙舍巧洽群黎。","边垣利刃岂可恃，荒淫无道有青史。","知警知戒勉在兹，方能示众抚遐迩。","虽无峻宇有云楼，登临不解几重愁。","连岩绝涧四时景，怜我晚年宵旰忧。","若使扶养留精力，同心治理再精求。","气和重农紫宸志，烽火不烟亿万秋。"]},{"t":"热河三十六景诗 其三 无暑清凉","f":"七言律诗","c":["畏景先愁永昼长，晚年好静益徬徨。","三庚退暑清风至，九夏迎凉称物芳。","意惜始终宵旰志，踟蹰自问济时方。","谷神不守还崇政，暂养回心山水庄。"]},{"t":"热河三十六景诗 其四 延薰山馆","f":"七言绝句","c":["夏木阴阴盖溽暑，炎风款款守峰衔。","山中无物能解愠，独有清凉免脱衫。"]},{"t":"热河三十六景诗 其五 水芳岩秀","f":"五言古诗","c":["水性杂苦甜，水芳即体厚。","名泉亦多览，未若此为首。","颐卦明口实，得正自养寿。","择地立偃房，根基度长久。","节宣在兹求，勤俭勿落后。","朝窗千岩里，峭壁似天剖。","远托思云汉，怡神至星斗。","精研书家奥，临池愈涩手。","清淡作饮馔，偏心恶旨酒。","读老无逸篇，年年祝大有。"]},{"t":"热河三十六景诗 其六 万壑松风","f":"七言绝句","c":["偃盖龙鳞万壑青，逶迤芳甸杂云汀。","白华朱萼勉人事，爱敬南陔乐正经。"]},{"t":"热河三十六景诗 其七 松鹤清越","f":"五言绝句","c":["寿比青松愿，千龄叶不彫。","铜龙鹤发健，喜动四时调。"]},{"t":"热河三十六景诗 其八 云山胜地","f":"七言绝句","c":["万顷园林达远阡，湖光山色入诗笺。","披云见水平清理，未识无愆守节宣。"]},{"t":"热河三十六景诗 其十 北枕双峰","f":"七言绝句","c":["嵚㟢冈岫紫宸关，乾地金峰坎黑山。","苦热云生双岭腹，盆倾瞬息落溪湾。"]},{"t":"热河三十六景诗 其十一 西岭晨霞","f":"七言绝句","c":["雨歇更阑斗柄东，成霞聚散四方风。","时光岂在凌云句，寡过清谈宜守中。"]},{"t":"热河三十六景诗 其十二 锤峰落照","f":"七言绝句","c":["纵目湖山千载留，白云枕涧报深秋。","巉岩自有争佳处，未若此峰景最幽。"]},{"t":"热河三十六景诗 其十三 南山积雪","f":"七言绝句","c":["图画难成丘壑容，浓妆淡抹耐寒松。","水心山骨依然在，不改冰霜积雪冬。"]},{"t":"热河三十六景诗 其十四 梨花伴月","f":"五言律诗","c":["云窗倚石壁，月宇伴梨花。","四季风光丽，千岩土气嘉。","瑩情如白日，托志结丹霞。","夜静无人语，朝来对客誇。"]},{"t":"热河三十六景诗 其十五 曲水荷香","f":"七言绝句","c":["荷气参差远益清，兰亭曲水亦虚名。","八珍旨酒前贤戒，空设流觞金玉羹。"]},{"t":"热河三十六景诗 其十六 风泉清听","f":"七言绝句","c":["瑶池芝殿老莱心，涌出新泉万籁吟。","芳槛倚栏蒸灵液，南山近指奏清音。"]},{"t":"热河三十六景诗 其十七 濠濮间想","f":"五言绝句","c":["茂林临止水，间想托身安。","飞跃禽鱼静，神情欲状难。"]},{"t":"热河三十六景诗 其十八 天宇咸畅","f":"古风","c":["通阁断霞应卜居。","人烟不到丽晴虚。","云叶淡巧万峰明，雁过初。","宾鸿侣。","鸥雨秋花遍洲屿。"]},{"t":"热河三十六景诗 其十九 暖溜暄波","f":"七言绝句","c":["水源暖溜辄蠲疴，涌出阴阳涤荡多。","怀保分流无近远，穷檐尽诵自然歌。"]},{"t":"热河三十六景诗 其二十 泉源石壁","f":"五言律诗","c":["水源依石壁，杂踏至河隈。","清镜分霄汉，层波溅碧苔。","日长定九数，发白考三才。","天贶名犹鄙，居心思道该。"]},{"t":"热河三十六景诗 其二十一 青枫绿屿","f":"五言律诗","c":["石磴高盘处，青枫引物华。","闻声知树密，见景绝纷哗。","绿屿临窗牖，晴云趁绮霞。","忘言清静意，频望群生嘉。"]},{"t":"热河三十六景诗 其二十二 莺啭乔木","f":"古风","c":["昨日闻莺鸣柳树，今朝阅马至崇杠。","朱英紫脱平原绿，月驷云?错落駹。"]},{"t":"热河三十六景诗 其二十三 香远益清","f":"古风","c":["出水涟漪。","香清益远，不染偏奇。","沙漠龙堆，青湖芳草，疑是谁知。","移根各地参差。","归何处、那分公私。","楼起千层，荷占数顷，炎景相宜。"]},{"t":"热河三十六景诗 其二十四 金莲映日","f":"五言绝句","c":["正色山川秀，金莲出五台。","塞北无梅竹，炎天映日开。"]},{"t":"热河三十六景诗 其二十五 远近泉声","f":"五言绝句","c":["引泉开瀑布，迸水起飞珠。","锵玉云岩应，色空有若无。"]},{"t":"热河三十六景诗 其二十六 云帆月舫","f":"五言律诗","c":["阁影凌波不，动涛接灵鳌。","蓬莱别殿挂，云霄粲挥毫。","四季风光总，无竭卧闻箫。","后乐先忧薰，弦意蕴羲爻。"]},{"t":"热河三十六景诗 其二十七 芳渚临流","f":"七言绝句","c":["堤柳汀沙翡翠茵，清溪芳渚跃凡鳞。","数丛夹岸山花放，独坐临流惜谷神。"]},{"t":"热河三十六景诗 其二十八 云容水态","f":"古风","c":["雨过云容易散，波流水态长存。","悠然世俗惟念，必得经书考原。"]},{"t":"热河三十六景诗 其二十九 澄泉绕石","f":"五言律诗","c":["每存高静意，至此结衡茅。","树密开行路，山长疑近郊。","水泉绕旧石，雉雀乐新巢。","晴夜荷珠滴，露凝众木梢。"]},{"t":"热河三十六景诗 其三十 澄波叠翠","f":"五言绝句","c":["叠翠耸千仞，澄波属紫文。","鉴开倒影列，反照共氤氲。"]},{"t":"热河三十六景诗 其三十一 石矶观鱼","f":"七言绝句","c":["唱晚渔歌傍石矶，空中任鸟带云飞。","羡鱼结网何须计，备有长竿坠钓肥。"]},{"t":"热河三十六景诗 其三十二 镜水云岑","f":"古风","c":["层崖千尺危嶂，涵绿几重碧潭。","狮径盘旋道北，松枝宛转山南。","沉吟力尽难得，悬象俯察仰参。","至理莫求别伎，经书自有包函。"]},{"t":"热河三十六景诗 其三十三 双湖夹镜","f":"七言绝句","c":["连山隔水百泉齐，夹镜平流花雨堤。","非是天然石岸起，何能人力作雕题。"]},{"t":"热河三十六景诗 其三十四 长虹饮练","f":"七言绝句","c":["长虹清径罗层崖，岸柳溪声月照阶。","淑景千林晴日出，禽鸣处处入音谐。"]},{"t":"热河三十六景诗 其三十五 甫田丛樾","f":"五言绝句","c":["留憩田间乐，旷观恤闾阎。","丛林欣赏处，遍地豫丰占。"]},{"t":"热河三十六景诗 其三十六 水流云在","f":"五言绝句","c":["雨后云峰澄，水流远自凝。","岸花催短鬓，高年寸寸增。"]},{"t":"岁除前二日立春","f":"七言绝句","c":["岁尽星回朔气消，迎新慵听奏笙箫。","梅花欲报春先到，犹怯凝寒瑞雪飘。"]},{"t":"嘉平月初雪后晚坐偶有所见书怀","f":"七言律诗","c":["尺雪同云晴亦佳，心参运水及搬柴。","群乌将宿频迁树，半壁馀光反照阶。","慷慨行年周甲子，徘徊抚景对宫槐。","岂辞栉沐编氓志，疾苦先知天下怀。"]},{"t":"咏鸟鎗","f":"七言古诗","c":["由来火具三皇始，后世方兴欲广威。","未尽响声先雁落，已腾烟处带禽归。","海洋扫却鲸鱼浪，漠北清尘解铁衣。"]},{"t":"朕亲统六师至宁夏驻跸二十日遍观地势游览山形城之东南有巽湖水最清偶尔得野鸭一只羽毛滋润黄头紫背胸白翅短与他处所有回然不同业已忘矣今经十五载忽于画中又见此禽因而有感故援笔以记","f":"七言律诗","c":["七边曾历贺兰山，塞北咽喉最险关。","叠翠崖峦人迹灭，堆沙道路柏林攀。","汉渠遥转唐渠会，浊水先流清水湾。","野鸟閒栖犹得静，吾今自睹二毛斑。"]},{"t":"咏自鸣钟","f":"五言律诗","c":["法自西洋始，巧心授受知。","轮行随刻转，表指按分移。","绛帻休催晓，金钟预报时。","清晨勤政务，数问奏章迟。"]},{"t":"赋得禁城春色晓苍苍","f":"七言律诗","c":["淑色曈昽射早光，御园梅柳怯寒霜。","三宫紫气通瑶殿，九陌和风到建章。","春社先农开布种，初辛祈谷望书祥。","莺声燕语添诗思，欲去浮文夙夜忙。"]},{"t":"赵北口水淀作","f":"五言律诗","c":["风微见水绿，日暖弄窗妍。","树老依根壮，心平任物迁。","维舟临草岸，挥翰借壶天。","非是禽鱼乐，人稠万户烟。"]},{"t":"赋得时人不识予心乐","f":"七言律诗","c":["恩波遍布首邦畿，爱此佳时绿尚微。","血耗养衰心益壮，神烦物扰体无违。","暮年筋骨犹能强，半世忧劳幸免非。","老惯豫游山水处，傍人那得识天机。"]},{"t":"樯灯","f":"七言律诗","c":["泊舟浅水意如何，为惜春光怡兴多。","倚槛晚晴吟皓月，推窗夜静悦清波。","冰消浪㓗鱼吹沫，风转云开雁踏莎。","更有樯灯分掩映，辉煌岂亚扣船歌。"]},{"t":"点绛唇 樯灯","f":"古风","c":["夜静更深，船窗临淀见波影。","出看何景。","灯映牙樯炯。","自笑无文，难得佳词整。","挥毛颖。","水平天永。","淡露春风冷。"]},{"t":"阅河长歌","f":"七言古诗","c":["春风春社艳阳天，雪尽尘清遍路阡。","曾记当时泊舟处，今成沃土及膏田。","十年之前汎黄水，民生困苦少人烟。","历历实情亲目睹，老转少徙益难抚。","挟男抱女至马前，皆云此河不可堵。","桑乾马邑虽发源，山中诸流数难数。","吾想畿内不能防，何况远虑治淮黄。","数巡高下南北岸，方知浑流为民伤。","春末无水沙自涨，雨多散漫遍汪洋。","若非动众劳人力，黎庶无田渐乏食。","庙谟不惜费帑金，救民每岁受饥溺。","开河端在辨高低，堤岸远近有准则。","未终二年永定成，泥沙黄溜直南倾。","万姓方苏愁心解，从此乡村祝太平。","昔日宵旰尝萦虑，将来善后勿纷更。"]},{"t":"忆咏苏州风俗","f":"五言律诗","c":["邓尉梅梢月，虎邱浪里峰。","人争天地秀，物杂理文宗。","俗尚非交让，官箴乏恊恭。","舆情常若此，何日奏时雍。"]},{"t":"偶观演剧作","f":"五言律诗","c":["雅颂不能传，诗词降作调。","唐人歌舞精，元曲选声妙。","若曰得仙音，究未探其要。","暂为遣见闻，寄此发长啸。"]},{"t":"三月初十日恭请皇太后雅玩斋进膳看梅花","f":"五言古诗","c":["当年梅雪伴，今岁暮春迟。","银杏舒新叶，木兰盖绿枝。","花当亭畔发，香逐雨中移。","别殿陈鲜蜜，尚方献瑞芝。","老莱舞膝下，珠草列仙墀。","敬上乔松祝，欣瞻王母仪。","捧觞称寿句，进酒问安词。","地润铺红萼，波澄敛玉池。","高峰多爽气，绮树得丰姿。","漏转催辰半，表行近画奇。","承欢同永日，孝思莫违时。","会庆思经义，千秋古训垂。"]},{"t":"畅春园西新园观花","f":"五言律诗","c":["春光尽季月，花信露群芳。","细草沿阶绿，奇葩扑户香。","寸阴惜鬓短，尺影逐时长。","心向诗书奥，精研莫可荒。"]},{"t":"西苑试士","f":"五言律诗","c":["霁日东风暖，平川宇宙宽。","文章随世转，经史得人安。","讲学前贤奥，观光后进欢。","有生宵旰虑，独望和羹难。"]},{"t":"大学士陈廷敬挽诗","f":"五言律诗","c":["世传诗赋重，名在独遗荣。","去岁伤元辅，连年痛钜卿。","朝恩葵志励，国典玉衡平。","儒雅空兴叹，含毫感倍生。"]},{"t":"汤泉应候","f":"七言律诗","c":["一为消疾驻灵泉，步辇平明观插田。","喜见蕣华方遍野，更看修竹远笼烟。","虽无玩赏因偕乐，屡庆丰登共息肩。","窗外雨声滴草舍，密林莺语亦欣然。"]},{"t":"将军潘育龙久任封疆故存问赐诗","f":"七言律诗","c":["少年勇战启元戎，久任三秦铁石衷。","守土防边资壮略，披坚敌阵表彤弓。","升平当惜老臣在，竹帛还酬旧日功。","白首怡神存硕果，愿期添算荷恩隆。"]},{"t":"赐将军吴英","f":"七言律诗","c":["水陆封疆六十年，曾经百战驾轻船。","蓬台远涉鲸鲵浪，岛屿全消烽火烟。","将老偏宜立志壮，宸襟每注施恩延。","波涛有作须先靖，黾勉防微计未然。"]},{"t":"冬至读易","f":"五言律诗","c":["复自纯坤起，阴阳由静生。","飞灰识地气，吹律考中声。","六甲周天运，九畴味道精。","非图穷理誉，本末近分明。"]},{"t":"黄腊梅","f":"七言绝句","c":["腊后江南得早梅，春迟北地见花开。","不随岸柳初眠候，祇伴寒松破冻回。"]},{"t":"赋得冬日可爱","f":"五言律诗","c":["复卦初生处，景随玉管回。","前旗分鸟道，后仗向龙堆。","爱日冬偏暖，临桥冰未开。","宽城行幸地，越岭少尘埃。"]},{"t":"咏雪","f":"五言律诗","c":["季秋封地雨，寒月减同云。","忽见峰头白，那看树杪雰。","众方矜藻缋，我独念耕耘。","未卜来朝庆，田畴积几分。"]},{"t":"赋得月照冰池","f":"五言律诗","c":["半璧映河隈，光瑩鉴溯洄。","源清同皎洁，溜静自徘徊。","远照移松岭，寒辉展镜台。","羊肠分岔路，飘渺碧云堆。"]},{"t":"吏部尚书引年致仕宋荦因朕六旬寿庆祝来京事毕五月内回本乡朕念旧臣特书七言律一首以纪其事云","f":"七言律诗","c":["受祉林泉颐养年，世家耆德自天全。","少时剑佩登三殿，久任吴淞抚九阡。","行俭铨衡有令誉，广平才藻入清篇。","修龄喜得人间寿，雪作须眉兴欲仙。"]},{"t":"赐大学士温达","f":"七言律诗","c":["自少存心敦孝友，中年芳誉畹兰清。","枢垣华省看封事，储粟经邦著政声。","三殿丝纶资作楫，九霄雨露启和羹。","君臣须发苍然矣，时念虞廷进善旌。"]},{"t":"几暇随笔书怀","f":"五言律诗","c":["云窗欲视远，启户北凭观。","岂若登山望，徒劳谱石看。","禅徒空世界，仙每误炉丹。","何似诗书蕴，常图根本安。"]},{"t":"五月上旬避暑热河涂中喜麦秋盈野雨旸得时赋七言一律","f":"七言律诗","c":["畏暑乘舆出凤城，麦秋预卜望庚晴。","千村共饱连年稔，万井同欢比屋盈。","谷有灵泉山脉壮，道无峻岭马蹄轻。","移风易俗先忠孝，蕃息编氓在厚生。"]},{"t":"夏日山庄 其一","f":"五言律诗","c":["日永炎风盛，纯阴在内含。","扶阳求物理，避暑岂幽探。","山静清歊热，泉潆照碧岚。","随时驻步辇，无著亦无贪。"]},{"t":"夏日山庄 其二","f":"五言律诗","c":["畏景消烦虑，吟诗续古风。","野花罗槛外，山鸟满林中。","云气氤氲合，莺鸣飒爽同。","无能寻丽句，赋物愧难工。"]},{"t":"金莲盛放 其一","f":"七言绝句","c":["曾观贝叶志金莲，再见清凉遍地鲜。","近日山房栽植茂，参差高下共争妍。"]},{"t":"金莲盛放 其二","f":"七言绝句","c":["数亩金莲万朵黄，凌晨浥露色辉煌。","薰风拂槛清波映，并作芙蕖满院香。"]},{"t":"赋得山林引兴长","f":"五言律诗","c":["曾读杜诗解，纷纷议论多。","遇时非泰运，行道至蹉跎。","托迹山林趣，披怀水石歌。","千年赋比兴，后世岂能过。"]},{"t":"咏夏 其一","f":"七言绝句","c":["甘泉日永秩南讹，清气重云入句多。","性理精研过盛夏，岂因白首废编摩。"]},{"t":"咏夏 其二","f":"七言绝句","c":["信风已尽接朱明，长养舂容草木亨。","漱露调冰消暑气，何如心静则神清。"]},{"t":"咏新竹","f":"七言绝句","c":["丛阴半亩润新篁，花气缤纷伴竹香。","可爱霏微昨夜雨，檐前风响趁苍筤。"]},{"t":"热河产人参虽不及辽左枝叶皆同命翰林蒋廷锡画图因戏作七言截句记之","f":"七言绝句","c":["旧传补气为神草，近日庸医误地精。","五叶五枝成洛数，顺时当用在权衡。"]},{"t":"兰菊图","f":"五言律诗","c":["尺楮绘秋容，搜寻墨淡浓。","丹青偏绰约，锦绣杂䒠茸。","意运含毫手，神生应矩胸。","自分枝向背，形影入芳踪。"]},{"t":"莲花岩松牡丹","f":"五言律诗","c":["离宫初雨后，花气满天街。","石壁流泉响，松坪古干佳。","香凝金掌露，名重玉盘钗。","静里经声息，方知道有涯。"]},{"t":"嘉禾双颖","f":"五言律诗","c":["夜雨初晴日，素商驱暑天。","林红变绿叶，谷熟卜丰年。","勿讶嘉禾瑞，须知贵粟先。","秋成各地异，大有再书篇。"]},{"t":"涌翠岩观瀑赏白莲","f":"七言律诗","c":["毕竟天然造化功，方能巧设古今同。","喷云百尺穿岩石，瀑水千层点药丛。","波涌白莲承晓露，溪浮绿盖动香风。","经声似脱红尘外，泡影依稀宇宙中。"]},{"t":"梨树峪道中步辇口占 其一","f":"七言绝句","c":["入峪桥分三岔路，傍崖步辇景何深。","山中独见松林影，时有清流助鼓琴。"]},{"t":"梨树峪道中步辇口占 其二","f":"七言绝句","c":["一溪展转见山花，步步石苔杨柳斜。","试看目前将熟果，青榛郁李并堪誇。"]},{"t":"云岩","f":"七言绝句","c":["三庚不用碧筒酒，九井何贪消暑珠。","自有云峰来澍雨，巉岩风飒到茅庐。"]},{"t":"山居即事","f":"七言绝句","c":["清商方至催蝉急，林叶吟风暑渐遥。","三伏炎蒸才过半，山居遍地喜禾苗。"]},{"t":"览孝经衍义有感而作","f":"五言古诗","c":["孝友乾坤蕴，彝伦宇宙开。","无违遵制礼，色养勉循陔。","风木追前事，春秋思表哀。","欢心从博爱，锡类育英才。","恶慢须防过，骄危诫取灾。","教原由匪懈，德本足兼该。","不敬有何别，存诚自可推。","始终劝兴行，经义日昭回。"]},{"t":"用梌木杯器","f":"五言律诗","c":["素轻珠玉器，专制及时杯。","错节分花影，盘根别利才。","茂林成木瘿，深谷染莓苔。","澹泊明吾志，天然见体裁。"]},{"t":"春行","f":"古风","c":["千红艳，万紫鲜，频催须鬓方寸悬。","桃火柳烟恐荡志，吟风弄月禁狂颠。","案牍惟勤被景牵，逢春又恶斗芳妍。","礼乐诗书海岳编，进德修业须钻研。","昙云寂灭沦王道，老氏无为徒苟延。","致知端赖格物先，次第由来性理篇。","性理无私天地宣，太极乾坤未画前。","敬承执中授受远，勿替心传思永年。"]},{"t":"去岁八九月雨最多民间俗说封地雨故一冬少雪犹可支持自交立春复不见云所以望雨甚殷昨晚密云四起夜深甘霖即霈田间老幼无不举手加额欢声载道朕以民食为天喜均一体故赋七言近体以示群臣","f":"七言律诗","c":["吟咏由来喜雨多，久晴喜雨更如何。","天心即是民心感，海甸应同畿甸歌。","立政刚柔符造化，体仁宽裕得人和。","两间物理原难尽，勿入浮诗曲士科。"]},{"t":"春行","f":"七言绝句","c":["爱此融融养育多，平原高下识恩波。","虽然迅速春难住，四季何尝离太和。"]},{"t":"柳絮","f":"古风","c":["御苑春将尽，和风鼓物生。","芸窗来淑气，丹陛奏清声。","眠柳垂青?，流莺啭碧泓。","沾泥非有意，高下点蓬瀛。"]},{"t":"清潭","f":"七言律诗","c":["一潭清冷拂游尘，活水源头可问津。","静处定知无复浪，动时须认养潜鳞。","临流能解薰风意，对景先愁涝雨频。","云影波光相映处，湛然澄澈见天真。"]},{"t":"读朱子全书有感而作","f":"七言律诗","c":["降衷天命同仁性，气质多偏亦有全。","人十已千知自勉，参三列九授师传。","直方表里须涵养，朝夕云为在惕乾。","喻道程朱明尽善，正心穷理溯渊渊。"]},{"t":"暑将退","f":"七言律诗","c":["歊蒸少退解烦忧，白发苍颜万里愁。","触物方知开造化，閒来更觉有源流。","倒垂树影河边水，悬挂波声岸上楼。","分外并无着意处，惟将周易静中求。"]},{"t":"浙闽总督范时崇陛见来京朕每念祖为开创宰辅父乃忠义名臣所以待之优重今因回任特书御诗饯送","f":"七言律诗","c":["翼唐九佐开天命，论道三台识国桢。","握管表章文学馆，持忠坚保岁寒名。","栋梁祖干家声重，兰桂孙枝令誉清。","浙闽封疆慎抚育，惟期宁静勉精诚。"]},{"t":"古北口提督马进良以年老辞去朕念当日鹰扬百战挽强执锐自守紫塞内外恬静皆因宿将老成之所致今回林泉深所惜也故赋五言特记不忘疆场旧事也","f":"五言律诗","c":["勇贯先锋气，鹰扬后阵威。","秦关提宝剑，沙碛历天旗。","白发秋霜肃，丹心皎日辉。","饯饮军民别，恩崇赐御衣。"]},{"t":"赋得万壑泉消夏千峰翠作秋","f":"五言古诗","c":["白藏新素节，碧涧洗心泉。","爽籁鸣楸叶，纤云罩野田。","鸿飞横峻岭，鹤舞爱平川。","见雨心愁潦，闻旸意省愆。","西成登瑞谷，南亩庆丰年。","远近无殊别，盈虚有后先。","桑榆怀壮志，吟咏借瑶篇。","生理随时发，渊衷重体乾。"]},{"t":"大西门升八旗官阅骑射作","f":"五言律诗","c":["骑射为观德，从来旧制存。","久安惜将老，长治厌兵繁。","训练虽成法，忠贞实本原。","先知亲上义，不必问私恩。"]},{"t":"江南诸臣","f":"七言律诗","c":["廿载安澜自有因，河干临幸至于频。","白首常思善后策，青畴每念力农晨。","移风实赖封疆吏，化俗无劳专事臣。","吴越山川犹在目，虽忘多景不忘民。"]},{"t":"灵泉启文明","f":"五言律诗","c":["节应黄钟律，阳生复卦前。","烈风催短鬓，暖溜益稀年。","梅候宫中树，诗成几上笺。","乾坤先后画，至理在精研。"]},{"t":"赋得恩光日边来","f":"五言律诗","c":["冬藏待春发，艮止佐东生。","八极分仁政，诸方拱向明。","车书同内外，民物望丰亨。","敬奉无私义，殷勤宵旰情。"]},{"t":"五十三年冬至斋戒作","f":"七言律诗","c":["姤复生生已浑同，不因小往大来中。","箫韶如在精诚致，钟鼓云乎礼乐崇。","日月无私能广运，圣贤有教佐天功。","老年岂惜衰残力，强欲躬行尽㓗衷。"]},{"t":"五十三年冬旱十二月初二日大雪二十一日又雪途中偶成","f":"七言律诗","c":["玉花泱漭近春和，步辇平明回陌过。","村老凭门吟里曲，行人载道咏寒歌。","无尘远视山横塞，破冻齐驱马渡河。","盈尺王畿皆作瑞，龙沙惟虑雪霜多。"]},{"t":"赋得梅候宫中树","f":"五言律诗","c":["积雪梅犹冷，春寒竹色沉。","占年勤远虑，恶酒自高吟。","忧乐同民切，诗书味道深。","光风来锦甸，生养见天心。"]},{"t":"赋得三十六宫都是春","f":"七言律诗","c":["四时观物视韦篇，奥旨微言开画前。","月窟天根来往处，地雷乾巽互环旋。","青阳和煦为春首，淑日依迟作道筌。","运转洪钧推造化，体元善政在身先。"]},{"t":"日月无私能广运","f":"七言律诗","c":["春寒暗解消冰势，膏澍新添助发生。","绣壤已看随处润，柴扉共乐及时耕。","运筹普被群黎广，宵旰先思积粟盈。","每览前村童叟悦，枫宸少慰白须情。"]},{"t":"春日郊行示地方官 其一","f":"五言绝句","c":["警跸幸畿南，中和慰闾里。","千村静路尘，淑气遍远迩。"]},{"t":"春日郊行示地方官 其二","f":"五言绝句","c":["每春来此地，黎庶尽安康。","尚德先宽政，官僚勉直方。"]},{"t":"春日郊行示地方官 其三","f":"五言绝句","c":["春蒐省耕种，莫误农桑时。","假寐羹墙睹，殷勤意在兹。"]},{"t":"春日郊行示地方官 其四","f":"五言绝句","c":["牧民寄所重，授钺赖宣风。","曩昔官箴在，开诚上下同。"]},{"t":"春日郊行示地方官 其五","f":"五言绝句","c":["平成多历年，生齿既蕃庶。","惟食在天时，轻徭民自豫。"]},{"t":"春日郊行示地方官 其六","f":"五言绝句","c":["案读五经义，遐观四海图。","缅怀洙泗训，期共乐天衢。"]},{"t":"舟中鼓琴","f":"五言律诗","c":["蓬窗听绿绮，月影映船遥。","静里宫商别，风前律吕调。","雁飞遥集渚，鱼跃欲乘潮。","雨歇苔犹湿，应知助麦苗。"]},{"t":"和风细雨","f":"五言律诗","c":["春潭连霢霂，沙岸泊轻舟。","鸭绿苔痕静，人閒载酒游。","风帆通野望，雨气杂清流。","怀保先农事，观耕凤跸留。"]},{"t":"望湖春色 其一","f":"七言绝句","c":["极目平波心水同，烟添媚景日曈昽。","湖边淑色年年有，似我澄怀数省躬。"]},{"t":"望湖春色 其二","f":"七言绝句","c":["倚槛平明对草庐，溪滨来往隐樵渔。","虽然九五乘乾位，山水幽情自卷舒。"]},{"t":"舟中观耕种","f":"七言绝句","c":["四野春耕阡陌安，徐牵密缆望河干。","土肥原系黄沙过，辛苦先年挽异澜。"]},{"t":"春归","f":"五言律诗","c":["勿讶春归速，还因冷觉迟。","烟寒榆荚落，雨逐柳黄移。","惜景勤经学，怡情喜恊时。","惠风虽曰尽，长养已相随。"]},{"t":"南方青竹丛林不乏观玩北地气寒非保护得宜即难艺植朕尝有事河干往来数次览竹树之畅茂暂时停辇即行后于禁苑种植颇蕃今经三十馀年迩来延至数亩之广其围至八寸径二寸五分有零古人以竹比君子因而思及草木无知积小以至于高大人有血气加之培养岂非国家桢干之选欤故赋七言一律记之","f":"七言律诗","c":["培养丛篁多历年，竹窗抱节绿云鲜。","猗猗玉润歌君子，济济心虚忆俊贤。","可爱缤纷含宿雨，最宜潇洒动新烟。","馀春欲伴寒松住，渐晚韶光被景牵。"]},{"t":"五十四年仲夏避暑途中瑞麦盈野赋五言律以记","f":"五言律诗","c":["忽送清尘雨，题诗吮兔毫。","青黄接玉粒，霢霂佐琼膏。","入野农歌遍，缘溪牧笛高。","蔚林能解愠，密草满亭皋。"]},{"t":"每见村农野老不识不知天然自得孝弟发于至性朴诚不事文辞故美其实而取先进之意赋七言一律","f":"七言律诗","c":["昼夜徬徨利禄间，奚如鄙里野人閒。","诗书不解穷通事，名姓无闻士宦班。","孔颜乐处箪瓢在，孝弟真情稚子关。","可笑文章少实据，空将浮伪玷青纶。"]},{"t":"鹧鸪天 擎盖荷珠","f":"古风","c":["数亩芳塘花未开。","荷珠清露落莓苔。","雨凉翡翠摇歌扇，风弄蜻蜓逐水隈。","乳燕舞，晓莺来。","炎天还似未春回。","葛衣日暮丝丝冷，丹槛泉声处处催。"]},{"t":"雨后戏题回文诗","f":"七言绝句","c":["云收晓景霁烟开，曲槛香凝露染苔。","分径花光清气爽，纷纷雨思绮文裁。"]},{"t":"佛手柑","f":"七言律诗","c":["生绿熟黄却有因，清香闽峤共呈珍。","似开贝叶瞿昙手，妙合华阴仙掌垠。","异物不须传驿路，奇芬欣得近枫宸。","画图尺素分枝干，相对无烦忆海滨。"]},{"t":"赋得江城五月落梅花","f":"七言绝句","c":["梅花一调楚江干，吹彻潇湘五月寒。","地北天南无谪叟，不教羁思入毫端。"]},{"t":"芝径云堤细雨归舟","f":"七言律诗","c":["长堤一线入芝径，小艇乘凉隔岸移。","水向方桥潆细浪，风吹菡萏倒垂枝。","秋成已庆年丰兆，暑尽无忧云汉诗。","遗事陈瓜为七夕，偶因佳节赋清辞。"]},{"t":"题兰","f":"古风","c":["君子之道，闇然日章。","蕙兰之质，有风则香。","草木培植，格物知详。","飞潜动静，各有攸藏。","秉精天地，青紫芬芳。","产自松岛，移根草堂。"]},{"t":"咏剪秋罗","f":"七言绝句","c":["可惜轻罗任剪裁，名传南国向秋开。","未知紫塞多佳种，杂置嫣红配绿苔。"]},{"t":"饯大学士李光地暂回闽省","f":"七言律诗","c":["恊恭惟得老成儒，味道经书翊庙谟。","白发辞君千里去，丹心捧日寸诚敷。","秋霜昔岁明臣节，昆玉冲襟决胜符。","暂别恩荣宸翰饯，勿劳远念慰长途。"]},{"t":"秋幸出郊见收成志喜 其一","f":"五言律诗","c":["节届商秋早，农忙屡岁丰。","柴门歌再稔，比屋乐同风。","人烟多庆色，霜树杂微红。","极目高低景，山川一望中。"]},{"t":"秋幸出郊见收成志喜 其二","f":"五言律诗","c":["涤暑高风至，中分白露微。","草肥宜牧马，林薄好行围。","水向阶前注，峰排云外稀。","斜阳临帐殿，晚色秘天机。"]},{"t":"赋得帐殿郁崔嵬 其一","f":"五言律诗","c":["茂林叶未黄，宾雁始成行。","后队分山出，前旌越岭扬。","鹿鸣秋草盛，人喜菊花香。","日暮帷宫近，风高暑气藏。"]},{"t":"赋得帐殿郁崔嵬 其二","f":"五言律诗","c":["清露知时转，纤云却暑回。","豫游临石磴，杂踏过河隈。","潭静鱼吹沫，林疏鹿印苔。","秋成良可赋，为此共徘徊。"]},{"t":"康熙五十四年十月初三日避暑山庄恭祝皇太后万寿诗","f":"五言古诗","c":["诞值小春暖，承颜爱日长。","农閒歌乐土，臣喜拜山堂。","孟月祈年节，芳卮献寿觞。","南峰留翠盖，北斗灿珠行。","愉色常犹怯，怡声久未忘。","欢心依白发，福曜现青方。","至养慈闱庆，遐龄母德昌。","虚文岂作颂，人瑞纪篇章。"]},{"t":"冬日可爱","f":"七言律诗","c":["秋敛冬藏暗发生，循环潜应有馀情。","扶阳布序君人志，爱日书云宇宙明。","长至免行丹陛礼，融风不设玉厨羹。","化醇意切惭凉德，渐喜春和万物荣。"]},{"t":"冬夜偶成 其一","f":"七言绝句","c":["隆冬何必辟寒犀，惟有苍颜性不迷。","玉律回环新故接，釭花夜永卷中题。"]},{"t":"冬夜偶成 其二","f":"七言绝句","c":["安危最系在君心，待旦殷勤化理寻。","鹤发多愁犹警惕，长思时弊若临深。"]},{"t":"季冬汤泉","f":"七言律诗","c":["素雪满川山未露，霜林盈野日将斜。","祈年正喜逢长至，澡德非同玩物华。","秉烛检书冬夕永，爇香待旦画屏遮。","灵泉每助消寒效，总为纯阳辨正邪。"]},{"t":"五十四年除夕偶成","f":"五言律诗","c":["待曙迎新节，辞寒忆旧时。","风光忽瞬息，岁月急星驰。","少小劳宵旰，中年按古规。","精力虽云惫，衷肠坚不移。"]},{"t":"康熙五十五年正月元旦书怀","f":"七言律诗","c":["乍回斗柄又芳晨，端月元阳万象新。","竹叶向风消积雪，梅花除腊报初春。","彤庭启节迎祥始，邃阁兴文起草频。","每绎晦翁真乐处，早知天意即生民。"]},{"t":"上元前三日立春","f":"七言律诗","c":["腊寒犹接上元灯，窗外参差六出凝。","媚景新春催玉律，惠风活水破蛟冰。","殷勤祈谷宁辞瘁，勉强雕虫愧未能。","九陌人烟多喜色，千门比户望年登。"]},{"t":"五十五年正月十二癸卯立春是日风从东北而至景云密布瑞雪铺地至十三日未止书云立春与元日同占乃收成之兆故喜民有足食之庆朕慰宵旰之忧赋五言排律以记其事","f":"五言古诗","c":["问夜何尝歇，殷勤六十年。","岁华催短鬓，寸晷惜担肩。","丰歉无推数，平成在事先。","人安为国瑞，谷熟是民天。","惭抚陶甄治，思将法令蠲。","云浓春气早，风静漏声传。","南陌银花遍，东郊绣壤连。","管弦喧里巷，灯火接山川。","不为私情扰，宁耽宝馔延。","祗期民俗厚，敢诩治功全。","礼让传家教，诗书戒往愆。","翠烟笼畎亩，泛泛润桑田。"]},{"t":"春寒梅迟","f":"七言律诗","c":["化工节候递推移，长养生生雨露垂。","雪冷梅惊频吐萼，春迟柳怯未飏丝。","阳禽北向还应早，林雀群争若有知。","和气停云今夕晚，走桥明月赋新词。"]},{"t":"汤泉道上遇雪口占","f":"七言绝句","c":["种麦田间盼尺盈，牧羊沙漠恶飘霙。","王臣率土分忧乐，莫道天公有不平。"]},{"t":"春风扇微和 其一","f":"五言绝句","c":["雪消山露背，泉暖日暄波。","荡涤甘言疾，澄清无妄疴。"]},{"t":"春风扇微和 其二","f":"五言绝句","c":["淑气来春甸，和风慰悯农。","东郊滋土润，云尽显诸峰。"]},{"t":"题朱伦瀚手指画雪梅竹二首 其一","f":"七言绝句","c":["指端写出犯寒梅，老干单枝雪里培。","疑是江南春色晚，红芳遍野点青苔。"]},{"t":"题朱伦瀚手指画雪梅竹二首 其二","f":"五言绝句","c":["雪覆石林竹，时催腊尽梅。","閒云飘远岫，长对翠屏开。"]},{"t":"两广总督赵宏灿陛见来京","f":"七言古诗","c":["镇抚封疆多历年，滇黔百粤凯归鞯。","当时马革抒诚切，近日龙光锡庆绵。","万里宣风梅岭表，三台拥节桂江边。"]},{"t":"优隆主眷酬耆旧芸阁宸章赐绮筵赋得二月春风似剪刀","f":"七言律诗","c":["春居别墅少人喧，煦育深知造化恩。","雪净梅花舒绿萼，霜轻柳带拂朱垣。","和风宇宙严寒解，暖日亭皋物色繁。","无欲自然得静理，丹颜已过白须存。"]},{"t":"春日即事","f":"七言律诗","c":["最盛芳春育物多，仲阳孳茂野烟和。","岂辞宵旰求民隐，益守平成免赋苛。","望杏敦耕迎淑气，瞻蒲劝稼播嘉禾。","中畴社鼓声相应，敷惠元元载路歌。"]},{"t":"晓发芦沟","f":"七言绝句","c":["有闰春深淑景迟，长桥冰泮未流澌。","徘徊风景思畴昔，千里金堤保旧规。"]},{"t":"六里桥铁柱","f":"七言绝句","c":["镕垆铸冶镇桥西，往返行人旧迹迷。","世远传殊谁识得，天南铜柱想应齐。"]},{"t":"水村","f":"七言律诗","c":["曾记江淮泊万艘，便旋水淀暂春游。","虽无浩渺长波壮，亦有清漪锦浪浮。","日暮帆樯排远岸，风轻蓑笠聚芳洲。","乡村不识居官况，漫笑朝堂身世忧。"]},{"t":"春水满四泽","f":"五言律诗","c":["条风拂春水，碧涨绕烟岑。","梅萼先知暖，林梢渐覆阴。","柳舒鸣好鸟，渚静习时禽。","韶景融和处，潜窥造化心。"]},{"t":"舟中观猎","f":"古风","c":["习战昆明汉武穿，于今江海靖鲸烟。","常思远涉坚筋骨，每令平流演猎船。","雁阵惊鎗离复合，鸥群畏弩?还连。","衰年虽乏挽强力，黾勉春蒐以德先。"]},{"t":"仲春闻雁","f":"古风","c":["渐喜春和踏草行，郊原遥听曙鸡鸣。","宾鸿欲向银湾渚，社燕方栖静舍楹。","已觉阴消馀雪?，争看阳长早潮生。","省耕畿辅先群吏，留憩田间夜不惊。"]},{"t":"阅永定河堤","f":"七言律诗","c":["豫定安澜在事前，每逢雨潦自心牵。","帑金不惜筹耕种，膏土惟思广陌阡。","堤老失防愁剥蚀，岸坚常护幸安全。","肩舆频视桃花水，滚滚浑波通碧涟。"]},{"t":"络纬养至暮春","f":"五言律诗","c":["秋深厌聒耳，今得锦囊盛。","经腊鸣香阁，逢春接玉笙。","物微宜护惜，事渺亦均平。","造化虽流转，安然比养生。"]},{"t":"五十五年三月下旬园中桃杏玉兰梅花齐放其中玉兰茂盛可观特请皇太后一阅","f":"七言律诗","c":["玉花万朵祝慈颜，藉奉欢心半日閒。","闰月春迟添岁永，香枝风送待时还。","膝前五代承王母，陛下千龄献寿山。","乍晓铜龙迎凤辇，霜容天上睹仙鬟。"]},{"t":"去岁三冬有雪至三月间农忙之际二十七日夜雨竟夕喜而成咏","f":"五言律诗","c":["滋麦如酥雨，空濛入土膏。","心同黎庶苦，目盼紫坛高。","任器已知重，安人宁避劳。","春愁暂且释，点点付挥毫。"]},{"t":"赋得陇麦","f":"五言律诗","c":["节迟谷雨后，田麦始分畦。","已送花开尽，难将春事稽。","纯阳时序近，馀闰化成齐。","未卜阴晴适，先期辑庶黎。"]},{"t":"五十五年冬谒陵作","f":"七言律诗","c":["拜奉山陵泪两垂，提携鞠育赖仁慈。","松林转盛青如许，鬓发劳伤白所宜。","屈指多年思慕永，深惭暮景远来迟。","珠邱玉殿依然觐，悲想音容寸晷移。"]},{"t":"春幸","f":"七言律诗","c":["载阳节候爱春和，宾日中衡社后过。","东作勤耕劳众力，西成有穫广农科。","官箴先戒关河固，节钺曾经岁月多。","正已清心倡庶吏，宣恩莫使政烦苛。"]},{"t":"风阻驻跸白洋湖偶成","f":"七言绝句","c":["平波数顷似江声，风阻湖边一日程。","可笑当年巡幸远，依稀吴越列行营。"]},{"t":"小满后偶旱涂中祈雨四月二十三日甘霖大霈","f":"七言律诗","c":["夙夜愁怀春夏间，天时难信未怡颜。","平原晚麦纤茎槁，四野新禾旱色殷。","乍起云光连岭岫，先垂雨脚遍人寰。","共沾甘澍敷膏泽，民食方知稼穑艰。"]},{"t":"晚夏偶成","f":"五言律诗","c":["青榛方作粒，郁李渐微红。","草药迷香径，荷花待晚风。","莫愁秋雨近，且望岁时丰。","倚槛频观稼，银须一老翁。"]},{"t":"忆扬州天宁寺竹","f":"七言律诗","c":["久别金焦十一年，依稀寒暑递推迁。","此君有意虚心待，叹我徒劳幽思牵。","雁逐西风何处问，云回北地竟谁传。","翠筠晚节饶苍箨，远寄宸章梵宇前。"]},{"t":"七月十六日赐九十一岁老和尚","f":"七言律诗","c":["暑退全消陌上尘，盂兰大喜见姚秦。","临风洗钵龙池雨，凝露舒莲鹫岭春。","送节双轮同梦幻，持心半偈见深淳。","循环已识盈虚理，不向山僧更问津。"]},{"t":"题画","f":"七言绝句","c":["杖藜端不染轻尘，野趣天然景物新。","春水风帆一目尽，孰知逝者太华津。"]},{"t":"泽卜尊丹巴胡土克图老喇嘛上寿","f":"七言律诗","c":["想像当年论转轮，龙沙遥隔十馀春。","相知惟有菩提行，得解尝闻秘密真。","花雨频施铺佛帐，贝经每祝上枫宸。","眉横鼻竖长松寿，导引众生善后因。"]},{"t":"未开新荷","f":"七言绝句","c":["清和将尽未端阳，时雨催擎珠点凉。","不染淤泥看净植，虽无花气叶先香。"]},{"t":"戏题千里眼","f":"五言律诗","c":["欲穷视远目，旷渺有无中。","体认全凭准，遐观约略同。","虽依双镜力，独用一瞳功。","不重西来巧，清明本在躬。"]},{"t":"赐松江提督赵珀","f":"七言律诗","c":["忆昔云间山水邦，波流清润抵松江。","春秋久未临銮辂，时刻尝怀拥节幢。","训练多方娴步伐，抚循成俗重敦庞。","建牙好慰军民望，服众投醪士气降。"]},{"t":"绿金莲花","f":"七言绝句","c":["牡丹有绿诚仙品，幻色生香野草中。","数朵乍开凝碧玉，黄花应逊碧花丛。"]},{"t":"赐老大臣","f":"七言律诗","c":["旧日讲筵剩几人，徒伤老朽并君臣。","平生壮志衰如许，诸事灰心懒逼真。","求简逡巡多恍惚，遇烦留滞累精神。","年来词赋荒疏久，觅句深惭笔有尘。"]},{"t":"苏州巡抚吴存礼","f":"七言绝句","c":["曾记临吴十二年，文风人杰并堪传。","予怀常念穷黎困，勉尔勤箴官吏贤。"]},{"t":"山庄四季 其一","f":"五言绝句","c":["节届三春胜，发生万汇齐。","诸花候御辇，百谷待村犁。"]},{"t":"山庄四季 其二","f":"五言绝句","c":["九夏愁旸雨，千林叶正肥。","秪因思避暑，端拱计频违。"]},{"t":"山庄四季 其三","f":"五言绝句","c":["金风多爽䬃，清露滴烟浮。","目睹仓箱满，方知岁有秋。"]},{"t":"山庄四季 其四","f":"五言绝句","c":["岁暮添霜鬓，殷勤宵旰劳。","地寒盈尺雪，还虑北风高。"]},{"t":"冬至不能全礼","f":"七言律诗","c":["老残多阻诣圜丘，一念精诚或解忧。","愆过常思天每鉴，衰颓恒觉自难由。","无心成化无私覆，不息流行不显求。","瞻拜洪钧斩礼缺，书云颙望太平秋。"]},{"t":"千叟宴","f":"七言律诗","c":["百里山川积素妍，古稀白发会琼筵。","还须尚齿勿尊爵，且向长眉拜瑞年。","莫讶君臣同健壮，愿偕亿兆共昌延。","万几惟我无休暇，七十衰龄未歇肩。"]},{"t":"题新安道上","f":"七言律诗","c":["满目平川映远空，身形少健一衰翁。","社前荷锸争春暖，陇畔扶犁趁晚风。","雨泽深邀天地德，耕桑还赖穑人功。","京南每出同村叟，总得阳和一气中。"]},{"t":"示平藏将士","f":"七言绝句","c":["去年藏里凯歌回，丹陛今朝宴赏陪。","万里辛勤瞬息过，欢声载道似春雷。"]},{"t":"六十一年春斋戒书","f":"五言古诗","c":["性理参天地，经书辅国朝。","勿劳民力尽，莫使俗氛嚣。","不误农桑事，须轻内外徭。","风高林鸟静，雨足路尘消。","视察焉能隐，行藏岂可摇。","桑榆虽景暮，松柏后霜凋。","长养春容盛，宽严君德调。","倦勤应不免，对越愧明昭。"]},{"t":"园中无处无花触目皆是故作此自嘲","f":"七言绝句","c":["无花无酒亦氤氲，况有清香到处闻。","万紫千红虽瞬息，古稀吟咏忘辛勤。"]},{"t":"端阳","f":"七言绝句","c":["春夏连年旱魃灾，虽逢令节免流杯。","清和幸得甘霖霈，竞渡蒲樽览一回。"]},{"t":"久旱无雨夙夜徬徨夏至前方得普沾","f":"五言律诗","c":["喜雨虽云快，岂无久旱由。","望云待旦起，问夜数更愁。","霹雳偏稽候，风霾任作尤。","西成登谷后，方慰悯农忧。"]},{"t":"避雨闻钟","f":"七言绝句","c":["雨阻端阳涌翠隈，荷香瀑水点新苔。","午钟忽送昙花曲，那得閒心笑几回。"]},{"t":"同老侍卫","f":"五言律诗","c":["庞眉经岁月，忆昔旧人稀。","少小儿童戏，年高亲故违。","叹无手足力，偏有友朋讥。","膝下曾孙事，怡情待晚晖。"]},{"t":"佛桑花","f":"七言绝句","c":["木槿层楼号佛桑，新移远道爱芬芳。","开时先占榴花艳，留日还同菊蕊香。"]},{"t":"京中报到霖雨普沾","f":"五言律诗","c":["亢阳愁久旱，霖雨满沟渠。","倏忽枯枝润，须臾卷叶舒。","千村勤袯襫，万顷促犁锄。","企望收成后，欣看谷贱书。"]},{"t":"夏至","f":"五言律诗","c":["山庄逢夏至，斋戒禁中同。","翠渚萍先绿，荷池花未红。","葛衣求体便，蔬食养心功。","偶得因几暇，偷閒碧树丛。"]},{"t":"山庄晚眺","f":"五言律诗","c":["岛屿堪图画，溪桥宛自成。","池边树影接，峰外月华生。","众鸟巢檐稳，群獐伏地平。","无知知德化，推扩至民情。"]},{"t":"登四面云山","f":"七言绝句","c":["云梯石磴逼巃嵷，倚杖傍观众壑同。","更上一层图远望，奈何树杂与烟笼。"]},{"t":"夏日山庄百花齐放","f":"七言绝句","c":["咫尺雄关一线墙，景风已拂尚芬芳。","近都爱此清凉地，逢草逢花莫不香。"]},{"t":"题山水画","f":"七言律诗","c":["岭岫嵚崎路渺茫，画工摹写各舒长。","云峰四起添山色，竹树重阴致夏凉。","最爱萧疏随意笔，可称流动赏心方。","依稀岩洞神仙住，那得閒情问草堂。"]},{"t":"山中自咏","f":"七言律诗","c":["一生何事不斟量，老至偷閒自可伤。","倦体每思依石憩，俗情且喜对山忘。","舂容无计寻方便，荏苒谁能驻景光。","濯足沧浪清水在，企思归咏舞雩傍。"]},{"t":"山居","f":"七言律诗","c":["迎薰避暑驻山庄，四顾重重丘壑长。","雨后雏莺歌密树，风前练雀舞斜廊。","静观得趣无非景，佳兴涵虚可致凉。","烹茗汲泉清意味，个中谁解有真香。"]},{"t":"戏作回文","f":"古风","c":["年丰足雨和时，谷贱家家展眉。","专意民安物阜，先为德广恩施。"]},{"t":"题画","f":"七言绝句","c":["敞怀潇洒驭风仙，散虑逍遥不记年。","名利牵情忙若辈，方知忧乐岂兼全。"]},{"t":"早御稻","f":"七言绝句","c":["紫芒半顷绿阴阴，最爱先时御稻深。","若使炎方多广布，可能两次见秧针。"]},{"t":"题画","f":"七言绝句","c":["隔溪隐隐见窗纱，几度呼童问酒家。","尺幅林峦分远近，画工浓淡最堪誇。"]},{"t":"挽总督赵宏燮","f":"七言律诗","c":["四十馀年抚近京，旗民称善政和平。","保全终始君恩重，奄逝悲凉众涕盈。","不畏刁顽持法纪，久司锁钥务精明。","官方仍在归泉壤，节钺空悬揽辔情。"]},{"t":"自笑古稀","f":"五言律诗","c":["月宇启窗纱，身閒兴转赊。","庞眉临事暗，垂老厌人哗。","懒惰心惟静，精勤目已花。","临池惭手涩，无复竞龙蛇。"]},{"t":"立秋在六月","f":"五言律诗","c":["庚伏虽云尽，依然六月中。","歊蒸临水榭，溽暑望金风。","未变楸梧色，还舒菡萏红。","杖藜西顾意，数问奏边功。"]},{"t":"忆陜西 其一","f":"七言律诗","c":["长安城阙昔曾游，黄水名山宛在眸。","清渭东流流自在，阳关远去去何休。","民稠地险人难化，谷贱年丰信有收。","衰老无能再一览，缅怀西顾愈添愁。"]},{"t":"忆陜西 其二","f":"七言律诗","c":["秦岭河西风俗淳，尚馀刚劲气难驯。","宽严相济毋偏执，教养兼施在体仁。","官久每闻滋反覆，吏新未晓作陶甄。","小诗自觉乏文丽，可尽衷肠对士民。"]},{"t":"月来香","f":"七言绝句","c":["月色东升候晚明，金风初到吐芳英。","忽闻香扑纱帷近，更觉游仙梦转清。"]},{"t":"膳酒自述","f":"七言律诗","c":["盈馀休说帝王家，俭朴身先务戒奢。","盛馔醇醲应有损，野蔬风味亦堪嘉。","樽中旨酒无能饮，案上珍肴勿过加。","淡泊宁心和五味，养身得正胜丹砂。"]},{"t":"树叶扇","f":"五言绝句","c":["叶绿存生气，香清却暑风。","轻摇能夏爽，巧制见人工。"]},{"t":"恶繁华","f":"七言绝句","c":["村野无知太古风，心依先进是吾衷。","不须问到繁华乐，愿与生民溯受中。"]},{"t":"书怀","f":"七言绝句","c":["不逮精神老愈愁，银须鹤发更何求。","艰难世事危心力，履薄临深岂自由。"]},{"t":"中元日同僧语","f":"七言绝句","c":["夙夜焦劳白发盈，愁肠一日几回萦。","偷閒暂向山僧话，可扫尘缘爱憎情。"]},{"t":"喜岭外水土","f":"七言绝句","c":["露凝肥草净无尘，处处泉源漾碧津。","食少事多宵旰老，暂偷閒暇养吾身。"]},{"t":"六十一年秋出哨","f":"五言古诗","c":["岁岁经行处，山川照旧时。","峰峦不改色，鬓发已如丝。","胜地清凉适，衰年水土宜。","非因耽逸豫，实借憩神思。","隔岭疑围阔，闻声呼鹿随。","归营常早歇，抚景自堪怡。","行伍原齐备，屏藩任指麾。","薄来厚往义，远近普恩施。"]},{"t":"回銮","f":"古风","c":["猎罢回銮塞冷时，旻天今岁落霜迟。","围人竞带甘肥脯，田叟争收高下?。","谷贱共知欣有食，物多须记守长规。","西成盈野仓箱满，关内依然是所思。"]}]};